import { createContext, useContext, useEffect, useState } from 'react'
import { useLocation } from 'react-router-dom'

const SidebarContext = createContext()

export function SidebarProvider({ children }) {
  const [opened, setOpened] = useState(false)

  const toggleSidebar = () => setOpened(prev => !prev)
  const closeSidebar = () => setOpened(false)

  const location = useLocation()

  // На мобильных и планшете (меню — оверлей) закрываем его при любой навигации.
  // На десктопе состояние не трогаем (там _opened = раскрытая панель без оверлея).
  useEffect(() => {
    if (window.innerWidth <= 1200) setOpened(false)
  }, [location])

  return (
    <SidebarContext.Provider value={{ opened, setOpened, toggleSidebar, closeSidebar }}>
      {children}
    </SidebarContext.Provider>
  )
}

export function useSidebar() {
  return useContext(SidebarContext)
}
