import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabase';
import { useAuth } from '../context/AuthContext';
import { getAuthReturnTo, readAuthFlow, endAuthFlow } from '../lib/DEF_DATA';
import './css/AuthCallback.css';

const TOTAL_TIMEOUT = 20000;     // hard limit for the whole callback
const PROFILE_WAIT = 2500;       // user without a profiles row: move on anyway
const SUCCESS_DELAY = 600;
const ERROR_DELAY = 4000;
const TICK = 200;

const MARKS = {
  pending: '·',
  active: '…',
  done: '✓',
  skipped: '—',
  failed: '✕',
};

const TITLES = {
  exchanging: { title: 'Авторизация...', hint: 'Получаем сессию' },
  loading: { title: 'Авторизация...', hint: 'Загружаем данные профиля' },
  success: { title: 'Авторизация завершена', hint: 'Возвращаемся на страницу' },
  error: { title: 'Ошибка авторизации', hint: 'Перенаправляем...' },
};

const CODE_TEXT = {
  active: 'обмен',
  done: 'получен',
  skipped: 'не требовался',
  failed: 'ошибка',
  pending: 'ожидание',
};

export default function AuthCallback() {
  const { user, profile, loadingDB, loadingServer } = useAuth();
  const navigate = useNavigate();

  const [stage, setStage] = useState('exchanging');
  const [codeState, setCodeState] = useState('active');
  const [errorAt, setErrorAt] = useState(null);
  const [details, setDetails] = useState('');
  const [email, setEmail] = useState('');
  const [elapsed, setElapsed] = useState(0);
  const [returnTo] = useState(() => getAuthReturnTo());
  const [provider] = useState(() => readAuthFlow().provider || 'google');

  const exchangeStartedRef = useRef(false);
  const deadlineRef = useRef(Date.now() + TOTAL_TIMEOUT);
  const startedAtRef = useRef(Date.now());

  const fail = (where, message) => {
    setErrorAt(where);
    setDetails(message || 'Неизвестная ошибка');
    setStage('error');
  };

  useEffect(() => {
    if (exchangeStartedRef.current) return;
    exchangeStartedRef.current = true;

    const urlParams = new URLSearchParams(window.location.search);
    const oauthError = urlParams.get('error_description') || urlParams.get('error');

    const cleanUrl = () => {
      window.history.replaceState({}, document.title, window.location.pathname);
    };

    if (oauthError) {
      cleanUrl();
      setCodeState('failed');
      fail('code', oauthError);
      return;
    }

    // С detectSessionInUrl: true сессия уже обменена автоматически на root.
    // Если сессии ещё нет — пробуем manual exchange (fallback для /auth/callback).
    const checkSession = async () => {
      const { data: existing } = await supabase.auth.getSession();
      if (existing?.session) {
        setEmail(existing.session.user?.email || '');
        setCodeState('skipped');
        setStage('loading');
        return;
      }
      // Fallback: manual exchange if code still present
      const code = urlParams.get('code');
      if (code) {
        try {
          const { data, error: exchangeError } = await supabase.auth.exchangeCodeForSession(code);
          cleanUrl();
          if (data?.session) {
            setEmail(data.session.user?.email || '');
            setCodeState('done');
            setStage('loading');
            return;
          }
        } catch (err) {
          // Code may have been consumed by auto-detect — session might be available now
          const { data: retry } = await supabase.auth.getSession();
          if (retry?.session) {
            setEmail(retry.session.user?.email || '');
            setCodeState('skipped');
            setStage('loading');
            return;
          }
        }
      }
      setCodeState('skipped');
      setStage('loading');
    };
    checkSession();
  }, []);

  useEffect(() => {
    if (stage !== 'loading') return;

    if (user && !email) setEmail(user.email || '');

    if (user && profile && !loadingDB && !loadingServer) {
      setStage('success');
      return;
    }

    if (!user) {
      const timeout = setTimeout(() => fail('session', 'Сессия не найдена'), PROFILE_WAIT);
      return () => clearTimeout(timeout);
    }

    const timeout = setTimeout(() => setStage('success'), PROFILE_WAIT);
    return () => clearTimeout(timeout);
  }, [stage, user, profile, loadingDB, loadingServer, email]);

  useEffect(() => {
    if (stage === 'success' || stage === 'error') return;
    const interval = setInterval(() => {
      setElapsed((Date.now() - startedAtRef.current) / 1000);
      if (Date.now() < deadlineRef.current) return;
      if (user) {
        setStage('success');
      } else {
        fail('session', 'Превышено время ожидания сессии');
      }
    }, TICK);
    return () => clearInterval(interval);
  }, [stage, user]);

  useEffect(() => {
    if (stage !== 'success' && stage !== 'error') return;
    const timeout = setTimeout(() => {
      endAuthFlow();
      // Клиентская навигация вместо window.location.replace:
      // статический билд (GitHub Pages и т.п.) не отдаёт глубокие пути,
      // а сюда нас может выбросить на любой маршрут с ?code= в URL.
      window.history.replaceState({}, document.title, window.location.pathname);
      navigate(returnTo, { replace: true });
    }, stage === 'success' ? SUCCESS_DELAY : ERROR_DELAY);
    return () => clearTimeout(timeout);
  }, [stage, returnTo, navigate]);

  const sessionDone = stage === 'success' || Boolean(user);
  const profileDone = stage === 'success' || Boolean(profile);

  const statusOf = (id) => {
    if (errorAt === id) return 'failed';
    if (stage === 'success') return 'done';
    if (stage === 'error') return 'pending';
    if (id === 'code') return codeState;
    if (id === 'session') {
      if (sessionDone) return 'done';
      return stage === 'loading' ? 'active' : 'pending';
    }
    if (id === 'profile') {
      if (profileDone) return 'done';
      return sessionDone ? 'active' : 'pending';
    }
    return 'pending';
  };

  const stepText = (id) => {
    const status = statusOf(id);
    if (id === 'code') return CODE_TEXT[status];
    if (id === 'session') return status === 'done' ? (email || 'получена') : (status === 'active' ? 'загрузка' : 'ожидание');
    if (id === 'profile') return status === 'done' ? 'загружен' : (status === 'active' ? 'загрузка' : 'ожидание');
    return stage === 'error' ? 'отмена' : returnTo;
  };

  const steps = [
    { id: 'code', label: 'Код доступа' },
    { id: 'session', label: 'Сессия' },
    { id: 'profile', label: 'Профиль' },
    { id: 'redirect', label: 'Возврат' },
  ];

  const passed = steps.filter((s) => ['done', 'skipped'].includes(statusOf(s.id))).length;
  const progress = stage === 'error' ? 100 : stage === 'success' ? 100 : Math.max((passed / steps.length) * 100, 5);
  const current = TITLES[stage];
  const titleClass = stage === 'success'
    ? 'auth-flow__title auth-flow__title--success'
    : stage === 'error'
      ? 'auth-flow__title auth-flow__title--error'
      : 'auth-flow__title';

  return (
    <div className="auth-flow">
      <div className="auth-flow__panel">
        <div className={titleClass}>{current.title}</div>
        <div className="auth-flow__subtitle">{current.hint}</div>

        <div className="auth-flow__bar">
          <div
            className={`auth-flow__bar-fill${stage === 'error' ? ' auth-flow__bar-fill--error' : ''}`}
            style={{ width: `${progress}%` }}
          />
        </div>

        <ul className="auth-flow__steps">
          {steps.map((step) => {
            const status = statusOf(step.id);
            return (
              <li key={step.id} className={`auth-flow__step auth-flow__step--${status}`}>
                <span className="auth-flow__mark">{MARKS[status]}</span>
                <span className="auth-flow__label">{step.label}</span>
                <span className="auth-flow__value">{stepText(step.id)}</span>
              </li>
            );
          })}
        </ul>

        {stage === 'error' && details && <div className="auth-flow__error">{details}</div>}

        <div className="auth-flow__meta">{`${provider} · ${elapsed.toFixed(1)} с · ${returnTo}`}</div>
      </div>
    </div>
  );
}
