import { createContext, useContext, useState } from 'react'

const AuthModalContext = createContext()
export function AuthModalProvider({ children }) {
  const [authModal, setAuthModal] = useState({ open: false, type: null })
  const openAuth = () => {
    setAuthModal({ open: true, type: 'auth' })
    document.body.style.overflowY = 'hidden';
  }
  const openReg = () => {
    setAuthModal({ open: true, type: 'reg' })
    document.body.style.overflowY = 'hidden';
  }
  const closeAuth = () => {
    setAuthModal({ open: false, type: null })
    document.body.style.overflowY = 'auto';
  }
  return (
    <AuthModalContext.Provider value={{ authModal, openAuth, openReg, closeAuth }}>
      {children}
    </AuthModalContext.Provider>
  )
}
export function useAuthModal() {
  return useContext(AuthModalContext)
}