// Селекторы для тултипов
const MENU_ITEM_SELECTOR = '.sidebar-v2-menu-item';
const WIDGET_SELECTOR = '.sidebar-widget-roulette';

/* ============================================================
   Универсальная ссылка пункта меню (Link / a / div)
   Тултип показывается ТОЛЬКО когда сайдбар свёрнут.
   ============================================================ */
function SidebarLink({ to, href, icon, label, active, tooltipText, opened }) {
  const { show, hide } = useTooltip({ selector: MENU_ITEM_SELECTOR, defaultPosition: 'right' });
  const classes = `sidebar-v2-menu-item${active ? ' sidebar-v2-menu-item_active' : ''}`;

  // Показываем тултип только если сайдбар свёрнут
  const handleMouseEnter = (e) => {
    if (!opened) show(e, tooltipText, 'right');
  };
  const handleMouseLeave = () => {
    if (!opened) hide();
  };

  const props = {
    className: classes,
    onMouseEnter: handleMouseEnter,
    onMouseLeave: handleMouseLeave,
  };

  const content = (
    <>
      {icon}
      <span>{label}</span>
    </>
  );

  if (to) return <Link to={to} {...props}>{content}</Link>;
  if (href) return <a href={href} {...props}>{content}</a>;
  return <div {...props}>{content}</div>;
}

