const ItemIguess = React.memo(function ItemIguess({item, index, profile, mines, firstItemRef, scrolN, state}) {
  let modifierClass = 'game-multipliers__item';
  let fi_cls = ''

  if (mines === 22) modifierClass = 'game-multipliers__item-twto game-multipliers__item';
  else if (mines === 23) modifierClass = 'game-multipliers__item-twth game-multipliers__item';
  else if (mines === 24) modifierClass = 'game-multipliers__item-twfo game-multipliers__item';

  const currentRound = profile?.Miner?.play ? profile.Miner.round : (INIT_DATA.round ?? 0)
  INIT_DATA.round = currentRound

  if (index === 0 && state?.dev?.view?.INIT_DATA__LOGS_IG) {
    console.log(`INIT_DATA__IIG: ${JSON.stringify(INIT_DATA)}`)
  }

  if (currentRound) {
    if (currentRound === index + 1) {
      fi_cls = 'game-multipliers__item_win'
    } else if (currentRound > index + 1) {
      fi_cls = 'game-multipliers__item_opened'
    }
  }

  const position = index + 1
  const classes = position > currentRound
    ? `${modifierClass} ${fi_cls}`
    : position < currentRound
      ? `${modifierClass} ${fi_cls} game-multipliers__item-celected`
      : `${modifierClass} ${fi_cls} game-multipliers__item-green`;

  return (
    <div key={index} className="swiper-content">
      <div
        className={classes}
        ref={index === 0 ? firstItemRef : null}
      >
        <small>{item.label}</small>
        <strong>{item.value}</strong>
      </div>
    </div>
  );
});

export default function Roll({ mines, profile }) {
  const sliderRef = useRef(null);
  const prevBtnRef = useRef(null);
  const nextBtnRef = useRef(null);
  const firstItemRef = useRef(null);
  const prevRoundRef = useRef(null);
  const { state } = useAppState()

  const multipliersData = useMemo(() => {
    const rowCount = 25 - mines;
    const kList = (ArrListMiner[mines - 1] || []).slice(0, rowCount);
    const getDuckLabel = (i) => {
      const count = i + 1;
      if (count === 1) return '1 утка';
      if (count <= 4) return `${count} утки`;
      return `${count} уток`;
    };
    return kList.map((value, index) => ({
      label: getDuckLabel(index),
      value
    }));
  }, [mines]);

  const ITEM_WIDTH = 103;

  const prevAnimationRef = useRef(null);

  const smoothScrollRef = useRef(null);
  smoothScrollRef.current = (targetPosition, duration = 200) => {
    const sliderWrapper = sliderRef.current;
    if (!sliderWrapper) return;

    if (prevAnimationRef.current) {
      cancelAnimationFrame(prevAnimationRef.current);
    }

    const startPosition = sliderWrapper.scrollLeft;
    let distance = targetPosition - startPosition;
    if (Math.abs(distance) < 1) return;

    let startTime = null;

    const animate = (currentTime) => {
      if (startTime === null) startTime = currentTime;
      const timeElapsed = currentTime - startTime;
      const progress = Math.min(timeElapsed / duration, 1);
      const ease = progress < 0.5
        ? 4 * progress * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 3) / 2;

      sliderWrapper.scrollLeft = startPosition + distance * ease;

      if (timeElapsed < duration) {
        prevAnimationRef.current = requestAnimationFrame(animate);
      } else {
        sliderWrapper.scrollLeft = targetPosition;
        prevAnimationRef.current = null;
      }
    };

    prevAnimationRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const sliderWrapper = sliderRef.current;
    const prevBtn = prevBtnRef.current;
    const nextBtn = nextBtnRef.current;

    const updateButtons = () => {
      if (!sliderWrapper) return;

      const scrollLeft = sliderWrapper.scrollLeft;
      const maxScroll = sliderWrapper.scrollWidth - sliderWrapper.clientWidth;

      if (prevBtn) prevBtn.disabled = scrollLeft <= 1;
      if (nextBtn) nextBtn.disabled = scrollLeft >= maxScroll - 1;
    };

    if (sliderWrapper) {
      sliderWrapper.addEventListener('scroll', updateButtons);
      window.addEventListener('resize', updateButtons);
    }

    setTimeout(updateButtons, 0);

    return () => {
      if (sliderWrapper) {
        sliderWrapper.removeEventListener('scroll', updateButtons);
        window.removeEventListener('resize', updateButtons);
      }
    };
  }, [mines]);

  useEffect(() => {
    const currentRound = profile?.Miner?.play ? profile.Miner.round : (INIT_DATA.round ?? 0);

    if (prevRoundRef.current !== null && currentRound > prevRoundRef.current && currentRound > 2) {
      handleScroll('next');
    }
    prevRoundRef.current = currentRound;
  }, [profile?.Miner?.round, profile?.Miner?.play]);

  const scrollAmountRef = useRef(103);

  useEffect(() => {
    if (firstItemRef.current && sliderRef.current) {
      const itemRect = firstItemRef.current.getBoundingClientRect();
      scrollAmountRef.current = Math.round(itemRect.width + 6);
    }
  }, [multipliersData]);

  const handleScroll = (direction) => {
    const sliderWrapper = sliderRef.current;
    if (!sliderWrapper) return;

    const scrollAmount = scrollAmountRef.current;
    const currentScroll = Math.round(sliderWrapper.scrollLeft / scrollAmount) * scrollAmount;
    const targetPosition = direction === 'next'
      ? currentScroll + scrollAmount
      : currentScroll - scrollAmount;

    smoothScrollRef.current(targetPosition, 300);
  };

  return (
    <div className="game-multipliers">
      <button
        aria-label="Previous"
        className="game-multipliers__button game-multipliers__button_prev"
        id="prevBtn"
        ref={prevBtnRef}
        onClick={() => handleScroll('prev')}
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512">
          <g><path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path></g>
        </svg>
      </button>

      <div className="game-multipliers-slider">
        <div className="slider-wrapper" id="sliderWrapper" ref={sliderRef}>
          {multipliersData.map((item, index) => (
            <ItemIguess key={index} item={item} index={index} profile={profile} mines={mines} firstItemRef={firstItemRef} scrolN={handleScroll} state={state}/>
          ))}
        </div>
      </div>

      <button
        aria-label="Next"
        className="game-multipliers__button game-multipliers__button_next"
        id="nextBtn"
        ref={nextBtnRef}
        onClick={() => handleScroll('next')}
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512">
          <g><path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path></g>
        </svg>
      </button>
    </div>
  );
}
