function Miner({ bet, setBet, mines, setMines, profile, isWide, isNarrow }) {
  const { profile: authProfile } = useAuth()
  const currentProfile = profile || authProfile
  const [ bombs, setBombs ] = useState(mines)
  const [runStart, setRunStart] = useState(false)
  const [runCell, setRunCell] = useState(false)

  const { data } = useTableData('miner_view', [
    { column: 'uuid', value: currentProfile?.uuid }
  ], { limit: 1 });

  const minerview = data?.minerview || data?.[0]?.minerview || [];

  useEffect(() => {
    const check = () => {
      const rs = window.__minerRunStart
      const rc = window.__minerRunCell
      if (rs !== runStart || rc !== runCell) {
        setRunStart(rs)
        setRunCell(rc)
      }
    }
    const id = setInterval(check, 50)
    return () => clearInterval(id)
  }, [runStart, runCell])
  
  useEffect(() => {
    if (currentProfile?.Miner) {
      setBombs(currentProfile.Miner.play ? currentProfile.Miner.bombs : mines)
    }
  }, [currentProfile, mines])

  useEffect(() => {
    if (currentProfile?.Miner?.play) {
      setMines(bombs)
    }
  }, [bombs, currentProfile?.Miner?.play])

  return(
    <div className="left-miner game-inhouse-frame__area">
      <div className={`miner-game page-game${isNarrow ? ' game-inhouse-miner__game' : ''}`}>
        {isNarrow ? (
          <>
            <Roll mines={bombs} profile={currentProfile} />
            <div className="miner-game-body">
              <div className="miner-game-panel miner-game-panel_left">
                <MinerLeft mines={bombs} />
                <MinerRight mines={bombs} />
              </div>
              <div className="miner-game-panel miner-game-panel_center">
                <MinerCells minerview={minerview} runStart={runStart} runCell={runCell} />
              </div>
            </div>
            <AutoCell minerview={minerview} />
          </>
        ) : (
          <div className="miner-game-body">
            <MinerLeft mines={bombs} />
            <MinerCenter mines={bombs} profile={currentProfile} minerview={minerview} runStart={runStart} runCell={runCell} />
            <MinerRight mines={bombs} />
          </div>
        )}
        <DepAndMines bet={bet} setBet={setBet} mines={mines} setMines={setMines} profile={currentProfile} />
      </div>
    </div>
  )
}

export default function MinerGamesPage() {
  const { profile } = useAuth()
  const { state, updateState } = useAppState()
  const [lastDep, setLD] = useState(false)
  const [bet, setBet] = useState(10);
  const [mines, setMines] = useState(5);
  const isWide = useIsWide()
  const isNarrow = useIsNarrow()
  const prevZoneRef = useRef(null)
  const prevOpenedRef = useRef(null)

  useEffect(() => {
    if (!profile || !profile.Miner) return

    const newZone = profile.Miner.zone
    const newOpened = Array.isArray(profile.Miner.zone)
      ? profile.Miner.zone.map(item => item === "X" ? true : false)
      : state.minerOpened

    const zoneChanged = JSON.stringify(newZone) !== JSON.stringify(prevZoneRef.current)
    const openedChanged = JSON.stringify(newOpened) !== JSON.stringify(prevOpenedRef.current)

    if (zoneChanged) {
      prevZoneRef.current = newZone
      updateState('miner', newZone)
    }
    if (openedChanged) {
      prevOpenedRef.current = newOpened
      updateState('minerOpened', newOpened)
    }
  }, [profile, profile?.Miner?.play, profile?.Miner?.zone, state.minerOpened, updateState])

  return (
    <div className="container">
      <div className="miner game-inhouse-frame">
        <div className="game-inhouse-frame__window">
          <div className="game-inhouse-frame__stage">
            <Miner
              bet={bet}
              setBet={setBet}
              mines={mines}
              setMines={setMines}
              profile={profile}
              isWide={isWide}
              isNarrow={isNarrow}
            />
          </div>
          {isWide && (
            <aside className="game-inhouse-frame__panel miner-side-panel">
              <LastDep game='Miner' />
            </aside>
          )}
        </div>
        <DownGame game='Miner' setLD={setLD} lastDep={lastDep} betsAlwaysActive={isWide}/>
        {!isWide && lastDep && <SlideIn><LastDep game="Miner" /></SlideIn>}
      </div>
      <SectMore game='Miner' />
    </div>
  );
}