import { createContext, useContext, useState } from 'react'
import { useSearchParams } from 'react-router-dom'

const BetMenuContext = createContext()

export function BetMenuProvider({ children }) {
  const [, setSearchParams] = useSearchParams()
  const [isOpen, setIsOpen] = useState(false)
  const [selectedBetUuid, setSelectedBetUuid] = useState(null)
  const openBetMenu = (betUuid) => {
    setSelectedBetUuid(betUuid)
    setIsOpen(true)
    document.body.style.overflowY = 'hidden'
    setSearchParams(prev => {
      prev.set('bet', betUuid)
      return prev
    })
  }
  const closeBetMenu = () => {
    setIsOpen(false)
    document.body.style.overflowY = 'auto'
    setSearchParams(prev => {
      prev.delete('bet')
      return prev
    })
  }
  return (
    <BetMenuContext.Provider value={{ isOpen, selectedBetUuid, openBetMenu, closeBetMenu }}>
      {children}
    </BetMenuContext.Provider>
  )
}

export function useBetMenu() {
  return useContext(BetMenuContext)
}
