import { useState } from "react";
import useTooltip from "../../../../hooks/useTooltip";
import { supabase } from "../../../../supabase";
import { useAuth } from "../../../../context/AuthContext";
import mess from "../../../../lib/message";
import { markSupabaseCall } from "../../../../lib/DEF_DATA";

export default function SettingsPage({profile}) {

  const { fetchProfile, user } = useAuth();

  const nameHelpTooltip = useTooltip({ selector: '.NHTT', defaultPosition: 'top' });
  const blockedEditTooltip = useTooltip({ selector: '.settings-account-avatar__edit-button', defaultPosition: 'top' });

  const [newName, setNewName] = useState('')
  const [loading, setLoading] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')
  const [incoLoading, setIncoLoading] = useState(false)

  const isIncognito = Boolean(profile?.INCO)

  const meta = user?.user_metadata || {}
  const googleName = meta.full_name || meta.name || user?.email || 'Google аккаунт'

  const trimmed = newName.trim()
  const isValid = trimmed.length >= 3 && trimmed.length <= 32
  const isChanged = trimmed !== String(profile?.name ?? '')
  const canSave = isValid && isChanged && !loading

  const handleChange = (e) => {
    setNewName(e.target.value)
    if (errorMsg) setErrorMsg('')
  }

  const showError = (text) => {
    setErrorMsg(text)
    setTimeout(() => setErrorMsg(''), 4000)
  }

  const handleSave = async () => {
    if (!canSave) return

    setLoading(true)
    setErrorMsg('')
    try {
      markSupabaseCall('redactName', 'pending')
      const { data, error } = await supabase.functions.invoke('redactName', {
        body: { newName: trimmed },
      })

      if (error) {
        let serverMsg = error.message || 'Ошибка изменения ника'
        try {
          if (error.context) {
            const ctx = await error.context.clone().json()
            if (ctx?.error) serverMsg = ctx.error
          }
        } catch (e) { /* тело не JSON */ }
        markSupabaseCall('redactName', 'error', serverMsg)
        mess(500, serverMsg)
        showError(serverMsg)
      } else if (data?.error) {
        markSupabaseCall('redactName', 'error', data.error)
        mess(400, data.error)
        showError(data.error)
      } else if (data?.success) {
        markSupabaseCall('redactName', 'ok')
        mess(200, data.message || 'Никнейм изменен')
        setNewName('')
        if (profile?.uuid) await fetchProfile(profile.uuid)
      } else {
        const serverMsg = 'Неизвестный ответ от сервера'
        markSupabaseCall('redactName', 'error', serverMsg)
        mess(500, serverMsg)
        showError(serverMsg)
      }
    } catch (err) {
      console.error('Network error changing nickname:', err)
      const serverMsg = err?.message || 'Ошибка подключения к серверу'
      markSupabaseCall('redactName', 'error', serverMsg)
      mess(500, 'Ошибка подключения к серверу')
      showError(serverMsg)
    } finally {
      setLoading(false)
    }
  }

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') handleSave()
  }

  const handleToggleIncognito = async () => {
    if (incoLoading) return

    const nextEnable = !isIncognito
    setIncoLoading(true)
    try {
      markSupabaseCall('incognito', 'pending')
      const { data, error } = await supabase.functions.invoke('incognito', {
        body: { enable: nextEnable },
      })

      if (error) {
        let serverMsg = error.message || 'Ошибка смены режима инкогнито'
        try {
          if (error.context) {
            const ctx = await error.context.clone().json()
            if (ctx?.error) serverMsg = ctx.error
          }
        } catch (e) { /* тело не JSON */ }
        markSupabaseCall('incognito', 'error', serverMsg)
        mess(500, serverMsg)
      } else if (data?.error) {
        markSupabaseCall('incognito', 'error', data.error)
        mess(400, data.error)
      } else if (data?.success) {
        markSupabaseCall('incognito', 'ok')
        mess(200, data.message || 'Режим инкогнито обновлен')
        if (profile?.uuid) await fetchProfile(profile.uuid)
      } else {
        const serverMsg = 'Неизвестный ответ от сервера'
        markSupabaseCall('incognito', 'error', serverMsg)
        mess(500, serverMsg)
      }
    } catch (err) {
      console.error('Network error toggling incognito:', err)
      markSupabaseCall('incognito', 'error', err?.message || String(err))
      mess(500, 'Ошибка подключения к серверу')
    } finally {
      setIncoLoading(false)
    }
  }

  return(
    <div className="account-settings">
      {/* Контент настроек */}
      <div className="panel-wrapper settings-account">
        <h2>Аккаунт</h2>
        <div className="panel">
          <div className="panel-content">
            <div className="panel-body">
              <div className="settings-account-avatar">
                <div className="settings-account-avatar__label">
                  <span>Аватар</span>
                </div>
                <div className="settings-account-avatar-image">
                  <span style={{background: String(profile.icon)}}>
                    <div>{String(profile.name[0]).toUpperCase()}</div>
                  </span>
                  <div 
                  onMouseEnter={(e) => blockedEditTooltip.show(e, 'Функция недоступна', 'top')}
                  onMouseLeave={blockedEditTooltip.hide}
                  class="settings-account-avatar__edit-button settings-account-avatar__edit-button_disabled v-popper--has-tooltip">
                    <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><g><path d="M496.889 51.13L460.42 14.626c-19.493-19.516-53.459-19.487-72.928 0L334.16 68.008 443.558 177.51l53.331-53.382C506.636 114.395 512 101.44 512 87.629c0-13.783-5.364-26.744-15.111-36.5zM297.668 104.536L31.884 370.571a12.664 12.664 0 00-3.428 6.168L.345 496.123a12.916 12.916 0 003.433 12.082 12.807 12.807 0 009.1 3.795c.982 0 1.987-.104 2.965-.336l119.276-28.137a12.824 12.824 0 006.162-3.431l265.784-266.031-109.397-109.529z"></path></g></svg>
                  </div>
                </div>
              </div>
              <div className="input">
                <div class="input">
                  <label class="input__label" for="input_994068">
                    <span>Никнейм</span>
                    <div className="NHTT"
                      onMouseEnter={(e) => nameHelpTooltip.show(e, 'От 3 до 32 символов', 'top')}
                      onMouseLeave={nameHelpTooltip.hide}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class="v-popper--has-tooltip"><path d="M256 0a256 256 0 10256 256A256.302 256.302 0 00256 0zm0 418.909a23.277 23.277 0 01-21.501-14.367 23.275 23.275 0 015.045-25.362 23.275 23.275 0 0139.729 16.456A23.272 23.272 0 01256 418.909zm54.458-157.23a69.533 69.533 0 00-31.185 55.365v8.774a23.27 23.27 0 01-6.817 16.456 23.27 23.27 0 01-32.912 0 23.27 23.27 0 01-6.817-16.456v-8.774a115.362 115.362 0 0150.479-93.091 46.545 46.545 0 00-18.618-83.549 46.56 46.56 0 00-38.322 9.936 46.554 46.554 0 00-16.811 35.842 23.27 23.27 0 01-6.817 16.456 23.27 23.27 0 01-32.912 0 23.27 23.27 0 01-6.817-16.456 93.096 93.096 0 0144.517-79.417 93.095 93.095 0 01126.087 27.861 93.086 93.086 0 01-23.055 127.053z"></path></svg>
                    </div>
                  </label> 
                  <div class="input-wrapper">
                    <div
                      class="input__error"
                      style={errorMsg ? { opacity: 1, visibility: 'visible', transform: 'translateY(0) scale(1)' } : undefined}>
                      {errorMsg}
                    </div> 
                      <input
                        placeholder={profile.name}
                        autocomplete="off"
                        type="text"
                        id="input_994068"
                        name="input_994068"
                        maxLength="32"
                        value={newName}
                        onChange={handleChange}
                        onKeyDown={handleKeyDown}
                        disabled={loading} />
                    </div> 
                    <div class="input__help">Отображается остальным участникам сайта. В списке ставок, истории игр, информации о профиле и во всех остальных местах.</div>
                </div>
              </div>
            </div>
            <div className="panel-footer">
              <div class="btn-wrapper">
                <button
                  disabled={!canSave}
                  onClick={handleSave}
                  class={`btn btn_primary ${canSave ? '' : 'btn_disabled'}`}>
                  <span>{loading ? 'Сохранение...' : 'Сохранить'}</span>
                </button> 
                <div
                  class="btn-loading"
                  style={loading ? { opacity: 1, visibility: 'visible' } : undefined} />
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="panel-wrapper settings-access">
        <h2>Доступ</h2> 
        <div class="panel">
          <div class="panel-content">
            <div class="panel-body">
              <div class="panel-header">
                <h3>Подключенные аккаунты</h3>
              </div> 
              <div class="settings-access-connections">
                <div class="settings-access-connections__item settings-access-connections__item_google">
                  <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><g><path d="M492.668 211.489l-208.84-.01c-9.222 0-16.697 7.474-16.697 16.696v66.715c0 9.22 7.475 16.696 16.696 16.696h117.606c-12.878 33.421-36.914 61.41-67.58 79.194L384 477.589c80.442-46.523 128-128.152 128-219.53 0-13.011-.959-22.312-2.877-32.785-1.458-7.957-8.366-13.785-16.455-13.785z"></path><path d="M256 411.826c-57.554 0-107.798-31.446-134.783-77.979l-86.806 50.034C78.586 460.443 161.34 512 256 512c46.437 0 90.254-12.503 128-34.292v-.119l-50.147-86.81c-22.938 13.304-49.482 21.047-77.853 21.047z"></path><path d="M384 477.708v-.119l-50.147-86.809c-22.938 13.303-49.48 21.046-77.853 21.046V512c46.437 0 90.256-12.503 128-34.292zM100.174 256c0-28.369 7.742-54.91 21.043-77.847l-86.806-50.034C12.502 165.746 0 209.444 0 256s12.502 90.254 34.411 127.881l86.806-50.034c-13.301-22.937-21.043-49.478-21.043-77.847zM256 100.174c37.531 0 72.005 13.336 98.932 35.519 6.643 5.472 16.298 5.077 22.383-1.008l47.27-47.27c6.904-6.904 6.412-18.205-.963-24.603C378.507 23.673 319.807 0 256 0 161.34 0 78.586 51.557 34.411 128.119l86.806 50.034c26.985-46.533 77.229-77.979 134.783-77.979z"></path><path d="M354.932 135.693c6.643 5.472 16.299 5.077 22.383-1.008l47.27-47.27c6.903-6.904 6.411-18.205-.963-24.603C378.507 23.672 319.807 0 256 0v100.174c37.53 0 72.005 13.336 98.932 35.519z"></path></g></svg> 
                  <span>{googleName}</span>
                </div>
              </div> 
              <div class="panel-header">
                <h3>Можно подключить</h3>
              </div> 
              <div class="settings-access-socials">
                <div class="settings-access-socials__item v-popper--has-tooltip">
                  <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="none" viewBox="0 0 512 512" class=""><g class="vkontakte"><path fill="#07F" d="M0 0h512v512H0z" class="frame"></path><path fill="#fff" fill-rule="evenodd" d="M126 250.8c0-58.831 0-88.247 18.277-106.523C162.553 126 191.969 126 250.8 126h10.4c58.831 0 88.247 0 106.523 18.277C386 162.553 386 191.969 386 250.8v10.4c0 58.831 0 88.247-18.277 106.523C349.447 386 320.031 386 261.2 386h-10.4c-58.831 0-88.247 0-106.523-18.277C126 349.447 126 320.031 126 261.2v-10.4Zm43.333-45.356c1.392 67.633 36.916 108.334 95.47 108.334h3.396v-38.692c21.326 2.164 37.229 18.107 43.721 38.692h30.746c-8.341-30.794-29.967-47.819-43.409-54.323 13.431-8.044 32.44-27.546 36.917-54.011h-27.973c-5.869 21.521-23.33 41.023-40.012 42.876v-42.876h-28.42v75.064c-17.295-4.329-39.856-25.382-40.78-75.064h-29.656Z" class="logotype"></path></g></svg>
                </div>
                <div class="settings-access-socials__item v-popper--has-tooltip">
                  <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="none" viewBox="0 0 512 512" class=""><g class="telegram"><path fill="#039BE5" d="M0 0h512v512H0z" class="frame"></path><path fill="#fff" d="M229.554 288.581l-4.065 57.181c5.816 0 8.336-2.498 11.356-5.499l27.27-26.061 56.506 41.381c10.363 5.775 17.664 2.734 20.46-9.534l37.09-173.797.01-.011c3.287-15.319-5.54-21.309-15.637-17.551L144.53 238.158c-14.88 5.775-14.654 14.07-2.53 17.828l55.738 17.337 129.467-81.011c6.093-4.034 11.633-1.802 7.076 2.233l-104.727 94.036z" class="logotype"></path></g></svg>
                </div>
                <div class="settings-access-socials__item v-popper--has-tooltip">
                  <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="none" viewBox="0 0 512 512" class=""><g class="yandex"><path fill="#FC3F1D" d="M0 0h512v512H0z" class="frame"></path><path fill="#fff" d="M307.781 133.12h-34.918c-35.377 0-71.072 26.123-71.072 84.483 0 30.229 12.813 53.773 36.298 67.162l-42.986 77.804c-2.038 3.68-2.091 7.85-.142 11.155 1.902 3.228 5.379 5.156 9.302 5.156h21.742c4.94 0 8.792-2.388 10.639-6.57l40.304-78.832h2.941v75.577c0 5.326 4.494 9.825 9.814 9.825h18.996c5.965 0 10.131-4.166 10.131-10.13V143.874c.001-6.332-4.543-10.754-11.049-10.754zM279.89 258.461h-5.189c-20.119 0-32.131-16.423-32.131-43.931 0-34.205 15.174-46.392 29.374-46.392h7.946v90.323z" class="logotype"></path></g></svg>
                </div>
                <div class="settings-access-socials__item v-popper--has-tooltip">
                  <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="none" viewBox="0 0 512 512" class=""><g class="steam"><path fill="#39739E" d="M0 0h512v512H0z" class="frame"></path><g class="logotype"><path fill="#fff" d="M316.447 151.552c-34.294 0-62.27 27.607-62.536 61.645l-38.943 55.572c-10.864-.983-20.234 1.26-28.518 6.288l-53.33-21.474v58.645l31.539 12.626c4.557 20.879 23.327 36.618 45.537 36.618 24.146 0 44.155-18.463 46.357-41.974l59.955-43.612c34.396 0 62.372-27.761 62.372-62.187l-.01-.011c0-34.263-27.976-62.136-62.423-62.136zm-106.251 197.55c-13.178 0-24.524-7.383-30.289-18.145 5.591 2.13 11.243 4.475 16.844 6.666 13.998 5.734 29.901-1.096 35.492-15.032 5.653-13.937-1.208-29.666-15.186-35.246l-14.264-5.735a33.751 33.751 0 017.403-.819c19.037 0 34.284 15.186 34.284 34.15 0 18.975-15.247 34.161-34.284 34.161zm106.312-93.757c-23.152 0-41.963-18.586-41.963-41.646 0-22.959 18.759-41.647 41.963-41.647 22.989 0 41.8 18.688 41.8 41.647 0 23.121-18.821 41.707-41.8 41.646z"></path><path fill="#fff" d="M316.621 180.285c-18.483 0-33.454 14.92-33.454 33.332 0 18.411 14.919 33.331 33.454 33.331 18.37 0 33.454-14.869 33.454-33.331 0-18.463-15.084-33.332-33.454-33.332z"></path></g></g></svg>
                </div>
              </div>
            </div> 
            <div class="panel-footer">
              <div class="btn-wrapper">
                <button class="btn btn_default">
                  <span>Зачем это нужно</span> 
                  <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path d="M256 0a256 256 0 10256 256A256.302 256.302 0 00256 0zm0 418.909a23.277 23.277 0 01-21.501-14.367 23.275 23.275 0 015.045-25.362 23.275 23.275 0 0139.729 16.456A23.272 23.272 0 01256 418.909zm54.458-157.23a69.533 69.533 0 00-31.185 55.365v8.774a23.27 23.27 0 01-6.817 16.456 23.27 23.27 0 01-32.912 0 23.27 23.27 0 01-6.817-16.456v-8.774a115.362 115.362 0 0150.479-93.091 46.545 46.545 0 00-18.618-83.549 46.56 46.56 0 00-38.322 9.936 46.554 46.554 0 00-16.811 35.842 23.27 23.27 0 01-6.817 16.456 23.27 23.27 0 01-32.912 0 23.27 23.27 0 01-6.817-16.456 93.096 93.096 0 0144.517-79.417 93.095 93.095 0 01126.087 27.861 93.086 93.086 0 01-23.055 127.053z"></path></svg>
                </button> 
                <div class="btn-loading" />
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="panel-wrapper settings-privacy">
        <h2>Приватность</h2> 
        <div class="panel">
          <div class="panel-content">
            <div class="panel-header">
              <h3>Режим инкогнито</h3> 
              <div class={`status ${isIncognito ? 'status_success' : 'status_error'}`}>
                <span>{isIncognito ? 'Включен' : 'Отключен'}</span>
              </div>
            </div> 
            <div class="panel-body"> 
              <ul class="numbered-list">
                <li class="numbered-list__item">Скрытый аватар</li>
                <li class="numbered-list__item">Скрытый никнейм</li>
                <li class="numbered-list__item">Скрытая игровая статистика</li>
                <li class="numbered-list__item">Скрытая история ставок</li>
              </ul> 
              <div class="settings-privacy__help">В режиме инкогнито детальная информация о Ваших действиях на сайте будет скрыта от остальных участников.</div>
            </div> 
            <div class="panel-footer">
              <div class="btn-wrapper">
                <button
                  disabled={incoLoading}
                  onClick={handleToggleIncognito}
                  class={`btn ${isIncognito ? 'btn_error' : 'btn_success'} ${incoLoading ? 'btn_disabled' : ''}`}>
                  <span>{incoLoading ? 'Подождите...' : (isIncognito ? 'Деактивировать' : 'Активировать')}</span>
                </button> 
                <div
                  class="btn-loading"
                  style={incoLoading ? { opacity: 1, visibility: 'visible' } : undefined} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}