import { 
  saveState, 
  getAllState, 
  saveStateBatch, 
  clearAllState,
  saveSetting, 
  getAllSettings, 
  saveSettingsBatch, 
  clearAllSettings 
} from './indexedDB';

window.dbCMD = {
  // ==================== STATE ====================
  async state() {
    const data = await getAllState();
    console.table(data);
    return data;
  },
  async stateSet(key, value) {
    await saveState(key, value);
    console.log(`✅ State "${key}" обновлён:`, value);
    return this.state();
  },
  async stateBatch(updates) {
    await saveStateBatch(updates);
    console.log(`✅ State обновлён (полей: ${Object.keys(updates).length}):`, updates);
    return this.state();
  },
  async stateReset() {
    await clearAllState();
    console.log('✅ State сброшен к дефолтным значениям');
    return this.state();
  },
  async stateGet(key) {
    const all = await getAllState();
    const value = all[key];
    console.log(`📌 State["${key}"] =`, value);
    return value;
  },

  // ==================== SETTINGS ====================

  async settings() {
    const data = await getAllSettings();
    console.table(data);
    return data;
  },
  async settingsSet(key, value) {
    await saveSetting(key, value);
    console.log(`✅ Setting "${key}" обновлён:`, value);
    return this.settings();
  },
  async settingsBatch(updates) {
    await saveSettingsBatch(updates);
    console.log(`✅ Настройки обновлены (полей: ${Object.keys(updates).length}):`, updates);
    return this.settings();
  },
  async settingsReset() {
    await clearAllSettings();
    console.log('✅ Настройки сброшены к дефолтным значениям');
    return this.settings();
  },
  async settingsGet(key) {
    const all = await getAllSettings();
    const value = all[key];
    console.log(`📌 Settings["${key}"] =`, value);
    return value;
  },

  // ==================== SHORTCUTS ====================

  async devMode() {
    await saveSettingsBatch({ devMode: true });
    await saveStateBatch({
      dev: {
        view: {
          updDPS: true,
          updUser: true,
          updProfile: true,
          updState: true,
          updSettings: true,
          updMiner: true,
          clrLog: true,
          logsAuthRT: true
        }
      }
    });
    console.log('✅ Dev-режим включён');
    return { settings: this.settings(), state: this.state() };
  },
  async devModeOff() {
    await saveSettingsBatch({ devMode: false });
    await saveStateBatch({
      dev: {
        view: {
          updDPS: false,
          updUser: false,
          updProfile: false,
          updState: false,
          updSettings: false,
          updMiner: false,
          clrLog: false,
          logsAuthRT: true
        }
      }
    });
    console.log('⚫ Dev-режим выключен');
    return { settings: this.settings(), state: this.state() };
  },
  async setDPS(value) {
    await saveState('FIRST_DPS', value);
    console.log(`✅ FIRST_DPS установлен: ${value}`);
    return this.stateGet('FIRST_DPS');
  },
  async setBalance(value) {
    await saveSetting('dps', value);
    console.log(`✅ settings.dps установлен: ${value}`);
    return this.settingsGet('dps');
  },
  async sound(enabled) {
    await saveSetting('sound', enabled);
    console.log(`✅ Sound ${enabled ? 'включён' : 'выключен'}`);
    return this.settingsGet('sound');
  },
  async theme(value) {
    await saveSetting('theme', value);
    console.log(`✅ Тема изменена на: ${value}`);
    return this.settingsGet('theme');
  },
  async overgame(enabled) {
    await saveState('miner_overgame', enabled);
    console.log(`✅ miner_overgame: ${enabled}`);
    return this.stateGet('miner_overgame');
  },
  help() {
    console.log(`
🛠️  Console Commands Help
==========================

📊 STATE (данные игры):
  dbCMD.state()                    - показать все state
  dbCMD.stateGet('key')            - получить поле
  dbCMD.stateSet('key', value)     - обновить поле
  dbCMD.stateBatch({a:1, b:2})     - обновить несколько полей
  dbCMD.stateReset()               - сбросить все state

⚙️  SETTINGS (настройки):
  dbCMD.settings()                 - показать все settings
  dbCMD.settingsGet('key')         - получить настройку
  dbCMD.settingsSet('key', value)  - обновить настройку
  dbCMD.settingsBatch({a:1})       - обновить несколько
  dbCMD.settingsReset()            - сбросить все settings

⚡ SHORTCUTS:
  dbCMD.devMode()                  - включить dev-режим
  dbCMD.devModeOff()               - выключить dev-режим
  dbCMD.setDPS(500)                - установить FIRST_DPS
  dbCMD.setBalance(200)            - установить dps в settings
  dbCMD.sound(true/false)          - включить/выключить звук
  dbCMD.theme('light'/'dark')      - сменить тему
  dbCMD.overgame(true/false)       - включить/выключить overgame

  dbCMD.help()                     - показать эту справку
    `);
  }
};

if (process.env.NODE_ENV === 'development') {
  console.log('dbCommands загружен. Введите dbCMD.help() для справки.');
}

export default window.dbCommands;