import React, { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useSettings } from '../../hooks/useSettings';
import { useAppState } from '../../hooks/useState';
import { useTableData } from '../../context/DataRT'

function ObjectTable({ title, data }) {
  return (
    <div style={{ marginBottom: '20px' }}>
      <h2>{title}</h2>
      <table border="1" cellPadding="8" style={{ borderCollapse: 'collapse', width: '100%' }}>
        <tbody>
          {Object.entries(data || {}).map(([key, value]) => (
            <tr key={key}>
              <td style={{ fontWeight: 'bold', width: '30%' }}>{key}</td>
              <td>
                {typeof value === 'object' ? (
                  <pre style={{ margin: 0, fontSize: '12px' }}>
                    {JSON.stringify(value, null, 2)}
                  </pre>
                ) : (
                  String(value)
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
export default function DevGetProfPage() {
  const { user, profile, signOut, loadingDB, loadingServer } = useAuth()
  const state = useAppState()
  const settings = useSettings()
  const [tick, setTick] = useState(0)
  const { data, loading, serverLoading } = useTableData(
      'miner_view', 
      'uuid',
      profile?.uuid, 
      state
    );
  const loadingVIEW = {
    'Server':loadingServer,
    'IndexDB':loadingDB,
    'miner_view':loading,
    'miner_view_server':serverLoading,
    'Settings':settings.loading,
    'State':state.loading,
  }
  
  useEffect(() => {
    setTick(prev => prev + 1)
  }, [user, profile, loadingDB, loadingServer, state.state, settings.settings])

  if (loadingDB) return <div>Загрузка...</div>;
  if (!user) return <span>Авторизуйтесь для проверки</span>; 
  if (!profile) {
    return (
      <>
        <button onClick={signOut}>Выйти</button>
        <div>Профиль "не найден"/"Загружается".</div>
      </>
    );
  }

  return (
    <>
      <span>Данные пользователя "{profile.name}"</span>
      <button onClick={signOut}>Выйти</button>
      <div>
        <ObjectTable title="loading" data={loadingVIEW}/>
        <ObjectTable title="user" data={user}/>
        <ObjectTable title="profile" data={profile}/>
        <ObjectTable title="miner_view" data={data}/>
        <ObjectTable title="state" data={state.state}/>
        <ObjectTable title="settings" data={settings.settings}/>
      </div>
      <div>
        <pre>{JSON.stringify(loadingVIEW, null, 2)}</pre>
        <pre>{JSON.stringify(user, null, 2)}</pre>
        <pre>{JSON.stringify(profile, null, 2)}</pre>
        <pre>{JSON.stringify(data, null, 2)}</pre>
        <pre>{JSON.stringify(settings.settings, null, 2)}</pre>
        <pre>{JSON.stringify(state.state, null, 2)}</pre>
      </div>
    </>
  );
}