import { useMemo } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { useTableData } from "../../../../context/DataRT"
import { useOpenBetMenu } from "../../../../hooks/useOpenBetMenu"

import '../css/betsdata.css'

const MONTHS_RU = [
  'января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
  'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'
]

function parseBetDate(isoString, utcOffsetHours = 3) {
  if (!isoString) return { time: '--:--', date: '' }

  const date = new Date(isoString)
  const utc = date.getTime() + date.getTimezoneOffset() * 60000
  const local = new Date(utc + 3600000 * utcOffsetHours)

  const time = local.toTimeString().slice(0, 5)
  const dateStr = `${local.getDate()} ${MONTHS_RU[local.getMonth()]}`

  return { time, date: dateStr }
}
