const MODES = {
  bets:    { table: 'old_dep', state_bet: 'games' },
  bonuses: { table: 'old_dep', state_bet: 'bonus' },
  userdata:{ table: 'old_dep', state_bet: 'games' },
}

const BONUS_DESCRIPTIONS = {
  PromoCode: 'Активация промо-кода',
  Roulette:  'Кручение Lucky Wheel',
}

// Анимация строк таблицы при появлении/исчезновении/смене данных
const rowVariants = {
  hidden: { opacity: 0, y: 10 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.25, ease: 'easeOut' } },
  exit: { opacity: 0, y: -10, transition: { duration: 0.15, ease: 'easeIn' } },
}

function BonusAmount({ value }) {
  return (
    <div className=" table-body table-col__amount_positiveds amount table-col__amount table-col__amount_scrollable table-col__amount_positive">
      <span>{value}</span>
      <DuckIcon />
    </div>
  )
}

export default function BetsData({mode, profile}) {
  const openBetMenu = useOpenBetMenu()

  const conf = MODES[mode] || null
  const { data } = useTableData(conf?.table ?? null, [
    { column: 'uuid', value: profile?.uuid },
    { column: 'state_bet', value: conf?.state_bet }
  ], {
    limit: 10,
    orderByColumn: 'timeat',
    orderDirection: 'desc'
  })

  const betsArr = useMemo(() => {
    return Array.isArray(data) ? data : data ? [data] : []
  }, [data])

  const contentHidden = conf !== null && data === null

  const safeDep = (bet) => Number(bet?.data?.dep ?? 0)
  const safeK = (bet) => Number(bet?.data?.k ?? 0)
  const multiplierClass = (k) =>
    k < 1 ? 'multiplier_red' :
    k >= 10 ? 'multiplier_yellow' :
    k >= 2 ? 'multiplier_blue' :
    'multiplier_default'

  const isBonus = conf?.state_bet === 'bonus'

  const emptyState = (
    <div className="table-row table-row_empty">
      <div className="table-col table-col_empty">
        <div className="table-col-empty__image">
          <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className="">
            <g>
              <path d="M256 0C114.844 0 0 114.844 0 256c0 141.157 114.844 256.001 256 256.001 141.157 0 256.001-114.844 256.001-256.001C512.001 114.844 397.156 0 256 0Z" opacity=".25"></path>
              <path d="M146.787 189.213c-11.716-11.716-11.716-30.71 0-42.426 11.716-11.716 30.71-11.716 42.426 0l67.287 67.287 67.287-67.287c11.716-11.716 30.71-11.716 42.426 0 11.716 11.716 11.716 30.71 0 42.426L298.926 256.5l67.064 67.063c11.716 11.716 11.716 30.711 0 42.427-11.716 11.716-30.711 11.716-42.427 0L256.5 298.926l-67.063 67.064c-11.716 11.716-30.711 11.716-42.427 0-11.716-11.716-11.716-30.711 0-42.427l67.064-67.063-67.287-67.287Z"></path>
            </g>
          </svg>
        </div>
        <div className="table-col-empty__title">Операции отсутствуют</div>
        <div className="table-col-empty__text">Тут будут отображаться операции, связанные с изменением Вашего баланса.</div>
        <div className="table-col-empty__text">Например, при возврате суммы ставки в случае сбоя игры.</div>
      </div>
    </div>
  )

  if (isBonus) {
    return (
      <div className={`bets-data ${contentHidden ? 'bets-data_loading' : ''}`}>
        <div className="table bonuses-v2">
          <div className="table-header bonuses-v2__header">
            <div className="table-row">
              <div className="bonuses-v2__col bonuses-v2__col_date">Дата</div>
              <div className="bonuses-v2__col bonuses-v2__col_description">Описание</div>
              <div className="bonuses-v2__col bonuses-v2__col_amount">Сумма</div>
              <div className="bonuses-v2__col bonuses-v2__col_actions" />
            </div>
          </div>
          <div className="table-body">
            {betsArr.length === 0 && emptyState}
            <AnimatePresence initial={false}>
              {betsArr.map((bet, index) => {
                const { time, date } = parseBetDate(bet?.timeat)
                const description = BONUS_DESCRIPTIONS[bet?.game] || bet?.game
                const amount = Number(bet?.data?.bet ?? 0)

                return (
                  <motion.div
                    className="table-row table-row_hoverable bonuses-v2__row"
                    key={bet?.id || bet?.bet_uuid || index}
                    variants={rowVariants}
                    initial="hidden"
                    animate="visible"
                    exit="exit"
                  >
                    <div className="bonuses-v2__col bonuses-v2__col_date">
                      <div className="table-col__date table-col__date_v2 table-col__date_v2_time">{time}</div>
                      <div className="table-col__date table-col__date_v2">{date}</div>
                    </div>
                    <div className="bonuses-v2__col bonuses-v2__col_description">
                      <div className="bonuses-v2__type">{description}</div>
                    </div>
                    <div className="bonuses-v2__col bonuses-v2__col_amount">
                      <BonusAmount value={amount} />
                    </div>
                    <div className="bonuses-v2__col bonuses-v2__col_actions" />
                  </motion.div>
                )
              })}
            </AnimatePresence>
          </div>
        </div>
      </div>
    )
  }

  return(
    <div className={`bets-data ${contentHidden ? 'bets-data_loading' : ''}`}>
      <div className="table bet-v2">
        <div className="table-header bets-v2__header">
          <div className="table-row">
            <div className="bets-v2__col bets-v2__col_date">Дата</div>
            <div className="bets-v2__col bets-v2__col_game">Игра</div>
            <div className="bets-v2__col bets-v2__col_bet">Ставка</div>
            <div className="bets-v2__col bets-v2__col_multiplier">Коэффициент</div>
            <div className="bets-v2__col bets-v2__col_result">Выигрыш</div>
            <div className="bets-v2__col bets-v2__col_actions" />
          </div>
        </div>
        <div className="table-body">
          {betsArr.length === 0 && emptyState}
          <AnimatePresence initial={false}>
          {betsArr.map((bet, index) => {
            const { time, date } = parseBetDate(bet?.timeat)
            const k = safeK(bet)
            const itswin = k !== 0
            const win = itswin ? (safeDep(bet) * k) : (safeDep(bet) * Number(bet?.data?.gamek ?? 0))

            return (
              <motion.div
                className="table-row table-row_hoverable bets-v2__row"
                key={bet?.id || bet?.bet_uuid || index}
                variants={rowVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
              >
                <div className="bets-v2__col bets-v2__col_date">
                  <div className="table-col__date table-col__date_v2 table-col__date_v2_time">{time}</div>
                  <div className="table-col__date table-col__date_v2">{date}</div>
                </div>
                <div className="bets-v2__col bets-v2__col_game">
                  <div className="bet-game-cell">
                    <GameIcon game={bet?.game} />
                    <span className="bet-game-cell__text">
                      <span className="bet-game-cell__name">{bet?.game}</span>
                      <span className="bet-game-cell__provider">LuckyDuck</span>
                    </span>
                  </div>
                </div>
                <div className="bets-v2__col bets-v2__col_bet">
                  <div className="fix-amount amount table-col__amount table-col__amount_scrollable">
                    <span>{safeDep(bet).toFixed(2)}</span>
                    <DuckIcon />
                  </div>
                </div>
                <div className="bets-v2__col bets-v2__col_multiplier">
                  <span style={{top: 0}}
                  className={`fix-amount table-col__multiplier multiplier ${multiplierClass(k)}`}>
                    {`x${k.toFixed(2)}`}
                  </span>
                </div>
                <div className="bets-v2__col bets-v2__col_result">
                  <div className={`fix-amount amount table-col__amount table-col__amount_scrollable ${itswin ? 'table-col__amount_positived' : 'table-col__amount_negative'}`}>
                    <span>{win.toFixed(3)}</span>
                    <DuckIcon />
                  </div>
                </div>
                <div className="bets-v2__col bets-v2__col_actions">
                  <button type="button" className="table-col__button table-col__button_blue" onClick={() => openBetMenu(bet?.bet_uuid)}>
                    <span>Подробнее</span>
                    <EyeIcon />
                  </button>
                </div>
                <div className="bets-v2__card">
                  <div className="bets-v2__card-header">
                    <div className="bet-game-cell bet-game-cell_inline">
                      <GameIcon game={bet?.game} />
                      <span className="bet-game-cell__text">
                        <span className="bet-game-cell__name">{bet?.game}</span>
                      </span>
                    </div>
                    <span style={{Top: 0}}
                    className={`table-col__multiplier bets-v2__card-multiplier multiplier ${multiplierClass(k)}`}>
                      {`x${k.toFixed(2)}`}
                    </span>
                    <div className="table-col__date table-col__date_v2 bets-v2__card-date">
                      {date ? `${date} в ${time}` : ''}
                    </div>
                  </div>
                  <div className="bets-v2__card-body">
                    <div className="bets-v2__card-values">
                      <div className="amount table-col__amount table-col__amount_scrollable fix-amount">
                        <span>{safeDep(bet).toFixed(2)}</span>
                        <DuckIcon />
                      </div>
                      <div className={`amount table-col__amount table-col__amount_scrollable fix-amount ${itswin ? 'table-col__amount_positived' : 'table-col__amount_negative'}`}>
                        <span>{win.toFixed(3)}</span>
                        <DuckIcon />
                      </div>
                    </div>
                    <button type="button" className="table-col__button table-col__button_blue bets-v2__card-button" onClick={() => openBetMenu(bet?.bet_uuid)}>
                      <span>Подробнее</span>
                      <EyeIcon />
                    </button>
                  </div>
                </div>
              </motion.div>
            )
          })}
          </AnimatePresence>
        </div>
      </div>
    </div>
  )
}