import { useState, useEffect } from 'react';

// Пороги прежние: <768 — мобильный, <1024 — планшет, иначе десктоп.
// matchMedia вместо resize: пересчёт только при пересечении брейкпоинта.
const DEVICES = [
  { device: 'm', query: '(max-width: 767.98px)' },
  { device: 't', query: '(min-width: 768px) and (max-width: 1023.98px)' },
];

const readDevice = () => {
  for (const { device, query } of DEVICES) {
    if (window.matchMedia(query).matches) return device;
  }
  return 'd';
};

// 'm' | 't' | 'd'
export function useDevice() {
  const [device, setDevice] = useState(readDevice);

  useEffect(() => {
    const mediaQueries = DEVICES.map(({ query }) => window.matchMedia(query));
    const onChange = () => setDevice(readDevice());
    mediaQueries.forEach((mediaQuery) => mediaQuery.addEventListener('change', onChange));
    return () => mediaQueries.forEach((mediaQuery) => mediaQuery.removeEventListener('change', onChange));
  }, []);

  return device;
}
