// Задержка применения обновлений баланса (profile), пока шары Plinko в полёте.
// События realtime, пришедшие во время «холда», ставятся в очередь и
// применяются одним пакетом, когда ПОСЛЕДНИЙ шар приземлится (releaseBalance).
// Счётчик, а не флаг: параллельно может летать несколько шаров.

let held = 0 // число шаров в полёте
let holdStartedAt = null // timestamp начала первого холда
let timeout = 0
let pending = [] // очередь профилей, ожидающих применения
let onFlush = null // обработчик применения (регистрируется AuthContext)
const holdListeners = new Set() // подписчики изменения числа шаров в полёте

export function getHoldStartedAt() {
  return holdStartedAt
}

// Подписка на число шаров в полёте: (held: number) => void. Возвращает
// функцию отписки. Позволяет компонентам (LastDep) скрывать новые ставки
// пользователя синхронно с балансом и подгружать запас строк по числу
// анимаций: пока held > 0 — холд включён.
export function onHoldChange(cb) {
  holdListeners.add(cb)
  return () => holdListeners.delete(cb)
}

function notifyHoldChange() {
  for (const cb of [...holdListeners]) cb(held)
}

// Текущее число шаров в полёте (0 = холда нет).
export function getHeldBalls() {
  return held
}

// Регистрация обработчика: (profiles[]) => void
export function registerBalanceFlushHandler(cb) {
  onFlush = cb
}

// Один шар запущен. safetyMs — авто-отпуск на случай, если приземление
// не случилось (закрытие вкладки, ошибка анимации).
export function holdBalance(safetyMs = 20000) {
  held += 1
  if (held === 1) holdStartedAt = new Date().toISOString()
  notifyHoldChange()
  clearTimeout(timeout)
  timeout = setTimeout(() => { held = 1; releaseBalance() }, safetyMs)
}

// Один шар приземлился. Применяем накопленные обновления, когда все
// приземлились. Событие без пары (ошибка ставки до запуска) отпускать
// нельзя — см. releaseBalanceOrphan.
export function releaseBalance() {
  if (held <= 0) return
  held -= 1
  if (held > 0) return
  holdStartedAt = null
  notifyHoldChange()
  clearTimeout(timeout)
  timeout = 0
  const q = pending
  pending = []
  if (q.length && typeof onFlush === 'function') onFlush(q)
}

// Отпуск без привязки к приземлению: ставка не состоялась (ошибка ответа),
// шар не летит — уменьшаем счётчик сразу.
export function releaseBalanceOrphan() {
  releaseBalance()
}

export function isBalanceHeld() {
  return held > 0
}

// Положить профиль в очередь (храним только последний — он актуальнее).
export function queueHeldProfile(profile) {
  pending = [profile]
}
