import React, { useRef, useEffect, useState } from 'react';

export default function Question({ id, title, isOpened, onToggle, children }) {
  const bodyRef = useRef(null);
  const [maxHeight, setMaxHeight] = useState('0px');

  useEffect(() => {
    if (bodyRef.current) {
      setMaxHeight(isOpened ? `${bodyRef.current.scrollHeight}px` : '0px');
    }
  }, [isOpened, children]);

  return (
    <div id={id} className={`question ${isOpened ? 'question_opened' : ''}`}>
      <div className="question-header" onClick={() => onToggle(id)}>
        <div className="question-header__anchor v-popper--has-tooltip">
          <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className=""><path d="M279.28 355.2l-38 38.048a86.656 86.656 0 01-94.427 18.776A86.649 86.649 0 0193.37 331.97a86.643 86.643 0 0125.382-61.266L156.8 232.72a38.729 38.729 0 0011.76-27.498 38.712 38.712 0 00-24.038-36.124 38.718 38.718 0 00-42.474 8.87L64 216a164.097 164.097 0 00232 232l38-38a38.732 38.732 0 008.424-42.192 38.711 38.711 0 00-20.94-20.971 38.732 38.732 0 00-29.636-.022 38.73 38.73 0 00-12.568 8.385zM448 64a164.881 164.881 0 00-232 0l-38.032 37.984A38.738 38.738 0 00232.72 156.8l38-38.048a86.647 86.647 0 01122.528 122.544L355.2 279.28a38.718 38.718 0 00.008 54.76 38.718 38.718 0 0054.76-.008L448 296a164.88 164.88 0 000-232z"></path><path d="M232.72 334.032L334.032 232.72a38.721 38.721 0 00-27.498-65.678 38.721 38.721 0 00-27.254 10.926L177.968 279.28a38.717 38.717 0 00.414 54.338 38.718 38.718 0 0054.338.414z"></path></svg>
        </div>
        <div className="question-header-content">
          <div className="question-header__title">{title}</div>
          <div className="question-header__caret">
            <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className=""><g><path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path></g></svg>
          </div>
        </div>
      </div>
      <div
        ref={bodyRef}
        className="question-body"
        style={{ maxHeight }}
      >
        <div className="typography">
          {children}
        </div>
      </div>
    </div>
  );
}