import { useState, useEffect } from 'react';
import { saveSetting, getAllSettings, saveSettingsBatch, clearAllSettings } from '../lib/indexedDB';
import { DEFAULT_SETTINGS } from '../lib/DEF_DATA'

export function useSettings() {
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      const all = await getAllSettings();
      setSettings({ ...DEFAULT_SETTINGS, ...all });
    } catch (err) {
      console.error('[useSettings] Load error:', err);
      setSettings(DEFAULT_SETTINGS);
    } finally {
      setLoading(false);
    }
  };
  const updateSetting = async (key, value) => {
    try {
      await saveSetting(key, value);
      setSettings(prev => ({ ...prev, [key]: value }));
    } catch (err) {
      console.error('[useSettings] Save error:', err);
    }
  };
  const updateSettingsBatch = async (newSettings) => {
    try {
      const dbSettings = { ...settings, ...newSettings };
      await saveSettingsBatch(newSettings);
      setSettings(dbSettings);
    } catch (err) {
      console.error('[useSettings] Batch save error:', err);
    }
  };
  const resetSettings = async () => {
    try {
      await clearAllSettings();
      setSettings(DEFAULT_SETTINGS);
    } catch (err) {
      console.error('[useSettings] Reset error:', err);
    }
  };
  return {
    settings,
    loading,
    updateSetting,
    updateSettingsBatch,
    resetSettings,
    loadSettings
  };
}