import { useEffect, useRef, useCallback } from 'react';

export function useInterval(callback, delay) {
  const savedCallback = useRef(callback);

  useEffect(() => {
    savedCallback.current = callback;
  }, [callback]);

  useEffect(() => {
    if (delay === null || delay === undefined) return;

    const tick = () => {
      if (typeof savedCallback.current === 'function') {
        savedCallback.current();
      }
    };
    
    const id = setInterval(tick, delay);
    
    return () => clearInterval(id);
  }, [delay]);
}

export function useIntervalAdvanced(callback, delay, options = {}) {
  const optObj = typeof options === 'object' ? options : {};
  const {
    immediate = false,
    pauseOnHidden = true,
  } = optObj;

  const savedCallback = useRef(callback);
  const intervalRef = useRef(null);
  const isPausedRef = useRef(false);

  useEffect(() => {
    savedCallback.current = callback;
  }, [callback]);

  useEffect(() => {
    if (!pauseOnHidden) return;

    const handleVisibilityChange = () => {
      if (document.hidden) {
        if (intervalRef.current) {
          clearInterval(intervalRef.current);
          isPausedRef.current = true;
        }
      } else if (isPausedRef.current && intervalRef.current) {
        isPausedRef.current = false;
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, [pauseOnHidden]);

  useEffect(() => {
    const safeDelay = (typeof delay === 'number' && delay > 0 && isFinite(delay)) ? delay : 1000;

    const tick = () => {
      if (typeof savedCallback.current === 'function') {
        savedCallback.current();
      }
    };

    if (immediate) {
      tick();
    }

    intervalRef.current = setInterval(tick, safeDelay);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [delay, immediate]);

  const start = useCallback(() => {
    if (intervalRef.current) return;
    isPausedRef.current = false;
    const safeDelay = (typeof delay === 'number' && delay > 0 && isFinite(delay)) ? delay : 1000;
    intervalRef.current = setInterval(() => {
      if (typeof savedCallback.current === 'function') savedCallback.current();
    }, safeDelay);
  }, [delay]);

  const pause = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
      isPausedRef.current = true;
    }
  }, []);

  const resume = useCallback(() => {
    if (!isPausedRef.current || intervalRef.current) return;
    isPausedRef.current = false;
    const safeDelay = (typeof delay === 'number' && delay > 0 && isFinite(delay)) ? delay : 1000;
    intervalRef.current = setInterval(() => {
      if (typeof savedCallback.current === 'function') savedCallback.current();
    }, safeDelay);
  }, [delay]);

  const reset = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  return { start, pause, resume, reset, isPaused: () => isPausedRef.current };
}