import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { supabase } from '../supabase'
import { useAuth } from './AuthContext'

const LikesContext = createContext(null)

const likeKey = (name) => String(name ?? '').trim().toLowerCase()
const entryUuid = (entry) => (typeof entry === 'string' ? entry : entry?.uuid)
const normalize = (list) => (Array.isArray(list) ? list.filter((entry) => entryUuid(entry)) : [])
const sameList = (a, b) =>
  a.length === b.length && a.every((entry, i) => entryUuid(entry) === entryUuid(b[i]))

export function LikesProvider({ children }) {
  const { user } = useAuth()
  const userId = user?.id || null

  const [likes, setLikes] = useState({})
  const [pending, setPending] = useState({})
  const [mine, setMine] = useState([])
  const [mineLoaded, setMineLoaded] = useState(false)

  const storeRef = useRef({})
  const pendingRef = useRef({})
  const queueRef = useRef(new Set())
  const flushTimerRef = useRef(null)
  const mineTimerRef = useRef(null)
  const flushRetryRef = useRef(0)
  const flushQueueRef = useRef(null)
  const userIdRef = useRef(userId)
  userIdRef.current = userId

  const commit = useCallback(() => setLikes({ ...storeRef.current }), [])

  // Применяем данные сервера/realtime, не перетирая наш оптимистичный результат
  const applyEntries = useCallback((key, rawLiked, ignorePending = false) => {
    if (!key) return
    let list = normalize(rawLiked)
    const intent = ignorePending ? null : pendingRef.current[key]
    const me = userIdRef.current

    if (intent && me) {
      const hasMe = list.some((entry) => entryUuid(entry) === me)
      if (intent === 'add' && !hasMe) list = [...list, { uuid: me }]
      if (intent === 'remove' && hasMe) list = list.filter((entry) => entryUuid(entry) !== me)
    }

    const prev = storeRef.current[key]
    if (prev && sameList(prev, list)) return

    storeRef.current[key] = list
    commit()
  }, [commit])

  // Одна сетевая запрос-пачка на все карточки, отрендеренные в одном кадре
  const flushQueue = useCallback(async () => {
    const names = Array.from(queueRef.current)
    queueRef.current.clear()
    if (names.length === 0) return

    try {
      const { data, error } = await supabase.functions.invoke('do-like', {
        body: { mode: 'bulk', gameNames: names },
      })
      if (error || !data?.likes) throw new Error(data?.error || error?.message || 'bulk likes failed')

      flushRetryRef.current = 0
      names.forEach((name) => {
        const key = likeKey(name)
        applyEntries(key, data.likes[key] ?? [])
      })
    } catch (err) {
      // Ошибка больше не молча проглатывается: возвращаем имена в очередь
      // и повторяем с нарастающей паузой, иначе count навсегда остался бы 0
      console.error('[Likes] bulk fetch error:', err)
      if (flushRetryRef.current >= 3) return
      flushRetryRef.current += 1
      for (const name of names) queueRef.current.add(name)
      setTimeout(() => flushQueueRef.current && flushQueueRef.current(), 500 * flushRetryRef.current)
    }
  }, [applyEntries])
  flushQueueRef.current = flushQueue

  const requestGame = useCallback((name) => {
    const key = likeKey(name)
    if (!key || key in storeRef.current) return

    queueRef.current.add(String(name).trim())
    if (flushTimerRef.current) return

    flushTimerRef.current = setTimeout(() => {
      flushTimerRef.current = null
      flushQueue()
    }, 40)
  }, [flushQueue])

  const refreshMine = useCallback(async () => {
    if (!userIdRef.current) {
      setMine([])
      setMineLoaded(true)
      return
    }

    try {
      const { data, error } = await supabase.functions.invoke('do-like', {
        body: { mode: 'user' },
      })
      if (error || !data?.games) return
      setMine(data.games.map(likeKey))
      setMineLoaded(true)
    } catch (err) {
      console.error('[Likes] favorites refresh error:', err)
    }
  }, [])

  const scheduleMineRefresh = useCallback((delay = 350) => {
    if (mineTimerRef.current) clearTimeout(mineTimerRef.current)
    mineTimerRef.current = setTimeout(() => {
      mineTimerRef.current = null
      refreshMine()
    }, delay)
  }, [refreshMine])

  // Мгновенный оптимистичный toggle с сверкой по ответу сервера
  const toggleLike = useCallback(async (name) => {
    const trimmed = String(name ?? '').trim()
    const key = likeKey(trimmed)
    const me = userIdRef.current

    if (!key) return { error: 'game name is empty' }
    if (!me) return { error: 'not authenticated' }
    if (pendingRef.current[key]) return { skipped: true }

    const previous = storeRef.current[key] || []
    const wasLiked = previous.some((entry) => entryUuid(entry) === me)

    pendingRef.current[key] = wasLiked ? 'remove' : 'add'
    setPending((state) => ({ ...state, [key]: true }))
    storeRef.current[key] = wasLiked
      ? previous.filter((entry) => entryUuid(entry) !== me)
      : [...previous, { uuid: me }]
    commit()

    try {
      const { data, error } = await supabase.functions.invoke('do-like', {
        body: { gameName: trimmed },
      })
      if (error || !data?.liked) throw new Error(data?.error || 'like request failed')

      delete pendingRef.current[key]
      applyEntries(key, data.liked, true)
      scheduleMineRefresh(0)
      return { liked: !wasLiked }
    } catch (err) {
      delete pendingRef.current[key]
      storeRef.current[key] = previous
      commit()
      console.error('[Likes] toggle error:', err)
      return { error: err?.message || String(err), wasLiked }
    } finally {
      setPending((state) => {
        const next = { ...state }
        delete next[key]
        return next
      })
    }
  }, [applyEntries, commit, scheduleMineRefresh])

  // Realtime: счётчики и избранное обновляются на изменениях всех пользователей
  useEffect(() => {
    const channel = supabase
      .channel('likes:games')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'games' },
        (payload) => {
          const row = payload.eventType === 'DELETE' ? payload.old : payload.new
          if (!row?.name) return

          applyEntries(likeKey(row.name), row.liked || [])
          if (userIdRef.current) scheduleMineRefresh()
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [applyEntries, scheduleMineRefresh])

  useEffect(() => {
    if (userId) refreshMine()
    else setMine([])
  }, [userId, refreshMine])

  useEffect(() => () => {
    if (mineTimerRef.current) clearTimeout(mineTimerRef.current)
    if (flushTimerRef.current) clearTimeout(flushTimerRef.current)
  }, [])

  const mineSet = useMemo(() => new Set(mine), [mine])
  const isFavorite = useCallback((name) => mineSet.has(likeKey(name)), [mineSet])

  const value = useMemo(
    () => ({
      likes,
      pending,
      requestGame,
      toggleLike,
      refreshMine,
      isFavorite,
      favorites: mineSet,
      favoritesLoaded: mineLoaded,
    }),
    [likes, pending, requestGame, toggleLike, refreshMine, isFavorite, mineSet, mineLoaded]
  )

  return <LikesContext.Provider value={value}>{children}</LikesContext.Provider>
}

export function useLikes() {
  const ctx = useContext(LikesContext)
  if (!ctx) throw new Error('useLikes must be used within LikesProvider')
  return ctx
}

// Лайки одной игры: число, состояние пользователя, анимация при изменении числа
export function useGameLikes(name) {
  const { user } = useAuth()
  const { likes, pending, requestGame, toggleLike } = useLikes()
  const key = likeKey(name)

  useEffect(() => {
    requestGame(name)
  }, [key, name, requestGame])

  const entries = likes[key]
  const count = entries ? entries.length : 0
  const loaded = Boolean(entries)

  const [bump, setBump] = useState(false)
  const prevCountRef = useRef(null)

  useEffect(() => {
    // Первое пришедшее с сервера число — базовое, анимация только на последующих изменениях
    if (!loaded) return

    if (prevCountRef.current === null) {
      prevCountRef.current = count
      return
    }
    if (prevCountRef.current === count) return

    prevCountRef.current = count
    setBump(true)
    const timer = setTimeout(() => setBump(false), 420)
    return () => clearTimeout(timer)
  }, [count, loaded])

  const isLiked = Boolean(user?.id && entries?.some((entry) => entryUuid(entry) === user.id))

  return {
    count,
    loaded: Boolean(entries),
    isLiked,
    pending: Boolean(pending[key]),
    bump,
    toggle: () => toggleLike(name),
  }
}
