import React, { useState, useCallback, useEffect } from 'react';
import TowerLeft from './component/tower-left'
import { useAuth } from '../../../context/AuthContext'
import { LastDep } from '../components/last_deps';
import DownGame from '../components/DownGame/page';
import SlideIn from '../components/SlideIn';
import './css/page.css';
import '../Plinko/css/game.css';
import SectMore from '../components/ENDLD/page';

// > 992px — панель lastDep показывается всегда сбоку; иначе — по кнопке в DownGame.
function useIsWide(breakpoint = 993) {
  const [isWide, setWide] = useState(
    typeof window !== 'undefined' ? window.innerWidth >= breakpoint : false
  );
  useEffect(() => {
    const onResize = () => setWide(window.innerWidth >= breakpoint);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, [breakpoint]);
  return isWide;
}

export default function NutsGamesPage() {
  const { profile } = useAuth()
  const [lastDep, setLD] = useState(false)
  const isWide = useIsWide()

  const handlePlay = useCallback((params) => {
    console.log('Tower play:', params)
    // TODO: реализовать логику запуска игры
  }, [])

  return (
    <div className='container'>
      <div className="game-inhouse-frame">
        <div className="game-inhouse-frame__window">
          <div className="game-inhouse-frame__stage">
            <div className="game-inhouse-frame__area">
              <TowerLeft profile={profile} onPlay={handlePlay} />
            </div>
          </div>
          {isWide && (
            <aside className="game-inhouse-frame__panel">
              <LastDep game='Nuts' />
            </aside>
          )}
        </div>
        <DownGame game='Nuts' setLD={setLD} lastDep={lastDep} betsAlwaysActive={isWide}/>
        {!isWide && lastDep && <SlideIn><LastDep game='Nuts'/></SlideIn>}
        <SectMore game='Nuts' />
      </div>
    </div>
  );
}
