export default function CoinFlipGamesPage() {
  const { signOut, profile } = useAuth()
  const { state, updateState } = useAppState()
  const [lastDep, setLD] = useState(false)
  const isWide = useIsWide()
  const [ mode, setMode ] = useState(true)
  const [ bet, setBet ] = useState('10')

  return(
    <div className="container">
      <div className="game-inhouse-frame">
        <div className="game-inhouse-frame__window">
          <div className="game-inhouse-frame__stage">
            <div className="game-inhouse-frame__area">
              <FieldCF state={state} profile={profile} mode={mode} setMode={setMode} bet={bet}/>
              <FormCF state={state} profile={profile} mode={mode} setMode={setMode} bet={bet} setBet={setBet}/>
            </div>
          </div>
          {isWide && (
            <aside className="game-inhouse-frame__panel">
              <LastDep game='CoinFlip' />
            </aside>
          )}
        </div>
        <DownGame game='CoinFlip' setLD={setLD} lastDep={lastDep} betsAlwaysActive={isWide}/>
        {!isWide && lastDep && <SlideIn><LastDep game='CoinFlip'/></SlideIn>}
      </div>
      <SectMore game='CoinFlip' />
    </div>
  );
}
