import { useEffect, useState } from 'react'
import mess from '../../../../lib/message.jsx'
import { supabase } from '../../../../supabase.js'
import { markSupabaseCall } from '../../../../lib/DEF_DATA.js'
import { useAuthModal } from '../../../../context/AuthModalContext'
import { setTrueCoin } from './Body.jsx'
import '../css/right-bet.css'

async function cf_norm_run( profile, choice, openAuth ) {
  if(profile === null){
    openAuth()
  }else {
    if (choice==='P' || choice==='O') {
      try {
        markSupabaseCall('CFNormRun', 'pending')
        const { data, error } = await supabase.functions.invoke('CFNormRun', {
          body: { coin: choice }
        })
        if (error) {
          console.error('Error run CF game:', error)
          markSupabaseCall('CFNormRun', 'error', error?.message || String(error))
          mess(500, error || 'Ошибка запуска игры')
        } else if(data?.error) {
          markSupabaseCall('CFNormRun', 'error', data.error)
          mess(400, data.error)
        } else if (data) {
          markSupabaseCall('CFNormRun', 'ok')
          setTrueCoin(data.TRUE_COIN)
          mess(200, data)
        } else if (data?.success) {
          mess(200, data)
        } else {
          mess(500, 'Неизвестный ответ от сервера')
        }
      } catch (err) {
        console.error('Network error run CF game:', err)
        markSupabaseCall('CFNormRun', 'error', err?.message || String(err))
        mess(500, 'Ошибка подключения к серверу')
      }
    } else if(!profile.CoinFlip.play){
      mess(400, "Игра неактивна")
    }else {
      mess(400, "Неверные параметры")
    }
  }
}

async function cf_norm_exit( profile, openAuth ) {
  if(profile === null) {
    openAuth()
  }else {
    if (profile?.CoinFlip?.play) {
      try {
        markSupabaseCall('CFNormExit', 'pending')
        const { data, error } = await supabase.functions.invoke('CFNormExit', {
          body: {  }
        })
        if (error) {
          console.error('Error exit CF game:', error)
          markSupabaseCall('CFNormExit', 'error', error?.message || String(error))
          mess(500, error || 'Ошибка заканчивания игры')
        } else if(data?.error) {
          markSupabaseCall('CFNormExit', 'error', data.error)
          mess(400, data.error)
        } else if (data) {
          markSupabaseCall('CFNormExit', 'ok')
          mess(200, data)
        } else if (data?.success) {
          mess(200, data)
        } else {
          mess(500, 'Неизвестный ответ от сервера')
        }
      } catch (err) {
        console.error('Network error run CF game:', err)
        markSupabaseCall('CFNormExit', 'error', err?.message || String(err))
        mess(500, 'Ошибка подключения к серверу')
      }
    } else if(!profile.CoinFlip.play){
      mess(400, "Игра неактивна")
    }else {
      mess(400, "Неверные параметры")
    }
  }
}
async function cf_norm_start( profile, bet, openAuth, setButtonState ) {
  if(profile === null) {
    openAuth()
  }else {
    if ((profile?.balance >= bet) && !(profile?.CoinFlip?.play)) {
      try {
        markSupabaseCall('CFNormStart', 'pending')
        const { data, error } = await supabase.functions.invoke('CFNormStart', {
          body: { dep: bet }
        })
        if (error) {
          console.error('Error start CF game:', error)
          markSupabaseCall('CFNormStart', 'error', error?.message || String(error))
          mess(500, error || 'Ошибка создания игры')
        } else if(data?.error) {
          markSupabaseCall('CFNormStart', 'error', data.error)
          mess(400, data.error)
        } else if (data) {
          markSupabaseCall('minerStart', 'ok')
          setButtonState('choose')
          mess(200, data)
        } else if (data?.success) {
          setButtonState('choose')
          mess(200, data)
        } else {
          mess(500, 'Неизвестный ответ от сервера')
        }
      } catch (err) {
        console.error('Network error run CF game:', err)
        markSupabaseCall('CFNormStart', 'error', err?.message || String(err))
        mess(500, 'Ошибка подключения к серверу')
      }
    } else if(profile?.CoinFlip?.play){
      mess(400, "Игра активна")
    }else {
      mess(400, "Неверные параметры")
    }
  }
}

export default function FormCF({state, profile, mode, bet, setBet, setMode}) {
  const [ showPresets, setShowPresets ] = useState(false)
  const [ tempValue, setTempValue ] = useState(bet.toString())
  const [ buttonState, setButtonState ] = useState(profile?.CoinFlip?.play ? (profile?.CoinFlip?.arrCoin.length > 0 ? 'cashout' : 'choose') : 'play')
  const { openAuth, openReg } = useAuthModal()
  
  const BET_MIN = 0.01
  const BET_MAX = () => Number(profile?.balance ?? 0)
  const BET_DEFAULT = 10

  const betPresets = [2, 5, 25, 100, 250]

  const handlePresetChange = (preset) => {
    setTempValue(preset.toString())
    setBet(preset)
    setShowPresets(false)
  }

  const clampValue = (num) => {
    return Math.max(BET_MIN, Math.min(BET_MAX(), num))
  }

  const validateAndNormalize = (raw) => {
    let normalized = raw.toString().replace(',', '.')
    const num = parseFloat(normalized)
    if (isNaN(num)) return BET_DEFAULT
    return clampValue(num)
  }

  useEffect(() => {
    setTempValue(bet.toString())
  }, [bet])

  const handleChange = (e) => {
    const rawValue = e.target.value
    setTempValue(rawValue)
    if (rawValue.length > 1 && rawValue.startsWith('0') && !rawValue.startsWith('0.') && !isNaN(rawValue[1])) {
      setTempValue(rawValue.substring(1))
    }
  }

  const handleBlur = () => {
    setShowPresets(false)
    const validated = validateAndNormalize(tempValue)
    setTempValue(validated.toString())
    setBet(validated)
  }

  const handleHalf = () => {
    const newValue = Number(bet) / 2
    const clamped = clampValue(newValue)
    setTempValue(clamped.toString())
    setBet(clamped)
  }

  const handleDouble = () => {
    const newValue = Number(bet) * 2
    const clamped = clampValue(newValue)
    setTempValue(clamped.toString())
    setBet(clamped)
  }

  useEffect(() => {
    if (profile?.CoinFlip) {
      const coinFlip = profile.CoinFlip
      const newButtonState = coinFlip.play ? 
      (coinFlip.arrCoin?.length > 0 ? 'cashout' : 'choose') : 'play'
      setButtonState(newButtonState)
    }
  }, [profile?.CoinFlip?.play, profile?.CoinFlip?.arrCoin])

  return(
    <div class="coinflip-game-form">
      <div class="game-form-group">
        <div class="game-form">
          <div class="game-form-header">
            <label class="game-form__label" for="bet_693746">Ставка</label>
            <div class="game-form__label-help">
              <span>От 0.01 до <strong>{BET_MAX().toFixed(2)}</strong></span>
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path d="M320.388 0H170.664c-23.256 0-42.109 18.853-42.109 42.11v171.78H85.11C61.853 213.89 43 232.744 43 256c0 23.257 18.853 42.11 42.11 42.11h43.445v44.114H85.11c-23.257 0-42.11 18.853-42.11 42.11 0 23.256 18.853 42.109 42.11 42.109h43.445v43.447c0 23.257 18.853 42.11 42.109 42.11 23.257 0 42.11-18.853 42.11-42.11v-43.447h86.224c23.257 0 42.11-18.853 42.11-42.109 0-23.257-18.853-42.11-42.11-42.11h-86.224V298.11h107.614c82.187 0 149.053-66.866 149.053-149.054C469.441 66.866 402.577 0 320.388 0zm0 213.888H212.774V84.218h107.614c35.749 0 64.834 29.083 64.834 64.834 0 35.751-29.083 64.836-64.834 64.836z"></path></svg>
            </div>
          </div> 
          <div class="game-form-body">
            <div class="game-form__input-icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path d="M320.388 0H170.664c-23.256 0-42.109 18.853-42.109 42.11v171.78H85.11C61.853 213.89 43 232.744 43 256c0 23.257 18.853 42.11 42.11 42.11h43.445v44.114H85.11c-23.257 0-42.11 18.853-42.11 42.11 0 23.256 18.853 42.109 42.11 42.109h43.445v43.447c0 23.257 18.853 42.11 42.109 42.11 23.257 0 42.11-18.853 42.11-42.11v-43.447h86.224c23.257 0 42.11-18.853 42.11-42.109 0-23.257-18.853-42.11-42.11-42.11h-86.224V298.11h107.614c82.187 0 149.053-66.866 149.053-149.054C469.441 66.866 402.577 0 320.388 0zm0 213.888H212.774V84.218h107.614c35.749 0 64.834 29.083 64.834 64.834 0 35.751-29.083 64.836-64.834 64.836z"></path></svg>
            </div> 
            <div class="game-form__input">
              <input 
                type="text" 
                id="bet_693746" 
                name="bet_693746" 
                value={tempValue}
                onFocus={() => setShowPresets(true)}
                onBlur={handleBlur}
                onChange={handleChange} 
              />
            </div> 
            <div class="game-form-tools">
              <button aria-label="Divide" class="game-form-tools__item game-form-tools__item_divider" onClick={handleHalf}>
                <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path d="M342.01 73.072c-9.904-5.95-22.616-2.505-28.392 7.695L119.859 422.902c-5.777 10.202-2.432 23.294 7.47 29.246 9.904 5.95 22.615 2.504 28.393-7.696l193.759-342.135c5.778-10.202 2.433-23.295-7.471-29.245z"></path><path fill-rule="evenodd" d="M303.71 75.164c8.849-15.626 28.632-21.175 44.167-11.842 15.324 9.207 20.253 29.164 11.512 44.598L165.63 450.056c-8.85 15.623-28.631 21.176-44.167 11.842l-.002-.001c-15.32-9.208-20.25-29.164-11.511-44.598L303.71 75.164zM119.859 422.902L313.618 80.767c5.776-10.2 18.488-13.645 28.392-7.695 9.904 5.95 13.249 19.043 7.471 29.245L155.722 444.452c-5.778 10.2-18.489 13.646-28.393 7.696-9.902-5.952-13.247-19.044-7.47-29.246z" clip-rule="evenodd"></path><path d="M86.668 255.973c0 15.708 12.743 28.442 28.462 28.442s28.462-12.734 28.462-28.442V28.441C143.592 12.734 130.849 0 115.13 0H66.462C50.743 0 38 12.734 38 28.442c0 15.707 12.743 28.441 28.462 28.441h20.206v199.09zM446.541 454.55c-.119 0-.244 0-.364.002-20.193.254-41.528.43-59.996.491 12.079-16.234 28.229-38.409 49.359-68.576 14.504-20.706 23.974-40.332 28.151-58.33.734-3.982 1.715-11.018 1.838-15.059 0-47.169-38.402-85.544-85.606-85.544-40.814 0-76.141 29.016-84 68.995-3.031 15.414 7.018 30.362 22.443 33.39 15.428 3.027 30.384-7.015 33.414-22.427 2.628-13.371 14.464-23.075 28.145-23.075 15.311 0 27.859 12.05 28.644 27.158l-.633 4.958c-2.702 10.501-9.26 23.367-19.03 37.317-35.337 50.452-56.419 78.038-67.745 92.858-14.222 18.608-21.36 27.948-16.567 43.519 2.839 9.221 9.814 16.291 19.138 19.397 3.751 1.25 7.125 2.376 51.131 2.376 17.085 0 40.3-.171 72.031-.569 15.719-.197 28.301-13.091 28.104-28.798-.2-15.586-12.903-28.083-28.457-28.083z"></path></svg>
              </button> 
              <button aria-label="Multiply" class="game-form-tools__item game-form-tools__item_multiplier" onClick={handleDouble}>
                <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><g><path d="M472.034 374.655c-.167 0-.343 0-.511.003-28.358.356-58.32.604-84.255.689 16.963-22.788 39.643-53.914 69.317-96.258 20.368-29.064 33.668-56.613 39.533-81.876 1.031-5.589 2.409-15.466 2.582-21.137C498.7 109.866 444.769 56 378.48 56c-57.318 0-106.929 40.729-117.966 96.846-4.255 21.636 9.857 42.619 31.518 46.869 21.667 4.248 42.67-9.847 46.925-31.48 3.691-18.769 20.313-32.39 39.526-32.39 21.501 0 39.123 16.914 40.226 38.12l-.89 6.96c-3.795 14.739-13.004 32.8-26.725 52.381-49.624 70.817-79.231 109.539-95.137 130.341-19.972 26.12-29.996 39.231-23.265 61.087 3.986 12.943 13.781 22.867 26.876 27.227 5.268 1.754 10.006 3.335 71.805 3.335 23.993 0 56.595-.24 101.157-.799 22.074-.277 39.744-18.375 39.467-40.423-.28-21.877-18.12-39.419-39.963-39.419z"></path><rect width="62.273" height="311.256" x="166.59" y="107.522" rx="31.136" transform="rotate(32.359 166.59 107.522)"></rect><rect width="62.273" height="311.256" rx="31.136" transform="scale(-1 1) rotate(32.359 -211.597 -36.89)"></rect></g></svg>
              </button>
            </div>
          </div> 
          <div class={`game-form-presets ${showPresets ? 'game-form-presets_visible' : 'game-form-presets_hidden'}`}>
            {betPresets.map((preset) => (
              <button 
                key={preset} 
                class="game-form-presets__item_cl"
                onMouseDown={() => handlePresetChange(preset)}
              >
                {preset}
              </button>
            ))}
          </div>
        </div>
        <div class="game-form">
          <div class="game-form-header">
            <label class="game-form__label">Режим игры</label>
            <div class="game-form__label-help">
              <span>Раунды — <strong>{mode ? '20' : '1'}</strong></span>
            </div>
          </div> 
          <div class="game-form-body">
            <div class="game-form__input">
              <div class="tab-select" id="tab-select_517653">
                <div class="tab-select-items-wrapper tab-select-items-wrapper_with-right-shadow">
                  <div class="tab-select-items tab-select-items tab-select-items_wide">
                    <button onClick={() => {setMode(true); setButtonState('play')}}
                      class={`tab-select-items__item ${mode && 'tab-select-items__item_active'}`}>
                      <span>С умножением</span>
                    </button>
                    <button onClick={() => {setMode(false); setButtonState('choose')}}
                      class={`tab-select-items__item ${!mode && 'tab-select-items__item_active'}`}>
                      <span>Быстрая игра</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div> 
      <button 
        className={`game-form-button ${buttonState === 'cashout' ? 'game-form-button_green' : buttonState === 'choose' ? 'game-form-button_blue_np' : 'game-form-button_blue'}`}
        onClick={() => {
          if (buttonState === 'play') {
            cf_norm_start(profile, bet, openAuth, setButtonState)
          } else if (buttonState === 'choose') {
            cf_norm_run(profile, mode ? 'O' : 'P', openAuth)
          } else if (buttonState === 'cashout') {
            cf_norm_exit(profile, openAuth)
          }
        }}
      >
        <span class="game-form-button-content">
          <span className={`kkkeno-terxt game-form-button__text state-${buttonState}`} key={buttonState}>
            <span>{buttonState==='play' ? 'ИГРАТЬ' : buttonState==='choose' ? 'ВЫБЕРИТЕ' : 'ЗАБРАТЬ'}</span>
            <strong>
              {buttonState==='choose' ? 'ЯЧЕЙКУ' : buttonState==='cashout' 
              && `${profile?.CoinFlip?.arrCoin.length > 0 ? (profile?.CoinFlip?.dep * profile?.CoinFlip?.k).toFixed(2) : '0.00'} ₽`}
            </strong>
          </span>
        </span>
      </button>
    </div>
  )
}