import { useState, useEffect, useRef } from 'react'

export default function SlideIn({ children, delay = 0 }) {
  const [visible, setVisible] = useState(false)
  const [removing, setRemoving] = useState(false)
  const [mounted, setMounted] = useState(false)
  const childRef = useRef(null)

  useEffect(() => {
    if (children) {
      setMounted(true)
      const timer = setTimeout(() => setVisible(true), delay)
      return () => clearTimeout(timer)
    } else if (mounted) {
      setRemoving(true)
      const timer = setTimeout(() => setVisible(false), 600)
      return () => clearTimeout(timer)
    }
  }, [children, delay, mounted])

  useEffect(() => {
    if (visible && mounted && childRef.current) {
      requestAnimationFrame(() => {
        childRef.current?.classList.add('last-dep-anim_visible')
      })
    }
  }, [visible, mounted])

  if (!visible) return null

  return (
    <div
      ref={childRef}
      className={`last-dep-anim${removing ? ' last-dep-anim_removing' : ''}`}
    >
      {children}
    </div>
  )
}
