import React from 'react';

const menuItems = [
  { href: '/help/account', label: 'Аккаунт', key: 'account' },
  { href: '/help/payments', label: 'Платежи и выплаты', key: 'payments' },
  { href: '/help/bonuses', label: 'Бонусная программа', key: 'bonuses' },
  { href: '/help/gameplay', label: 'Геймплей', key: 'gameplay' },
  { href: '/help/affiliate', label: 'Партнерка', key: 'affiliate' },
  { href: '/help/rules', label: 'Правила', key: 'rules' },
];

export default function HelpMenu({ active }) {
  return (
    <div className="help-page-menu">
      <div className="help-menu">
        <div className="help-menu-items">
          {menuItems.map((item) => (
            <a
              key={item.key}
              href={item.href}
              className={`help-menu-item ${active === item.key ? 'help-menu-item_active' : ''}`}
              aria-current={active === item.key ? 'page' : undefined}
            >
              {item.label}
            </a>
          ))}
        </div>
      </div>
    </div>
  );
}