import React, { useState, useEffect } from 'react';
import '../css/DepAndMines.css';
import { supabase } from '../../../../supabase'
import { useAuth } from '../../../../context/AuthContext'
import { MII, RUB } from '../../../../img/ICOdiv/ROCICO'
import mess from '../../../../lib/message'
import { useAppState } from '../../../../hooks/useState'
import { INIT_DATA, markSupabaseCall } from '../../../../lib/DEF_DATA'

export const K_WAM = [0.00, 0.00, false]
export let exit_bet_uuid = false

async function minerCreate(dep, bombs, profile, state, updateState, updateStateWithoutDB) {
  if (!profile) {
    mess(400, "Профиль не загружен")
    return
  }
  if (profile.balance - dep >= 0 && bombs > 0 && bombs <= 25) {
    try {
      markSupabaseCall('minerCreate', 'pending')
      const { data, error } = await supabase.functions.invoke('Miner-create', {
        body: { dep, bombs }
      })
      
      if (error) {
        console.error('Error creating miner game:', error)
        markSupabaseCall('minerCreate', 'error', error?.message || String(error))
        mess(500, error.message || 'Ошибка создания игры')
      } else if (data?.error) {
        markSupabaseCall('minerCreate', 'error', data.error)
        mess(400, data.error)
      } else if (data) {
        markSupabaseCall('minerCreate', 'ok')
        INIT_DATA.round = 0
        K_WAM[0] = 0; K_WAM[1] = 0; K_WAM[2] = false
        updateState('miner', Array(25).fill(false))
        updateState('minerOpened', Array(25).fill(false))
        updateState('miner_overgame', false)
        mess(200, 'Игра создана успешно')
      } else {
        mess(500, 'Неизвестный ответ от сервера')
      }
    } catch (err) {
      console.error('Network error creating miner game:', err)
      mess(500, 'Ошибка подключения к серверу')
    }
  } else {
    mess(400, "Неверные параметры")
  }
}

async function minerLeave(profile, state, updateState, updateStateWithoutDB) {
  if (!profile) {
    mess(400, "Профиль не загружен")
    return
  }
  const minerData = profile.games?.Miner || profile.Miner
  if (!minerData || !minerData.play || minerData.zone === false) {
    mess(400, "Игра не активна")
    return
  }
  if (minerData.round > 0 || minerData.k > 1) {
    try {
      markSupabaseCall('minerExit', 'pending')
      const { data, error } = await supabase.functions.invoke('Miner-exit', {
        body: { action: 'exit' },
      })
      if (error) {
        console.error('Error exiting miner game:', error)
        markSupabaseCall('minerExit', 'error', error?.message || String(error))
        mess(500, error.message || 'Ошибка выхода из игры')
        throw error
      } else if (data?.error) {
        markSupabaseCall('minerExit', 'error', data.error)
        mess(400, data.error)
      } else if (data) {
        markSupabaseCall('minerExit', 'ok')
        updateState('miner', data.zone)
        const newMinerOpened = [...state.minerOpened].map((item) => item===false ? item="F" : item)
        updateState('minerOpened', newMinerOpened)
        if(data.sek){K_WAM[0] = data.k; K_WAM[1] = data.win; K_WAM[2] = true}
        mess(200, data)
      } if (!error) {
        exit_bet_uuid = data?.bet_uuid
      }
      return data
    } catch (err) {
      console.error('Network error exiting miner game:', err)
      mess(500, 'Ошибка подключения к серверу')
    }
  } else {
    mess(400, "Выберите хотя бы 1 клетку")
  }
}

function GameInput({ label, value, onValueChange, presets, isMines, defaultValue, profile, zp = [] }) {
  const [showPresets, setShowPresets] = useState(false);
  const [tempValue, setTempValue] = useState(value.toString());

  useEffect(() => {
    setTempValue(value.toString())
  }, [value])

  const getMin = () => isMines ? 1 : 0.01;
  const getMax = () => isMines ? 25 : Number(profile?.balance ?  profile.balance : 25000);
  const getDefault = () => defaultValue || (isMines ? 5 : 10);

  const clampValue = (num) => {
    return Math.max(getMin(), Math.min(getMax(), num));
  };

  const validateAndNormalize = (raw) => {
    let normalized = raw.toString().replace(',', '.');
    const num = parseFloat(normalized);
    
    if (isNaN(num)) {
      return getDefault();
    }

    let finalNum = num;
    if (isMines) {
      finalNum = Math.ceil(num);
    }
    
    return clampValue(finalNum);
  };

  const handleChange = (e) => {
    const rawValue = e.target.value;
    setTempValue(rawValue);
    
    if (rawValue.length > 1 && rawValue.startsWith('0') && !rawValue.startsWith('0.') && !isNaN(rawValue[1])) {
      const newValue = rawValue.substring(1);
      setTempValue(newValue);
    }
  };

  const handleBlur = () => {
    setShowPresets(false);
    const validated = validateAndNormalize(tempValue);
    setTempValue(validated.toString());
    onValueChange(validated)
  };

  const handleHalf = () => {
    const newValue = Number(value) / 2;
    const finalValue = isMines ? Math.ceil(newValue) : newValue;
    const clamped = clampValue(finalValue);
    setTempValue(clamped.toString());
    onValueChange(clamped);
  };
  
  const handleDouble = () => {
    const newValue = Number(value) * 2;
    const finalValue = isMines ? Math.ceil(newValue) : newValue;
    const clamped = clampValue(finalValue);
    setTempValue(clamped.toString());
    onValueChange(clamped);
  };

  const handlePresetChange = (preset) => {
    setTempValue(preset.toString());
    onValueChange(preset);
  };

  return (
    <div className="game-form">
      <div className="game-form-header">
        <label className="game-form__label">{label}</label>
        <div className="game-form__label-help">
          {isMines ? "От 1 до 24 мин" : "Ставка от 0.01₽"}
        </div>
      </div>
      <div className={`game-form-body ${zp[0] ? 'opanotal' : ''}`}>
        <div className="game-form__input-icon">
          {isMines ? <span style={{fontSize: '14px'}}><MII width='18' height='18' cn=''/></span> : <span style={{fontWeight:'bold'}}><RUB width='14' height='14' bold={true} cn='game-form__input-icon-two' /></span>}
        </div>
        <div className={`game-form__input${zp[0] ? ' opanotal' : ''}`}>
          <input
            readOnly={zp[0]}
            type="text" 
            value={tempValue} 
            onFocus={() => setShowPresets(true)}
            onBlur={handleBlur}
            onChange={handleChange} 
          />
        </div>
        <div className="game-form-tools">
          <button disabled={zp[0]} className="game-form-tools__item" onClick={handleHalf}>½</button>
          <button disabled={zp[0]} className="game-form-tools__item" onClick={handleDouble}>x2</button>
        </div>
      </div>
      <div className={`game-form-presets ${isMines ? 'game-form-presets_mines' : ''} ${showPresets ? "game-form-presets_visible" : "game-form-presets_hidden" }`}>
        {presets.map((preset) => (
          <button 
            key={preset} 
            className="game-form-presets__item_cl"
            onMouseDown={() => handlePresetChange(preset)}
          >
            {isMines && preset === 5 ? '5' : preset}
          </button>
        ))}
      </div>
    </div>
  );
}

export default function DepAndMines({ bet, setBet, mines, setMines, profile }) {
  const { profile: authProfile } = useAuth()
  const [z, setZ] = useState(false)
  const [play, setPlay] = useState(profile?.Miner?.play ?? false)
  const [winAmount, setWA] = useState(0)
  const betPresets = [2, 5, 25, 100, 250];
  const minesGrid = Array.from({ length: 25 }, (_, i) => i + 1);
  const currentProfile = profile || authProfile
  const minerData = currentProfile?.Miner || {}
  const minerRound = minerData.round || false
  const minerK = minerData.k || 1
  const minerPlay = minerData.play ?? false
  const { state, updateState, updateStateWithoutDB } = useAppState()

  const formatWinAmount = (num) => {
    const formatted = num.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
    if (formatted.length > 24) {
      const half = Math.ceil(formatted.length / 2);
      return (
        <>
          {formatted.slice(0, half)}
          <br />
          {formatted.slice(half)}
        </>
      );
    }
    return formatted;
  };

  useEffect(() => {
    setPlay(minerPlay)
  }, [minerPlay])

  useEffect(() => {
    const newZ = minerPlay && minerRound !== false && minerRound !== 0
    const newWA = minerData?.dep * minerK
    const clampedBet = Math.min(bet, Number(profile?.balance) || 0)
    setZ(newZ)
    setWA(newWA)
    if (clampedBet !== bet) {
      setBet(clampedBet)
    }
  }, [minerRound, minerK, minerPlay, minerData?.dep, profile?.balance, bet, setBet])


  const handleCreate = async () => {
    await minerCreate(bet, mines, currentProfile, state, updateState, updateStateWithoutDB)
  }

  const handleLeave = async () => {
    await minerLeave(currentProfile, state, updateState, updateStateWithoutDB)
  }

  if (!currentProfile || !currentProfile.Miner) {
    return (
      <div className="miner-game-footer">
        <div className="miner-game-form">
          <div className="game-form-group">
            <GameInput 
              label="Ставка"
              value={bet}
              onValueChange={setBet}
              presets={betPresets}
              isMines={false}
              defaultValue={10}
              profile={profile}
            />
            <GameInput 
              label="Мины"
              value={mines}
              onValueChange={setMines}
              presets={minesGrid}
              isMines={true}
              defaultValue={5}
              profile={profile}
            />
          </div>
        </div>
        
        <button 
          className="game-form-button game-form-button_blue"
          disabled
        >
          <span className="game-form-button-content">
            <span className="game-form-button__text">
              Загрузка...
            </span>
          </span>
        </button>
      </div>
    )
  }

  return (
    <div className="miner-game-footer">
      <div className="miner-game-form">
        <div className="game-form-group">
          <GameInput 
            label="Ставка"
            value={bet}
            onValueChange={setBet}
            presets={betPresets}
            isMines={false}
            defaultValue={10}
            profile={profile}
            zp={[z, play]}
          />
          <GameInput 
            label="Мины"
            value={mines}
            onValueChange={setMines}
            presets={minesGrid}
            isMines={true}
            defaultValue={5}
            profile={profile}
            zp={[z, play]}
          />
        </div>
      </div>
      
      <button 
        className={`game-form-button ${z ? 'game-form-button_green' : play ? 'game-form-button_blue_np' : 'game-form-button_blue'}`}
        onClick={z ? handleLeave : (play ? undefined : handleCreate)}
      >
        <span className="game-form-button-content">
          <span className={`text-fix-miner text-minerrr game-form-button__text ${z ? 'state-cashout true-text-miner-fix' : play ? 'state-choose true-text-miner-fix' : 'state-play'}`}>
            {z ? (
              <>ЗАБРАТЬ
                <strong>{formatWinAmount(winAmount)} ₽</strong>
              </>
            ) : play ? (
              <>
                <span>ВЫБЕРИТЕ</span>
                <strong>ЯЧЕЙКУ</strong>
              </>
            ) : (
              'ИГРАТЬ'
            )}
          </span>
        </span>
      </button>
    </div>
  );
}