const DB_NAME = 'AppDB';
const DB_VERSION = 3;

export const STORES = {
  USER: 'user',
  PROFILE: 'profile',
  SETTINGS: 'settings',
  STATE: 'state'
};

const PROFILE_EXCLUDE_FIELDS = [
  'Miner.zone',
  'Nuts.nutsArea'
];

export const openDB = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
    
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      
      if (!db.objectStoreNames.contains(STORES.USER)) {
        db.createObjectStore(STORES.USER, { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains(STORES.PROFILE)) {
        db.createObjectStore(STORES.PROFILE, { keyPath: 'uuid' });
      }
      if (!db.objectStoreNames.contains(STORES.SETTINGS)) {
        db.createObjectStore(STORES.SETTINGS, { keyPath: 'key' });
      }
      if (!db.objectStoreNames.contains(STORES.STATE)) {
        db.createObjectStore(STORES.STATE, { keyPath: 'key' });
      }
    };
  });
};

// ==================== ПОМОЩНИКИ ====================

const excludeFields = (obj, excludeList) => {
  if (!obj || typeof obj !== 'object') return obj;
  
  const result = { ...obj };
  
  excludeList.forEach(fieldPath => {
    const parts = fieldPath.split('.');
    let current = result;
    
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      
      if (i === parts.length - 1) {
        delete current[part];
      } else {
        if (current[part] && typeof current[part] === 'object') {
          current = current[part];
        } else {
          break;
        }
      }
    }
  });
  
  return result;
};

// ==================== ОБЩИЕ МЕТОДЫ ====================

export const saveToDB = async (storeName, data) => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(storeName, 'readwrite');
    const store = transaction.objectStore(storeName);
    const request = store.put(data);
    
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const getFromDB = async (storeName, key) => {
  if (key === null || key === undefined) {
    return null;
  }
  
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(storeName, 'readonly');
    const store = transaction.objectStore(storeName);
    const request = store.get(key);
    
    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => reject(request.error);
  });
};

export const removeFromDB = async (storeName, key) => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(storeName, 'readwrite');
    const store = transaction.objectStore(storeName);
    const request = store.delete(key);
    
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
};

// ==================== ПОЛЬЗОВАТЕЛЬ ====================

export const saveUserData = async (user, profile) => {
  if (user) {
    await saveToDB(STORES.USER, {
      id: user.id,
      email: user.email,
      email_verified: user.email_verified,
      phone: user.phone,
      role: user.role,
      aud: user.aud,
      created_at: user.created_at,
      last_sign_in_at: user.last_sign_in_at,
      app_metadata: user.app_metadata,
      user_metadata: user.user_metadata,
      saved_at: Date.now()
    });
  }
  
  if (profile) {
    await saveToDB(STORES.PROFILE, {
      ...profile,
      saved_at: Date.now()
    });
  }
};

export const loadUserData = async (userId) => {
  const user = await getFromDB(STORES.USER, userId);
  const profile = await getFromDB(STORES.PROFILE, userId);
  return { user, profile };
};

export const removeUserData = async (userId) => {
  await removeFromDB(STORES.USER, userId);
  await removeFromDB(STORES.PROFILE, userId);
};

// ==================== НАСТРОЙКИ ====================

export const saveSetting = async (key, value) => {
  await saveToDB(STORES.SETTINGS, { key, value, updated_at: Date.now() });
};

export const getSetting = async (key) => {
  const result = await getFromDB(STORES.SETTINGS, key);
  return result?.value || null;
};

export const getAllSettings = async () => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORES.SETTINGS, 'readonly');
    const store = transaction.objectStore(STORES.SETTINGS);
    const request = store.getAll();
    
    request.onsuccess = () => {
      const settings = {};
      request.result.forEach(item => {
        settings[item.key] = item.value;
      });
      resolve(settings);
    };
    request.onerror = () => reject(request.error);
  });
};

export const removeSetting = async (key) => {
  await removeFromDB(STORES.SETTINGS, key);
};

export const saveSettingsBatch = async (settings) => {
  const db = await openDB();
  const transaction = db.transaction(STORES.SETTINGS, 'readwrite');
  const store = transaction.objectStore(STORES.SETTINGS);
  
  Object.entries(settings).forEach(([key, value]) => {
    store.put({ key, value, updated_at: Date.now() });
  });
  
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
  });
};

export const clearAllSettings = async () => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORES.SETTINGS, 'readwrite');
    transaction.objectStore(STORES.SETTINGS).clear();
    
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
  });
};

