import { useState, useEffect, useRef } from "react"
import { supabase } from '../../../../supabase'
import mess from "../../../../lib/message"
import '../css/dep.css'

async function NutsCreate(dep, stones, profile, setSST, proccesing, setProcessing, setResult) {
  if (!profile) {
    mess(400, "Профиль не загружен")
    return
  }
  if (profile.balance - dep >= 0 && stones>0 && stones<5) {
    try {
      const { data, error } = await supabase.functions.invoke('Nuts-start', {
        body: { dep, stones }
      })
      
      if (error) {
        console.error('Error creating nuts game:', error)
        mess(500, error.message || 'Ошибка создания игры')
      } else if (data?.error) {
        mess(400, data.error)
      } else if (data) {
        setSST('choose')
        setProcessing(false)
        setResult([false, false])
        mess(200, 'Игра создана успешно')
      } else {
        mess(500, 'Неизвестный ответ от сервера')
      }
    } catch (err) {
      console.error('Network error creating nuts game:', err)
      mess(500, 'Ошибка подключения к серверу')
    }
  } else {
    mess(400, "Неверные параметры")
  }
}
async function NutsExit(profile, setSST, setResult) {
  if (!profile) {
    mess(400, "Профиль не загружен")
    return
  }
  if (!profile?.Nuts?.nutsArea) {
    mess(400, "Игра не активна")
    return
  }
  if (profile.Nuts.stringNuts > 0 || profile.Nuts.k > 0) {
    try {
      const { data, error } = await supabase.functions.invoke('Nuts-exit', {
        body: { action: 'exit' },
      })
      if (error) {
        console.error('Error exiting nuts game:', error)
        mess(500, error.message || 'Ошибка выхода из игры')
        throw error
      } else if (data?.error) {
        mess(400, data.error)
      } else if (data) {
        setSST('start')
        setResult(data?.area ? [true, data.area] : [false, false])
        mess(200, data)
      } if (!error) {
        mess(500, 'Неизвестный ответ от сервера')
      }
      return data
    } catch (err) {
      console.error('Network error exiting nuts game:', err)
      mess(500, 'Ошибка подключения к серверу')
    }
  } else {
    mess(400, "Выберите хотя бы 1 клетку")
  }
}

