  const BET_MIN = 0.01
  const BET_MAX = () => Number(profile?.balance ?? 0)
  const BET_DEFAULT = 10

  const clampValue = (num) => {
    return Math.max(BET_MIN, Math.min(BET_MAX(), num))
  }

  const validateAndNormalize = (raw) => {
    let normalized = raw.toString().replace(',', '.')
    const num = parseFloat(normalized)
    if (isNaN(num)) return BET_DEFAULT
    return clampValue(num)
  }

  useEffect(() => {
    setTempValue(bet.toString())
  }, [bet])

  const handlePresetChange = (preset) => {
    prevValueRef.current = preset.toString()
    setTempValue(preset.toString())
    setBet(preset)
    setShowPresets(false)
  }

  const handleChange = (e) => {
    const rawValue = e.target.value
    if (rawValue === '' || /^\d*\.?\d*$/.test(rawValue)) {
      if (rawValue === '' || (rawValue.length > 1 && rawValue.startsWith('0') && !rawValue.startsWith('0.') && !isNaN(rawValue[1]))) {
        setTempValue(prevValueRef.current)
        return
      }
      setTempValue(rawValue)
    }
  }

  const handleBlur = () => {
    setShowPresets(false)
    const validated = validateAndNormalize(tempValue)
    const finalStr = validated.toString()
    prevValueRef.current = finalStr
    setTempValue(finalStr)
    setBet(validated)
  }

  const handleHalf = () => {
    const newValue = Number(bet) / 2
    const clamped = clampValue(newValue)
    const finalStr = clamped.toString()
    prevValueRef.current = finalStr
    setTempValue(finalStr)
    setBet(clamped)
  }

  const handleDouble = () => {
    const newValue = Number(bet) * 2
    const clamped = clampValue(newValue)
    const finalStr = clamped.toString()
    prevValueRef.current = finalStr
    setTempValue(finalStr)
    setBet(clamped)
  }

