import React, { createContext, useContext, useEffect, useState, useRef } from 'react';
import { supabase } from '../supabase';
import { saveUserData, loadUserData, removeUserData, clearAll } from '../lib/indexedDB';
import { beginAuthFlow, endAuthFlow } from '../lib/DEF_DATA';
import { registerBalanceFlushHandler, isBalanceHeld, queueHeldProfile } from '../lib/balanceHold';
import { useAppState } from '../hooks/useState';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const [loadingDB, setLoadingDB] = useState(true);
  const [loadingServer, setLoadingServer] = useState(false);
  const [isFullyLoaded, setIsFullyLoaded] = useState(false);
  
  const channelRef = useRef(null);
  const { state } = useAppState();

  const log = (...args) => {
    if (state.dev?.view?.logsAuthRT) {
      console.log('[AuthContext]', ...args);
    }
  };

  const error = (...args) => {
    if (state.dev?.view?.logsAuthRT) {
      console.error('[AuthContext]', ...args);
    }
  };

  const fetchProfile = async (userId) => {
    if (state.dev?.view?.logsAuthRT) {
      const start = performance.now();
      log(`fetchProfile called for user: ${userId}`);
      
      try {
        setLoadingServer(true);
        
        const { data, error: fetchError } = await supabase
          .from('profiles')
          .select('*')
          .eq('uuid', userId);
        
        setLoadingServer(false);
        
        if (fetchError) {
          error(`Profile fetch error:`, fetchError.message);
          return null;
        }
        
        const profile = data?.[0] || null;
        
        if (profile) {
          await saveUserData({ id: userId }, profile);
          setProfile(profile);
          log(`Profile fetched and saved:`, profile);
        }
        
        const end = performance.now();
        log(`fetchProfile completed in: ${end - start}ms`);
        return profile;
      } catch (err) {
        setLoadingServer(false);
        error(`Profile fetch error:`, err);
        return null;
      }
    } else {
      try {
        setLoadingServer(true);
        
        const { data, error: fetchError } = await supabase
          .from('profiles')
          .select('*')
          .eq('uuid', userId);
        
        setLoadingServer(false);
        
        if (fetchError) {
          error(`Profile fetch error:`, fetchError.message);
          return null;
        }
        
        const profile = data?.[0] || null;
        
        if (profile) {
          await saveUserData({ id: userId }, profile);
          setProfile(profile);
        }
        
        return profile;
      } catch (err) {
        setLoadingServer(false);
        error(`Profile fetch error:`, err);
        return null;
      }
    }
  };

  // применение накопленных обновлений баланса после приземления шара Plinko
  useEffect(() => {
    registerBalanceFlushHandler(async (profiles) => {
      const latest = profiles[profiles.length - 1];
      if (!latest) return;
      log('[Realtime] Applying held balance update');
      setProfile(latest);
      try {
        await saveUserData({ id: user?.id }, latest);
        log('[Realtime] Held profile saved to IndexedDB');
      } catch (err) {
        error('[Realtime] SaveUserData (held) error:', err);
      }
    });
  }, [user?.id]);

  // ставка в момент клика: оптимистично списываем деп с отображаемого баланса.
  // при приземлении flushBalance применяет настоящий профиль сервера (с выигрышем),
  // поэтому локальное списание лишь скрывает деп до конца анимации.
  const holdLocalBet = (amount) => {
    const dep = Number(amount);
    if (!dep || dep <= 0) return;
    setProfile(prev => {
      if (!prev) return prev;
      const balance = Number(prev.balance) - dep;
      log('[LocalBet] Optimistic deduct', dep, '->', balance);
      return { ...prev, balance };
    });
  };

  // откат оптимистичного списания: ставка не состоялась (ошибка ответа,
  // канвас не готов) — возвращаем деп на отображаемый баланс
  const restoreLocalBet = (amount) => {
    const dep = Number(amount);
    if (!dep || dep <= 0) return;
    setProfile(prev => {
      if (!prev) return prev;
      const balance = Number(prev.balance) + dep;
      log('[LocalBet] Optimistic restore', dep, '->', balance);
      return { ...prev, balance };
    });
  };

  useEffect(() => {
    if (!user?.id) {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
        log('Realtime channel unsubscribed (no user)');
      }
      return;
    }

    if (channelRef.current) {
      supabase.removeChannel(channelRef.current);
      log('Realtime channel unsubscribed (new user)');
    }

    channelRef.current = supabase
      .channel(`profile:${user.id}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'profiles',
          filter: `uuid=eq.${user.id}`
        },
        async (payload) => {
          log('[Realtime] Profile updated:', payload);
          
          if (payload.new) {
            const newProfile = payload.new;

            // шар Plinko в полёте — копить обновления, применить при приземлении
            if (isBalanceHeld()) {
              queueHeldProfile(newProfile);
              log('[Realtime] Balance update held (ball in flight)');
              return;
            }

            setProfile(newProfile);
            try {
              await saveUserData({ id: user.id }, newProfile);
              log('[Realtime] Profile saved to IndexedDB');
            } catch (err) {
              error('[Realtime] SaveUserData error:', err);
            }
          }
        }
      )
      .subscribe((status) => {
        log('[Realtime] Subscription status:', status);
      });

    log(`Realtime channel created for user: ${user.id}`);

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
        log('Realtime channel unsubscribed (cleanup)');
      }
    };
  }, [user?.id]);

  useEffect(() => {
    let isMounted = true;

    const init = async () => {
      log('AuthContext: init started');
      const { data: { session } } = await supabase.auth.getSession();
      
      if (!isMounted) return;
      
      const currentUser = session?.user ?? null;
      setUser(currentUser);
      log('AuthContext: session loaded', currentUser);
      
      if (currentUser) {
        log('AuthContext: loading cached data for user:', currentUser.id);
        const cached = await loadUserData(currentUser.id);
        
        if (cached.user) {
          setUser(cached.user);
          log('AuthContext: user cached loaded');
        }
        
        if (cached.profile) {
          setProfile(cached.profile);
          log('AuthContext: profile cached loaded');
        }
        
        setLoadingDB(false);
        setIsFullyLoaded(true);
        
        await fetchProfile(currentUser.id);
      } else {
        setLoadingDB(false);
        setIsFullyLoaded(true);
        log('AuthContext: no user, init complete');
      }
    };
    
    init();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!isMounted) return;
      
      log('AuthContext: auth state change', event);
      
      if (event === 'SIGNED_OUT') {
        setUser(null);
        setProfile(null);
        if (user?.id) {
          await removeUserData(user.id);
          log('AuthContext: user data removed');
        }
        
        if (channelRef.current) {
          supabase.removeChannel(channelRef.current);
          channelRef.current = null;
          log('AuthContext: realtime unsubscribed on sign out');
        }
        
        setLoadingDB(false);
        setIsFullyLoaded(true);
        return;
      }
      
      const currentUser = session?.user ?? null;
      setUser(currentUser);
      log('AuthContext: new user from auth change', currentUser);
      
      if (currentUser) {
        await saveUserData(currentUser, null);
        
        const cached = await loadUserData(currentUser.id);
        if (cached.profile) {
          setProfile(cached.profile);
          log('AuthContext: profile loaded from cache after auth change');
        }
        
        setLoadingDB(false);
        setIsFullyLoaded(true);
        
        await fetchProfile(currentUser.id);
      } else {
        setProfile(null);
        setLoadingDB(false);
        setIsFullyLoaded(true);
        log('AuthContext: user signed out via auth change');
      }
    });

    return () => {
      isMounted = false;
      subscription?.unsubscribe();
      log('AuthContext: cleanup completed');
    };
  }, [user?.id]);

  const signInWithGoogle = async () => {
    log('signInWithGoogle called');
    const flow = beginAuthFlow('google');
    log('signInWithGoogle returnTo:', flow.returnTo);

    // redirectTo ведёт обратно на страницу, с которой началась авторизация.
    // detectSessionInUrl: true в supabase.js автоматически обменяет ?code=
    // на сессию при возврате, поэтому целевой маршрут не имеет значения.
    const { error: oauthError } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: { 
        redirectTo: `${window.location.origin}${flow.returnTo}`,
        skipBrowserRedirect: false
      },
    });
    
    if (oauthError) {
      endAuthFlow();
      error('OAuth error:', oauthError);
    }
  };

  const signOut = async () => {
    log('signOut called');
    if (user?.id) {
      await removeUserData(user.id);
    }
    await supabase.auth.signOut();
    window.location.reload();
  };

  const updateUserProfile = async (newProfileData) => {
    log('updateUserProfile called with:', newProfileData);
    try {
      setProfile(prev => ({ ...prev, ...newProfileData }));
      log('Profile optimistically updated');
      
      const { data, error: updateError } = await supabase
        .from('profiles')
        .update(newProfileData)
        .eq('uuid', user.id)
        .select();
      
      if (updateError) {
        error('Update profile error:', updateError.message);
        return { error: updateError };
      }
      
      if (data?.[0]) {
        await saveUserData({ id: user.id }, data[0]);
        setProfile(data[0]);
        log('Profile successfully updated on server and saved to IndexedDB');
      }
      
      return { data: data?.[0] };
    } catch (err) {
      error('Update profile error:', err);
      return { error: err };
    }
  };

  const clearAllData = async () => {
    log('clearAllData called');
    await clearAll();
    setUser(null);
    setProfile(null);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      profile, 
      loadingDB,
      loadingServer,
      isFullyLoaded,
      signInWithGoogle, 
      signOut,
      updateUserProfile,
      clearAllData,
      fetchProfile,
      holdLocalBet,
      restoreLocalBet
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
};