import { useState, useEffect, useRef } from 'react'
import { supabase } from '../supabase'
import { getFromDB, saveToDB, STORES } from '../lib/indexedDB'
import { useAppState } from '../hooks/useState'

const activeChannels = new Set()

export const useTableData = (
  tableName, 
  filters, 
  { limit = null, orderByColumn = 'created_at', orderDirection = 'desc' } = {}
) => {
  const { state } = useAppState();
  
  const safeFilters = Array.isArray(filters) ? filters : [];
  const filtersKey = JSON.stringify(safeFilters);
  
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [serverLoading, setServerLoading] = useState(false);
  const [error, setError] = useState(null);

  const tableNameRef = useRef(tableName);
  const filtersRef = useRef(safeFilters);
  const limitRef = useRef(limit);
  const orderByColumnRef = useRef(orderByColumn);
  const orderDirectionRef = useRef(orderDirection);
  const channelRef = useRef(null);
  const isMountedRef = useRef(true);
  const channelNameRef = useRef(null);
  const requestIdRef = useRef(0);
  const prevParamsRef = useRef({ tableName, filtersKey });

  useEffect(() => {
    tableNameRef.current = tableName;
    filtersRef.current = safeFilters;
    limitRef.current = limit;
    orderByColumnRef.current = orderByColumn;
    orderDirectionRef.current = orderDirection;
  }, [tableName, filtersKey, limit, orderByColumn, orderDirection]);

  const log = (...args) => {
    if (state.dev?.view?.logsDataRT) {
      console.log(`[DataRT:${tableName}]`, ...args);
    }
  };

  const errorLogger = (...args) => {
    if (state.dev?.view?.logsDataRT) {
      console.error(`[DataRT:${tableName}]`, ...args);
    }
  };

  const buildCacheKey = (filterValues) => {
    const safeF = Array.isArray(filterValues) ? filterValues : [];
    const filterParts = safeF.map((f, i) => `${i}:${f.column}:${f.value}`).join('|');
    return `${filterParts}:${tableName}`;
  };

  const matchesFilters = (row) => {
    if (!row) return false;
    const safeF = Array.isArray(filtersRef.current) ? filtersRef.current : [];
    return safeF.every(f => {
      if (f.value === null || f.value === undefined) return true;
      const col = String(f.column);
      if (col.includes('->') || col.includes('.')) return true;
      if (f.operator === 'gte') return row[f.column] >= f.value;
      return row[f.column] === f.value;
    });
  };

  const fetchData = async (currentFilters) => {
    if (!tableName || typeof tableName !== 'string') {
      setLoading(false);
      return;
    }
    const requestId = requestIdRef.current;
    const isStale = () => requestId !== requestIdRef.current;

    const safeF = Array.isArray(currentFilters) ? currentFilters : [];
    log(`fetchData called for table: ${tableName}, filters:`, safeF);
    setServerLoading(true);
    setError(null);

    let query = supabase
      .from(tableName)
      .select('*');

    if (safeF.length > 0) {
      safeF.forEach(filter => {
        if (filter.value !== null && filter.value !== undefined) {
          if (filter.operator === 'gte') {
            query = query.gte(filter.column, filter.value);
          } else {
            query = query.eq(filter.column, filter.value);
          }
        }
      });
    }

    if (limit && orderByColumn) {
      query = query.order(orderByColumn, { ascending: orderDirection === 'asc' }).limit(limit);
    }

    const { data: serverData, error: fetchError } = await query;

    if (isStale()) {
      log(`Ignoring stale fetchData result (request ${requestId})`);
      return;
    }

    setServerLoading(false);

    if (fetchError) {
      errorLogger(`Error fetching ${tableName}:`, fetchError.message);
      setError(fetchError.message);
      return;
    }

    if (serverData && serverData.length > 0) {
      const result = serverData.length === 1 ? serverData[0] : serverData;
      
      const cacheKey = buildCacheKey(safeF);
      await saveToDB(STORES.STATE, { key: cacheKey, value: result });
      
      setData(result);
      log(`Data fetched:`, result);
    } else {
      setData([]);
      if (safeF.length > 0) {
        const cacheKey = buildCacheKey(safeF);
        await saveToDB(STORES.STATE, { key: cacheKey, value: [] });
      }
      log(`No data found for ${tableName}`);
    }
  };

  useEffect(() => {
    requestIdRef.current += 1;

    // Если сменились только limit/порядок сортировки (таблица и фильтры те
    // же) — НЕ сбрасываем данные и не показываем загрузку: список обновится
    // бесшовно. Иначе это смена запроса (таблица/фильтры) — чистим как раньше.
    const prev = prevParamsRef.current;
    const onlySortOrLimit =
      prev.tableName === tableName && prev.filtersKey === filtersKey;
    prevParamsRef.current = { tableName, filtersKey };
    if (!onlySortOrLimit) {
      setData(null);
      setLoading(true);
    }

    const init = async () => {
      const requestId = requestIdRef.current;
      const isStale = () => requestId !== requestIdRef.current;

      log('init started');
      
      if (safeFilters.length > 0) {
        const cacheKey = buildCacheKey(safeFilters);
        try {
          const cached = await getFromDB(STORES.STATE, cacheKey);
          if (isStale()) {
            log('Ignoring stale cache result');
            return;
          }
          if (cached) {
            const cachedValue = cached.value || cached;
            setData(cachedValue);
            log('Data loaded from cache');
          }
        } catch (err) {
          errorLogger('Cache load error:', err);
        }
      }

      if (isStale()) return;
      setLoading(false);
      await fetchData(safeFilters);
    };

    init();
  }, [filtersKey, tableName, limit, orderByColumn, orderDirection]);

  useEffect(() => {
    if (channelRef.current) {
      supabase.removeChannel(channelRef.current);
      channelRef.current = null;
      log('Realtime channel unsubscribed (new params)');
    }

    isMountedRef.current = true;
    const currentTableName = tableNameRef.current;
    
    if (!currentTableName || typeof currentTableName !== 'string') {
      log('Skipping realtime channel: invalid table name');
      return;
    }
    
    const currentFilters = filtersRef.current || [];
    const currentLimit = limitRef.current;
    const currentOrderBy = orderByColumnRef.current;
    const currentOrderDir = orderDirectionRef.current;

    const filterParts = currentFilters.map(f => `${f.column}=${f.value}`).join(',');
    const channelName = `rt:${currentTableName}:${filterParts || 'all'}`;
    if (activeChannels.has(channelName)) {
      log(`Channel ${channelName} already exists, skipping`);
      return;
    }
    activeChannels.add(channelName);
    channelNameRef.current = channelName;

    log(`Creating realtime channel: ${channelName}`);

    channelRef.current = supabase
      .channel(channelName)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: currentTableName,
          ...(currentFilters && currentFilters.length > 0 
            ? { 
                filter: currentFilters
                  .filter(f => 
                    f.value !== undefined && f.value !== null && 
                    !f.column.includes('->') &&
                    !f.column.includes('.')
                  )
                  .map(f => 
                    `${f.column}=${f.operator === 'gte' ? 'gte' : 'eq'}.${f.value}`
                  ).join(',')
              } 
            : {})
        },
        async (payload) => {
          if (!isMountedRef.current) return;

          if (!matchesFilters(payload.eventType === 'DELETE' ? payload.old : payload.new)) {
            log(`Realtime event skipped (row doesn't match filters) [${payload.eventType}]`);
            return;
          }

          log(`Realtime update [${payload.eventType}]:`, payload);

          const idCol = filtersRef.current[0]?.column || 'id';
          const limit = limitRef.current;
          const orderBy = orderByColumnRef.current;
          const orderDir = orderDirectionRef.current;

          if (payload.eventType === 'INSERT') {
            if (payload.new) {
              setData(prev => {
                if (!prev) return [payload.new];
                
                const newArr = Array.isArray(prev) ? [...prev, payload.new] : [prev, payload.new];
                
                if (orderBy) {
                  newArr.sort((a, b) => {
                    const aVal = a[orderBy];
                    const bVal = b[orderBy];
                    if (orderDir === 'desc') {
                      return bVal > aVal ? 1 : bVal < aVal ? -1 : 0;
                    }
                    return aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
                  });
                }
                if (limit && newArr.length > limit) {
                  return newArr.slice(0, limit);
                }
                
                return newArr;
              });
              
              if (currentFilters && currentFilters.length > 0) {
                setData(currentData => {
                  const cacheKey = buildCacheKey(currentFilters);
                  saveToDB(STORES.STATE, { key: cacheKey, value: currentData })
                    .catch(err => errorLogger('Cache save error on INSERT:', err));
                  return currentData;
                });
              }
              
              log('Data updated after INSERT');
            }
          } 
          else if (payload.eventType === 'UPDATE') {
            if (payload.new) {
              setData(prev => {
                if (Array.isArray(prev)) {
                  const exists = prev.find(item => item[idCol] === payload.new[idCol]);
                  if (exists) {
                    return prev.map(item => 
                      item[idCol] === payload.new[idCol] ? payload.new : item
                    );
                  }
                  return [...prev, payload.new];
                }
                return payload.new;
              });

              if (currentFilters && currentFilters.length > 0) {
                const cacheKey = buildCacheKey(currentFilters);
                try {
                  await saveToDB(STORES.STATE, { key: cacheKey, value: payload.new });
                  log('Data saved to cache after UPDATE');
                } catch (err) {
                  errorLogger('Cache save error on UPDATE:', err);
                }
              }
            }
          } 
          else if (payload.eventType === 'DELETE') {
            if (payload.old) {
              setData(prev => {
                if (!prev) return null;
                if (Array.isArray(prev)) {
                  return prev.filter(item => item[idCol] !== payload.old[idCol]);
                }
                if (prev[idCol] === payload.old[idCol]) {
                  return null;
                }
                return prev;
              });
              log('Data updated after DELETE');
            }
          }
        }
      )
      .subscribe((status) => {
        log(`Subscription status: ${status}`);
      });

    log(`Realtime channel created for table: ${currentTableName}`);

    return () => {
      isMountedRef.current = false;
      if (channelRef.current) {
        activeChannels.delete(channelNameRef.current);
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
        log('Realtime channel unsubscribed (cleanup)');
      }
    };
  }, [tableName, filtersKey, limit, orderByColumn, orderDirection]);

  return { data, loading, serverLoading, error };
};