import React, { useRef, useEffect, useState } from 'react'
import '../css/Footer.css'

import DRESHKA from '../img/DRESH.png'
import RESHKA from '../img/RESH.png'
import OREL from '../img/OREL.png'

const multipliers = [
  '1.94', '3.88', '7.76', '15.52', '31.04',
  '62.08', '124.16', '248.32', '496.64', '993.28',
  '1.98k', '3.97k', '7.94k', '15.89k', '31.78k',
  '63.56k', '127.13k', '254.27k', '508.55k', '1017.11k',
]

const ITEM_WIDTH = 73
const ITEMS_TO_LEAVE = 8

export default function CNT_Footer({ cls, mode, profile }) {
  const sliderRef = useRef(null)
  const prevBtnRef = useRef(null)
  const nextBtnRef = useRef(null)
  const smoothScrollRef = useRef(null)
  const prevAnimationRef = useRef(null)

  smoothScrollRef.current = (targetPosition, duration = 200) => {
    const sliderWrapper = sliderRef.current
    if (!sliderWrapper) return

    if (prevAnimationRef.current) {
      cancelAnimationFrame(prevAnimationRef.current)
    }

    const startPosition = sliderWrapper.scrollLeft
    let distance = targetPosition - startPosition
    if (Math.abs(distance) < 1) return

    let startTime = null

    const animate = (currentTime) => {
      if (startTime === null) startTime = currentTime
      const timeElapsed = currentTime - startTime
      const progress = Math.min(timeElapsed / duration, 1)
      const ease = progress < 0.5
        ? 4 * progress * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 3) / 2

      sliderWrapper.scrollLeft = startPosition + distance * ease

      if (timeElapsed < duration) {
        prevAnimationRef.current = requestAnimationFrame(animate)
      } else {
        sliderWrapper.scrollLeft = targetPosition
        prevAnimationRef.current = null
      }
    }

    prevAnimationRef.current = requestAnimationFrame(animate)
  }

  useEffect(() => {
    const sliderWrapper = sliderRef.current
    const prevBtn = prevBtnRef.current
    const nextBtn = nextBtnRef.current

    const updateButtons = () => {
      if (!sliderWrapper) return

      const scrollLeft = sliderWrapper.scrollLeft
      const maxScroll = sliderWrapper.scrollWidth - sliderWrapper.clientWidth

      if (prevBtn) prevBtn.disabled = scrollLeft <= 1
      if (nextBtn) nextBtn.disabled = scrollLeft >= maxScroll - (ITEMS_TO_LEAVE * ITEM_WIDTH)
    }

    if (sliderWrapper) {
      sliderWrapper.addEventListener('scroll', updateButtons)
      window.addEventListener('resize', updateButtons)
    }

    setTimeout(updateButtons, 0)

    return () => {
      if (sliderWrapper) {
        sliderWrapper.removeEventListener('scroll', updateButtons)
        window.removeEventListener('resize', updateButtons)
      }
    }
  }, [])

  const handleScroll = (direction) => {
    const sliderWrapper = sliderRef.current
    if (!sliderWrapper) return

    const scrollAmount = ITEM_WIDTH
    const currentScroll = Math.round(sliderWrapper.scrollLeft / scrollAmount) * scrollAmount
    const targetPosition = direction === 'next'
      ? currentScroll + scrollAmount
      : currentScroll - scrollAmount

    smoothScrollRef.current(targetPosition, 300)
  }

  return (
    <div className="coinflip-game-field-footer">
        <div className={`coinflip-game-multipliers-wrapper ${mode ? 'coinflip-game-multipliers-wrapper_visible' : ''}`}>
          <div className="coinflip-game-multipliers">
            <button
              aria-label="Previous"
              className="coinflip-game-multipliers__button coinflip-game-multipliers__button_prev"
              ref={prevBtnRef}
              onClick={() => handleScroll('prev')}
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="512" height="512"
                fill="currentColor"
                viewBox="0 0 512 512"
              >
                <g>
                  <path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path>
                </g>
              </svg>
            </button>
            <div className="coinflip-game-multipliers-slider">
              <div className="slider-wrapper slider-wrapperr" id="sliderWrapper" ref={sliderRef}>
                {multipliers.map((mult, index) => {
                  const arrLen = profile?.CoinFlip?.arrCoin?.length || 0;
                  const isNext = index === arrLen;
                  const stateCoin = (profile?.CoinFlip?.arrCoin?.[index]?.[1] === 'P' ? 'P' : 
                    profile?.CoinFlip?.arrCoin?.[index]?.[1] === 'O' ? 'O' : false );
                  const coinImg = stateCoin === 'P' ? RESHKA : stateCoin === 'O' ? OREL : DRESHKA;
                  const coinState = stateCoin ? stateCoin : '-empty';
                  return(
                  <div
                    key={index}
                    className={`swiper-slide ${isNext ? 'coinflip-game-multipliers__item_next' : ''}`}
                    ref={null}
                  
                  >
                    <div className="swiper-content">
                      <div className={`coinflip-game-multipliers__item ${isNext || coinState==='O' || coinState==='P' ? 'coinflip-game-multipliers__item_active' : ''}`}>
                        <div className="coinflip-game-multipliers__coin">
                          <div className="coinflip-game-multipliers__coin-body" key={`${index}${coinState}`}>
                            <div className="coinflip-game-multipliers__coin__front">
                              <img src={coinImg} alt={stateCoin === 'P' ? 'Решка' : stateCoin === 'O' ? 'Орел' : 'Empty'} />
                            </div>
                            <div className="coinflip-game-multipliers__coin__back" />
                          </div>
                        </div>
                        <strong>x{mult}</strong>
                      </div>
                    </div>
                  </div>
                )})}
              </div>
            </div>
            <button
              aria-label="Next"
              className="coinflip-game-multipliers__button coinflip-game-multipliers__button_next"
              ref={nextBtnRef}
              onClick={() => handleScroll('next')}
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="512" height="512"
                fill="currentColor"
                viewBox="0 0 512 512"
              >
                <g>
                  <path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path>
                </g>
              </svg>
            </button>
          </div>
        </div>
        <div className={`coinflip-game-history-wrapper ${mode ? 'coinflip-game-history-wrapper_visible' : ''}`}>
          <div className="coinflip-game-history" />
        </div>
    </div>
  )
}