import React, { useState } from 'react'
import { SWI, VPI, ZOI, WLT, RUB, ROI, PLI, MII, COI, NUI, KEI, CFI, BOI, AFI, HEI, HPI, VOI } from '../../img/ICOdiv/ROCICO'

export default function IcoTestPage() {
  const [o, seto] = useState('50')

  return (
    <>
      <input
        type="number"
        value={o}
        onChange={(e) => seto(e.target.value)}
      />
      <span>SWI <SWI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>VPI <VPI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>ZOI <ZOI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>WLT <WLT width={Number(o)} height={Number(o)} cn='' /></span>
      <span>RUB <RUB width={Number(o)} height={Number(o)} cn='' /></span>
      <span>ROI <ROI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>PLI <PLI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>MII <MII width={Number(o)} height={Number(o)} cn='' /></span>
      <span>COI <COI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>NUI <NUI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>KEI <KEI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>CFI <CFI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>BOI <BOI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>AFI <AFI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>HEI <HEI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>HPI <HPI width={Number(o)} height={Number(o)} cn='' /></span>
      <span>VOI <VOI width={Number(o)} height={Number(o)} cn='' /></span>
    </>
  )
}