import './css/page.css'
import { useState, useEffect } from 'react'
import { useAuth } from '../../../../context/AuthContext'
import { useAuthModal } from '../../../../context/AuthModalContext'
import { useSearch } from '../../../../context/SearchContext'
import { useGameLikes } from '../../../../context/LikesContext'

export default function DownGame({ game, lastDep, setLD, betsAlwaysActive = false }) {
  const { profile, user,  } = useAuth()
  const { openSearch } = useSearch()
  const { openAuth } = useAuthModal()
  const { count, isLiked, pending, bump, toggle } = useGameLikes(game)
  const [animClass, setAnimClass] = useState('')

  useEffect(() => {
    if (!animClass) return
    const timer = setTimeout(() => setAnimClass(''), 420)
    return () => clearTimeout(timer)
  }, [animClass])

  const handleLike = () => {
    if (!user) {
      openAuth()
      return
    }
    if (!game || typeof game !== 'string' || pending) return

    setAnimClass(isLiked ? 'likes-badge_unliking' : 'likes-badge_liking')
    toggle()
  }

  return (
    <>
    <div class={`${game==="Plinko" && 'game-toolbar-plinko'} game-toolbar game-toolbar_dark`}>
      <div class="game-toolbar__group">
        <button
          type="button"
          class={`likes-badge likes-badge_default likes-badge_md ${isLiked ? 'likes-badge_active' : ''} ${animClass} ${bump ? 'likes-badge_bump' : ''}`}
          onClick={handleLike}
          disabled={pending}
          aria-pressed={isLiked}
        >
          <span class="likes-badge__heart">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="512"
              height="512"
              fill="currentColor"
              viewBox="0 0 512 512"
              class=""
            >
              <path d="M376 30c-27.783 0-53.255 8.804-75.707 26.168-21.525 16.647-35.856 37.85-44.293 53.268-8.437-15.419-22.768-36.621-44.293-53.268C189.255 38.804 163.783 30 136 30 58.468 30 0 93.417 0 177.514c0 90.854 72.943 153.015 183.369 247.118 18.752 15.981 40.007 34.095 62.099 53.414A15.978 15.978 0 00256 482c3.88 0 7.62-1.404 10.532-3.953 22.094-19.322 43.348-37.435 62.111-53.425C439.057 330.529 512 268.368 512 177.514 512 93.417 453.532 30 376 30z" />
            </svg>
          </span>
          <span class="likes-badge__count">{count}</span>
        </button>

        <button
          type="button"
          aria-label="Сообщить о проблеме"
          class="game-toolbar__btn v-popper--has-tooltip"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="512"
            height="512"
            fill="currentColor"
            viewBox="0 0 512 512"
            class=""
          >
            <path
              fill-rule="evenodd"
              d="M210.5 54.192c20.222-34.923 70.778-34.923 91 0l203.383 351.232c20.222 34.923-5.056 78.576-45.5 78.576H52.617c-40.444 0-65.722-43.653-45.5-78.576L210.5 54.192ZM286 389.5c0 16.569-13.431 30-30 30-16.569 0-30-13.431-30-30 0-16.569 13.431-30 30-30 16.569 0 30 13.431 30 30Zm0-230.5c0-16.569-13.431-30-30-30-16.569 0-30 13.431-30 30v138c0 16.569 13.431 30 30 30 16.569 0 30-13.431 30-30V159Z"
            />
          </svg>
        </button>
      </div>

      <div class="game-toolbar__divider game-toolbar__divider_search"></div>

      <button type="button" class="search-trigger game-toolbar__search search-trigger_dark" onClick={openSearch}>
        <span class="search-trigger__icon">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="512"
            height="512"
            fill="currentColor"
            viewBox="0 0 512 512"
            class=""
          >
            <path d="M224.044 1c123.184 0 223.044 99.895 223.044 223.124 0 50.072-16.489 96.29-44.329 133.521l98.815 98.851.185.185c12.392 12.499 12.31 32.681-.185 45.078a31.87 31.87 0 0 1-10.389 6.878 31.866 31.866 0 0 1-12.233 2.366 31.866 31.866 0 0 1-12.233 2.366 31.866 31.866 0 0 1-22.623-9.244l-99.576-98.287c-37.085 27.506-82.997 43.777-132.709 43.777C100.861 447.249 1 347.354 1 224.125S100.86 1 224.044 1Zm0 63.75c-87.988 0-159.317 71.354-159.317 159.375S136.055 383.5 224.044 383.5c42.505 0 81.121-16.653 109.687-43.791a32.891 32.891 0 0 1 5.207-5.181c27.51-28.642 44.422-67.546 44.422-110.403 0-88.021-71.327-159.375-159.316-159.375Z" />
          </svg>
        </span>
        <span class="search-trigger__label">Найти игру, провайдера или категорию</span>
      </button>

      <div class="game-toolbar__break"></div>
      <div class="game-toolbar__divider"></div>

      <div class="game-toolbar__group">
        <button
          type="button"
          aria-label="История ставок"
          class={`${(lastDep || betsAlwaysActive) ? 'game-toolbar__btn_active' : ''} game-toolbar__btn v-popper--has-tooltip`}
          onClick={betsAlwaysActive ? undefined : () => setLD(lastDep ? false : true)}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="512"
            height="512"
            fill="currentColor"
            viewBox="0 0 512 512"
            class=""
          >
            <g>
              <path d="M445.573 273.686c36.628 0 66.427-29.8 66.427-66.428v-25.65c0-8.294-6.724-15.018-15.017-15.018-27.429-.019-47.588-2.574-69.558 16.643l-5.302-25.705 10.903-2.721c35.539-8.869 57.235-44.997 48.367-80.536l-6.211-24.886c-2.009-8.047-10.16-12.938-18.207-10.934l-24.886 6.211c-34.822 7.93-57.728 46.071-48.366 80.535l6.135 24.583c10.188 53.419 27.742 96.301-.66 148.562-14.274 26.469-37.436 47.387-65.219 58.9l-40.972 16.974c-5.68 2.362-10.149 8.703-9.148 15.782 3.568 28.584 3.789 50.034 28.527 69.56a66.05 66.05 0 0049.062 13.329l25.443-3.26c7.713-.988 13.305-7.662 13.105-15.271a15.055 15.055 0 00-.118-1.532c-3.569-28.584-3.79-50.034-28.528-69.559a67.092 67.092 0 00-9.532-6.163 161.463 161.463 0 0019.787-12.966l17.643 10.877c15.129 9.348 33.074 12.168 50.194 8.089 30.572-7.569 39.666-27.081 54.672-51.606 2.722-4.412 2.884-9.681.9-14.075a14.954 14.954 0 00-5.801-6.59c-21.299-12.998-36.567-25.63-62.805-23.032a161.752 161.752 0 004.07-14.114h15.095v.001zM238.233 387.344c-.236-5.089-3.438-10.805-9.239-13.128l-40.972-16.974c-27.784-11.513-50.945-32.431-65.219-58.9-28.416-52.287-10.829-95.203-.659-148.562 7.065-27.829 14.508-47.795-1.369-74.868-9.136-15.21-23.647-25.954-40.862-30.25L55.026 38.45a14.958 14.958 0 00-7.384.026c-5.158 1.334-9.442 5.376-10.823 10.907L30.61 74.27c-8.87 35.538 12.827 71.667 48.365 80.536l10.904 2.721-5.303 25.706c-11.716-10.344-27.086-16.642-43.908-16.642h-25.65C6.724 166.591 0 173.315 0 181.609v25.65c0 36.628 29.8 66.427 66.427 66.427h15.094a161.515 161.515 0 004.398 15.07c-25.98-2.376-41.183 10.25-62.244 23.079-6.93 4.213-9.318 13.559-4.902 20.664 0 .002.003.004.005.007 15.035 24.567 24.082 44.012 54.669 51.6 17.118 4.081 35.065 1.257 50.193-8.089l17.884-11.025a161.388 161.388 0 0018.658 12.111 67.148 67.148 0 00-9.532 6.163c-24.73 19.503-24.969 41.028-28.527 69.559a15.055 15.055 0 00-.118 1.532c-.199 7.609 5.394 14.283 13.105 15.271 6.533.696 27.839 4.003 34.02 3.809 14.611 0 28.735-4.796 40.485-13.878 24.735-19.515 24.966-41.006 28.527-69.56.03-.671.157-1.026.091-2.655z" />
              <path d="M313.436 307.058a13.331 13.331 0 0013.083-15.876l-10.163-52.161a8.67 8.67 0 012.601-8.005l38.882-36.224a13.327 13.327 0 00-7.467-22.98l-52.749-6.453a8.673 8.673 0 01-6.808-4.947l-22.303-47.886c-4.731-10.486-19.48-10.609-24.296-.287l-22.437 48.173a8.673 8.673 0 01-6.809 4.947l-52.748 6.453c-11.271 1.354-15.755 15.492-7.236 23.195l38.651 36.009a8.676 8.676 0 012.601 8.005l-10.163 52.161a13.33 13.33 0 0019.548 14.202l46.467-25.785a8.676 8.676 0 018.417 0l46.467 25.785a13.291 13.291 0 006.462 1.674z" />
            </g>
          </svg>
        </button>

        <button
          type="button"
          aria-label="Театральный режим"
          class="game-toolbar__btn v-popper--has-tooltip"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="512"
            height="512"
            fill="currentColor"
            viewBox="0 0 512 512"
            class=""
          >
            <path
              fill-rule="evenodd"
              d="M100.609 84C45.597 84 1 128.564 1 183.537v144.926C1 383.436 45.597 428 100.609 428h310.782C466.403 428 511 383.436 511 328.463V183.537C511 128.564 466.403 84 411.391 84H100.609Zm26.696 76.444c-27.507 0-49.805 22.283-49.805 49.769v91.574c0 27.486 22.298 49.769 49.805 49.769h257.39c27.507 0 49.805-22.283 49.805-49.769v-91.574c0-27.486-22.298-49.769-49.805-49.769h-257.39Z"
            />
          </svg>
        </button>
      </div>
    </div>
    </>
  )
}