import { useEffect, useState } from 'react'
import mess from '../../../../lib/message.jsx'
import { supabase } from '../../../../supabase.js'
import { markSupabaseCall } from '../../../../lib/DEF_DATA.js'

async function cookies_run(setTR, setPROC, profile, bet, openAuth, setResult, mode ) {
  if(profile === null) {
    openAuth()
  }else {
    setPROC(true)
    if (!(profile?.balance >= bet)) {
      mess(400, 'Недостаточно средств')
    } else if(mode>=0 && mode<3) {
      try {
        markSupabaseCall('Cookies', 'pending')
        const { data, error } = await supabase.functions.invoke('Cookies', {
          body: { bet: bet, mode: mode }
        })
        if (error) {
          console.error('Error start Cookies game:', error)
          markSupabaseCall('Cookies', 'error', error?.message || String(error))
          mess(500, error || 'Ошибка создания игры')
        } else if(data?.error) {
          markSupabaseCall('Cookies', 'error', data.error)
          mess(400, data.error)
        } else if (data) {
          const countK = data.count_k || [0, 0]
          let trValue = 6
          switch (countK[0]) {
            case 0:
              trValue = 6
              break
            case 2:
              trValue = countK[1] === 0 ? 5 : 4
              break
            case 3:
              trValue = countK[1] === 0 ? 3 : 2
              break
            case 4:
              trValue = 1
              break
            case 5:
              trValue = 0
              break
            default:
              trValue = 6
          }
          setTR(trValue)
          setResult(data.TRUE_ZONE)
          markSupabaseCall('Cookies', 'ok')
          mess(200, data)
          setPROC(false)
        } else if (data?.success) {
          mess(200, data)
        } else {
          mess(500, 'Неизвестный ответ от сервера')
        }
      } catch (err) {
        console.error('Network error run Cookies game:', err)
        markSupabaseCall('Cookies', 'error', err?.message || String(err))
        mess(500, 'Ошибка подключения к серверу')
      }
    }else {
      mess(400, "Неверные параметры")
    }
  }
}

