async function KenoRun( profile, chossen, mode, dep, openAuth, setResult, setK ) {
  //console.log(`mode: ${mode}\ndep: ${dep}\nchossen: ${chossen}`)
  if(profile === null){
    openAuth()
  } else if(chossen.length<1 || chossen.length>40) {
    mess(400, 'Ошибка клеток поля')
  } else if(profile?.balance-dep<0){
    mess(400, 'недостаточно средств')
  }
  else {
    if (mode>=0 || mode<=2) {
      try {
        markSupabaseCall('KenoRun', 'pending')
        const { data, error } = await supabase.functions.invoke('Keno', {
          body: { dep:dep, chossen:chossen, mode:mode }
        })
        if (error) {
          console.error('Error run Keno game:', error)
          markSupabaseCall('KenoRun', 'error', error?.message || String(error))
          mess(500, error || 'Ошибка запуска игры')
        } else if(data?.error) {
          markSupabaseCall('KenoRun', 'error', data.error)
          mess(400, data.error)
        } else if (data) {
          markSupabaseCall('KenoRun', 'ok')
          if (data.TRUE_ZONE || data.chossen) {
            let resultZone = data.TRUE_ZONE
            for(let i=0; i<resultZone.length; i++){
              switch(resultZone[i]){
                case false: 
                  if(data.chossen.includes(i + 1)){
                    resultZone[i] = 'lose'
                  } else {
                    resultZone[i] = 'empty'
                  }
                  break;
                case true:
                  if(data.chossen.includes(i + 1)){
                    resultZone[i] = 'win'
                  } else {
                    resultZone[i] = 'empty current'
                  }
                  break;
              }
              setK(resultZone.filter(x => x === 'win').length+1)
            }
            setResult(resultZone)
          }
          mess(200, data)
        } else if (data?.success) {
          mess(200, data)
        } else {
          mess(500, 'Неизвестный ответ от сервера')
        }
      } catch (err) {
        console.error('Network error run Keno game:', err)
        markSupabaseCall('KenoRun', 'error', err?.message || String(err))
        mess(500, 'Ошибка подключения к серверу')
      }
    } else {
      mess(400, "Неверный режим")
    }
  }
}

const random = {
  // random.int(0, 100) рандомное число от 0 до 100 с одинаковым шансом
  int: (min, max) => Math.floor(Math.random() * (max - min + 1)) + min,
  // random.choice(["W", "eeee", 0, 5, abc]) рандомное значение из массива с одинаковым шансом
  choice: (array) => array[Math.floor(Math.random() * array.length)],
  // a = [[1.5, 60], ["hello world", 40]] 1.5 и "hello world" - значения, 60% и 40% шансы выпадения значений
  // random.procent(a) выдает рандомное значение с заранее заданными шансами
  procent: (array) => {
    const totalChance = array.reduce((sum, item) => sum + item[1], 0);
    const rand = Math.random() * totalChance;
    let currentSum = 0;
    for (const item of array) {
      currentSum += item[1];
      if (rand <= currentSum) {
        return item[0];
      }
    }
    return array[array.length - 1][0];
  },
  // random.draw(10, 40) — 10 случайных уникальных чисел от 1 до 40
  draw: (count, max) => {
    const nums = Array.from({ length: max }, (_, i) => i + 1);
    for (let i = nums.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
    return nums.slice(0, count);
  },
  // Установить count случайных элементов в value внутри arr
  array: Object.assign(
    (arr, count, value) => {
      const result = [...arr];
      const indices = result.map((_, i) => i);
      for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
      }
      for (let i = 0; i < count && i < indices.length; i++) {
        result[indices[i]] = value;
      }
      return result;
    },
    {
      limit: (arr, count, value, limit = arr.length) => {
        const result = [...arr];
        const indices = Array.from({ length: limit }, (_, i) => i);
        for (let i = indices.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [indices[i], indices[j]] = [indices[j], indices[i]];
        }
        for (let i = 0; i < count && i < indices.length; i++) {
          result[indices[i]] = value;
        }
        return result;
      }
    }
  )
};

