function KenoSlider({ mode, chosen, k }) {
  const sliderRef = useRef(null);
  const trackRef = useRef(null);
  const prevBtnRef = useRef(null);
  const nextBtnRef = useRef(null);
  const slideWidthRef = useRef(65);
  const prevAnimationRef = useRef(null);
  const translateXRef = useRef(0);

  const multipliersData = useMemo(() => {
    const chosenCount = chosen.length;
    if (chosenCount === 0) return [];

    const modeIndex = Math.min(mode, MULTIPLIERS.length - 1);
    const modeData = MULTIPLIERS[modeIndex] || MULTIPLIERS[0];
    const row = modeData[chosenCount - 1] || [];

    const items = [];

    for (let i = 0; i < row.length; i++) {
      const value = row[i];
      const count = i;
      const label = count === 0
        ? '0 чисел'
        : count === 1
          ? '1 число'
          : count <= 4
            ? `${count} числа`
            : `${count} чисел`;

      items.push({ label, value: `x${value}` });
    }

    return items;
  }, [chosen, mode]);

  const maxTranslateRef = () => {
    const track = trackRef.current;
    const wrapper = sliderRef.current;
    if (!track || !wrapper) return 0;
    return Math.max(0, track.scrollWidth - wrapper.clientWidth);
  };

  const smoothScrollRef = useRef(null);
  smoothScrollRef.current = (targetPosition, duration = 300) => {
    const track = trackRef.current;
    if (!track) return;

    if (prevAnimationRef.current) {
      cancelAnimationFrame(prevAnimationRef.current);
    }

    const startPosition = translateXRef.current;
    let distance = targetPosition - startPosition;
    if (Math.abs(distance) < 1) return;

    let startTime = null;

    const animate = (currentTime) => {
      if (startTime === null) startTime = currentTime;
      const timeElapsed = currentTime - startTime;
      const progress = Math.min(timeElapsed / duration, 1);
      const ease = progress < 0.5
        ? 4 * progress * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 3) / 2;

      const currentX = startPosition + distance * ease;
      track.style.transform = `translateX(${-currentX}px)`;
      translateXRef.current = currentX;
      updateButtons();

      if (timeElapsed < duration) {
        prevAnimationRef.current = requestAnimationFrame(animate);
      } else {
        track.style.transform = `translateX(${-targetPosition}px)`;
        translateXRef.current = targetPosition;
        prevAnimationRef.current = null;
        updateButtons();
      }
    };

    prevAnimationRef.current = requestAnimationFrame(animate);
  };

  const updateButtons = () => {
    const wrapper = sliderRef.current;
    const track = trackRef.current;
    if (!wrapper || !track) return;

    const currentX = Math.round(translateXRef.current);
    const maxScroll = Math.round(maxTranslateRef());
    const slideWidth = slideWidthRef.current;

    const canGoPrev = currentX > 0;
    const canGoNext = currentX + slideWidth <= maxScroll + 0.5;

    if (prevBtnRef.current) prevBtnRef.current.disabled = !canGoPrev;
    if (nextBtnRef.current) nextBtnRef.current.disabled = !canGoNext;
  };

  useEffect(() => {
    window.addEventListener('resize', updateButtons);
    updateButtons();

    return () => {
      window.removeEventListener('resize', updateButtons);
    };
  }, [multipliersData.length]);

  const handleScroll = (direction) => {
    const wrapper = sliderRef.current;
    if (!wrapper) return;

    const slideWidth = slideWidthRef.current;
    const currentX = translateXRef.current;
    const maxScroll = maxTranslateRef();

    const targetPosition = direction === 'next'
      ? Math.min(currentX + slideWidth, maxScroll)
      : Math.max(currentX - slideWidth, 0);

    smoothScrollRef.current(targetPosition, 300);
  };

  const scrollToIndex = (index, offset = 0) => {
    const wrapper = sliderRef.current;
    if (!wrapper) return;

    const slideWidth = slideWidthRef.current;
    const maxScroll = maxTranslateRef();
    const targetPosition = Math.max(0, Math.min((index - offset) * slideWidth, maxScroll));

    smoothScrollRef.current(targetPosition, 500);
  };

  useEffect(() => {
    if (k === false || k === null || k === undefined) return;

    scrollToIndex(k - 1, 2);
  }, [k]);
  return (
    <div className="game-multipliers">
      <button
        aria-label="Previous"
        className="game-multipliers__button game-multipliers__button_prev"
        ref={prevBtnRef}
        onClick={() => handleScroll('prev')}
        disabled={chosen.length === 0}
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className="">
          <g>
            <path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path>
          </g>
        </svg>
      </button>

      {chosen.length === 0 ? (
        <div className="game-multipliers-slider">
          <div className="swiper swiper-container-initialized swiper-container-horizontal swiper-container-pointer-events" id="swiper_keno_multipliers">
            <div className="swiper-wrapper">
              <div className="swiper-slide-active" style={{ width: '100%'}}>
                <div className="swiper-content">
                  <div className="game-multipliers__empty">
                    <div className="game-multipliers__empty-text">
                      <span>Выберите <strong>от 1 до 10 чисел</strong> чтобы увидеть шансы</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="game-multipliers-slider">
          <div className={`slider-wrapper${multipliersData.length >= 8 ? ' slider-wrapper_scroll' : ' slider-wrapper_no-scroll'}`} ref={sliderRef}>
            <div className="slider-track" ref={trackRef}>
              {multipliersData.map((item, index) => {
                const isScroll = multipliersData.length >= 8;
                const basis = isScroll
                  ? undefined
                  : `calc((100% - 6px * ${multipliersData.length - 1}) / ${multipliersData.length})`;
                return (
                  <div key={index} className="swiper-content"
                    style={{ flex: isScroll ? undefined : `0 0 ${basis}` }}>
                    <div className={`game-multipliers__item
                      ${isScroll ? ' game-multipliers__item-scroll' : ''}
                      ${(k-1)===index ? ' game-multipliers__item_win' : ''}`}>
                      <small>{item.label}</small>
                      <strong>{item.value}</strong>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      <button
        aria-label="Next"
        className="game-multipliers__button game-multipliers__button_next"
        ref={nextBtnRef}
        onClick={() => handleScroll('next')}
        disabled={chosen.length === 0}
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className="">
          <g>
            <path d="M20.387 225.704L232.22 361.053a44.16 44.16 0 0047.553 0l211.835-135.349c20.55-13.13 26.573-40.439 13.437-60.989-13.136-20.555-40.434-26.566-60.989-13.436L255.998 271.436 67.944 151.279c-7.366-4.705-15.597-6.955-23.734-6.955-14.568 0-28.828 7.201-37.254 20.39-13.136 20.557-7.119 47.86 13.43 60.99z"></path>
          </g>
        </svg>
      </button>
    </div>
  );
}

