/* ── чтение профиля по UUID ── */
function useProfileByUuid(uuid) {
  const [profile, setProfile] = useState(null)
  const [loading, setLoading] = useState(true)
  const [notFound, setNotFound] = useState(false)

  useEffect(() => {
    let cancelled = false

    const fetch = async () => {
      if (!uuid) {
        setLoading(false)
        return
      }
      setLoading(true)
      setNotFound(false)

      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('uuid', uuid)
        .single()

      if (cancelled) return

      if (error || !data) {
        setNotFound(true)
        setLoading(false)
        return
      }

      setProfile(data)
      setLoading(false)
    }

    fetch()
    return () => { cancelled = true }
  }, [uuid])

  return { profile, loading, notFound }
}

