import '../css/Body.css'

import RESHKA from '../img/RESH.png'
import OREL from '../img/OREL.png'

import { useAuthModal } from '../../../../context/AuthModalContext.jsx'
import { useState, useEffect, useRef } from 'react'
import { supabase } from '../../../../supabase.js'
import { markSupabaseCall } from '../../../../lib/DEF_DATA.js'
import mess from '../../../../lib/message.jsx'

let K = { up: false, down: false }
let trueCoinValue = 'O'
let trueCoinListeners = []
let flipTriggerListeners = []

export const notifyFlipTrigger = () => {
  flipTriggerListeners.forEach(cb => cb())
}

export const setTrueCoin = (val) => {
  trueCoinValue = val
  trueCoinListeners.forEach(cb => cb())
  notifyFlipTrigger()
}
const subscribeTrueCoin = (cb) => {
  trueCoinListeners.push(cb)
  return () => { trueCoinListeners = trueCoinListeners.filter(c => c !== cb) }
}
const subscribeFlipTrigger = (cb) => {
  flipTriggerListeners.push(cb)
  return () => { flipTriggerListeners = flipTriggerListeners.filter(c => c !== cb) }
}

async function cf_fast( setCoin, profile, bet, coin, onResult ) {
  if ((profile?.balance >= bet) && (coin==='P' || coin==='O')) {
    try {
      markSupabaseCall('CFFast', 'pending')
      const { data, error } = await supabase.functions.invoke('CFFast', {
        body: { dep: bet, coin: coin }
      })
      if (error) {
        console.error('Error fast CF game:', error)
        markSupabaseCall('CFFast', 'error', error?.message || String(error))
        mess(500, error || 'Ошибка создания игры')
        if (onResult) onResult(false)
      } else if(data?.error) {
        markSupabaseCall('CFFast', 'error', data.error)
        mess(400, data.error)
        if (onResult) onResult(false)
      } else if (data) {
        markSupabaseCall('CFFast', 'ok')
        mess(200, data)
        if (onResult) setTimeout(() => onResult(data.win), 850)
        setCoin(data.TRUE_COIN==='O' ? true : false)
        notifyFlipTrigger()
      } else if (data?.success) {
        mess(200, data)
        if (onResult) onResult(true)
      } else {
        mess(500, 'Неизвестный ответ от сервера')
        if (onResult) onResult(false)
      }
    } catch (err) {
      console.error('Network fast CF game:', err)
      markSupabaseCall('CFFast', 'error', err?.message || String(err))
      mess(500, 'Ошибка подключения к серверу')
      if (onResult) onResult(false)
    }
  } else {
    mess(400, "Неверные параметры")
    if (onResult) onResult(false)
  }
}

async function cf_norm_run( setCoin, profile, choice, openAuth ) {
  if(profile === null){
    openAuth()
  }else {
    if (choice==='P' || choice==='O') {
      try {
        markSupabaseCall('CFNormRun', 'pending')
        const { data, error } = await supabase.functions.invoke('CFNormRun', {
          body: { coin: choice }
        })
        if (error) {
          console.error('Error run CF game:', error)
          markSupabaseCall('CFNormRun', 'error', error?.message || String(error))
          mess(500, error || 'Ошибка создания игры')
        } else if(data?.error) {
          markSupabaseCall('CFNormRun', 'error', data.error)
          mess(400, data.error)
        } else if (data) {
          markSupabaseCall('CFNormRun', 'ok')
          if (data.win) {
            K.up = true
          } else {
            K.down = true
          }
          setCoin(data.TRUE_COIN==='O' ? true : false)
          notifyFlipTrigger()
        } else if (data?.success) {
        } else {
          mess(500, 'Неизвестный ответ от сервера')
        }
      } catch (err) {
        console.error('Network error run CF game:', err)
        markSupabaseCall('CFNormRun', 'error', err?.message || String(err))
        mess(500, 'Ошибка подключения к серверу')
      }
    } else if(!profile.CoinFlip.play){
      mess(400, "Игра неактивна")
    }else {
      mess(400, "Неверные параметры")
    }
  }
}

export default function CNT_Body({cls, profile, bet, mode}) {
  const kList = [  1.94, 3.88, 7.76, 15.52, 31.04,
  62.08, 124.16, 248.32, 496.64, 993.28,
  (1.98 * 1000), (3.97 * 1000), (7.94 * 1000), (15.89 * 1000), (31.78 * 1000),
  (63.56 * 1000), (127.13 * 1000), (254.27 * 1000), (508.55 * 1000), (1017.11 * 1000)]
  const round = mode ? (profile?.CoinFlip?.arrCoin?.length-1 || 0) : 0
  const [ coin, setCoin ] = useState(true)
  const { openAuth, openReg } = useAuthModal()
  const [ displayAmount, setDisplayAmount ] = useState('0.00 ₽')
  const [ showAmount, setShowAmount ] = useState(false)
  const [ multiplier, setMultiplier ] = useState('0')
  const [ multiplierAnim, setMultiplierAnim ] = useState({ show: false, newValue: '' })
  const [ loseAnim, setLoseAnim ] = useState(false)
  const [ fastResult, setFastResult ] = useState(null)
  const [ flipping, setFlipping ] = useState(false)
  const flipTimeoutRef = useRef(null)
  const prevMultiplierRef = useRef('0')
  const animatingRef = useRef(false)
  const animRef = useRef(null)
  const frameRef = useRef(0)
  const startRef = useRef(0)
  const fromRef = useRef(0)
  const betValue = parseFloat(bet) || 10

  useEffect(() => {
    const trigger = () => {
      setFlipping(true)
      if (flipTimeoutRef.current) clearTimeout(flipTimeoutRef.current)
      flipTimeoutRef.current = setTimeout(() => {
        setFlipping(false)
        flipTimeoutRef.current = null
      }, 850)
    }
    return subscribeFlipTrigger(trigger)
  }, [])

  useEffect(() => {
    if (fastResult !== null) {
      animatingRef.current = true
      if (fastResult === false) {
        setMultiplierAnim({ show: false, newValue: '' })
        setLoseAnim(true)
        
        const timer = setTimeout(() => {
          setLoseAnim(false)
          setFastResult(null)
          animatingRef.current = false
        }, 600)
      } else {
        setMultiplier('1.94')
        setMultiplierAnim({ show: true, newValue: '1.94' })
        
        const timer = setTimeout(() => {
          setMultiplierAnim({ show: false, newValue: '' })
          setFastResult(null)
          animatingRef.current = false
        }, 600)
      }
    }
  }, [fastResult])
  useEffect(() => {
    if (animatingRef.current) return
    if (flipping) return
    
    if (!mode) {
      setMultiplier('1.94')
      return
    }
    
    if (!profile?.CoinFlip?.play || round === 0) {
      setMultiplier('0')
      prevMultiplierRef.current = '0'
      return
    }
    
    const k = profile?.CoinFlip?.k
    if (k != false) {
      setMultiplier(String(k))
      prevMultiplierRef.current = String(k)
    }
  }, [mode, profile?.CoinFlip?.play, profile?.CoinFlip?.k, round, flipping])

  useEffect(() => {
    setCoin(trueCoinValue === 'O')
    return subscribeTrueCoin(() => {
      setCoin(trueCoinValue === 'O')
    })
  }, [])

  useEffect(() => {
    if (animRef.current) cancelAnimationFrame(animRef.current)

    const isFast = !mode
    const isMultiply = mode && profile?.CoinFlip?.play
    const shouldShow = isFast || isMultiply

    setShowAmount(shouldShow)

    if (!shouldShow) {
      setDisplayAmount(`${profile?.CoinFlip?.dep*kList[profile?.CoinFlip?.arrCoin?.length]} ₽`)
      fromRef.current = 0
      return
    }

    let targetAmount
    if (isFast) {
      targetAmount = betValue * 1.94
    } else {
      targetAmount = profile?.CoinFlip?.dep*kList[profile?.CoinFlip?.arrCoin?.length]
    }

    fromRef.current = frameRef.current
    startRef.current = performance.now()
    frameRef.current = targetAmount

    const animate = (now) => {
      const elapsed = now - startRef.current
      const progress = Math.min(elapsed / 500, 1)
      const eased = 1 - Math.pow(1 - progress, 3)

      const current = fromRef.current + (targetAmount - fromRef.current) * eased
      setDisplayAmount(`${current.toFixed(2)} ₽`)

      if (progress < 1) {
        animRef.current = requestAnimationFrame(animate)
      }
    }

    animRef.current = requestAnimationFrame(animate)
    return () => cancelAnimationFrame(animRef.current)
  }, [mode, betValue, profile?.CoinFlip?.play, profile?.CoinFlip?.dep, round])

  return(
    <div class="coinflip-game-field-body">
      <div class="coinflip-game-result">
        <div class={`coinflip-game-result__coin ${flipping ? (coin ? 'coinflip-game-result__coin_flip_front' : 'coinflip-game-result__coin_flip_back') : (coin ? 'coinflip-game-result__coin_animation-front' : 'coinflip-game-result__coin_animation-back')}`}>
          <div class="coinflip-game-result__coin__front">
            <img src={OREL} alt="Орел" />
          </div>
          <div class="coinflip-game-result__coin__back">
            <img src={RESHKA} alt="Решка" />
          </div>
        </div>
      </div> 
      <div class="coinflip-game-round">
        <div class="coinflip-game-round__item">
          <div class={`coinflip-game-round__item-value coinflip-game-round__item-value_muted 
            ${profile?.CoinFlip?.play && 'coinflip-game-round__item-value__play'}`}>
            <span>
              {mode ? `${round ? round+1 : '0'} из 20` : '—'}
            </span>
          </div> 
          <div class="coinflip-game-round__item-title">Раунд</div>
        </div> 
        <div class="coinflip-game-round__item"></div> 
        <div class="coinflip-game-round__item">
          <div class={`coinflip-game-round__item-value coinflip-game-round__item-value_muted 
            ${(profile?.CoinFlip?.play || !mode) && 'coinflip-game-round__item-value__play'}`}>
            <div class="multiplier-wrapper">
              <span class="multiplier-value">x{multiplier}</span>
              {multiplierAnim.show && (
                <span class="multiplier-float" key={multiplierAnim.newValue}>
                  x{multiplierAnim.newValue}
                </span>
              )}
              {loseAnim && (
                <span class="multiplier-float multiplier-float-lose">
                  x0
                </span>
              )}
            </div>
          </div> 
          <div class="coinflip-game-round__item-title">Множитель</div>
        </div>
      </div> 
      <div class="coinflip-game-buttons">
        <button onClick={()=>{mode ? cf_norm_run( setCoin, profile, 'O', openAuth ) : cf_fast( setCoin, profile, bet, 'O', setFastResult )}} aria-label="Heads" class={`coinflip-game-button ${mode ? 'coinflip-game-button_mode' : ''}`}>
          <span class="coinflip-game-button-icon">
            <img src={OREL} alt="Орел" />
          </span> 
          <span class={`coinflip-game-button-content`}>
            <span class={`coinflip-game-button__text ${(!mode || profile?.CoinFlip?.play) ? 'shifted-up' : ''}`}>Орел</span> 
            <span class={`coinflip-game-button__help ${(profile?.CoinFlip?.play || !mode) ? 'playing-cfgb_help' : ''} ${showAmount ? 'amount-visible' : ''}`}>
              <span class={`amount ${showAmount ? 'amount-visible' : ''}`}>
                <span>
                  {showAmount ? displayAmount : ''}
                </span> 
              </span>
            </span>
          </span>
        </button> 
        <button onClick={()=>{mode ? cf_norm_run( setCoin, profile, 'P', openAuth ) : cf_fast( setCoin, profile, bet, 'P', setFastResult )}} aria-label="Tails" class={`coinflip-game-button coinflip-game-button_invert ${mode ? 'coinflip-game-button_mode' : ''}`}>
          <span class="coinflip-game-button-icon">
            <img src={RESHKA} alt="Решка" />
          </span> 
          <span class={`coinflip-game-button-content`}>
            <span class={`coinflip-game-button__text ${(!mode || profile?.CoinFlip?.play) ? 'shifted-up' : ''}`}>Решка</span> 
            <span class={`coinflip-game-button__help ${(profile?.CoinFlip?.play || !mode) ? 'playing-cfgb_help' : ''} ${showAmount ? 'amount-visible' : ''}`}>
              <span class={`amount ${showAmount ? 'amount-visible' : ''}`}>
                <span>
                  {showAmount ? displayAmount : ''}
                </span> 
              </span>
            </span>
          </span>
        </button>
      </div>
    </div>  
  )
}