import React, { useEffect, useRef, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { Routes, Route, useSearchParams, useLocation } from 'react-router-dom';
//hooks
  import { useDataUpdate } from './hooks/UpdateDataPerSecond';
//components
  import BetMenu from './Pages/Games/components/BetMenu'; 
  import Sidebarnav from './components/menu/sidebar';
  import { NavMenu } from './components/menu/upper';
  import { Auth, Reg } from './components/menu/upper';
  import HowToPlay from './Pages/Games/components/HTP';
  import Footer from './components/Footer/page';
//Pages
  //games
    import CrashGamesPage from './Pages/Games/Crash/Page';
    import MinerGamesPage from './Pages/Games/Miner/Page';
    import PlinkoGamesPage from './Pages/Games/Plinko/Page';
    import CookiesGamesPage from './Pages/Games/Cookies/Page';
    import NutsGamesPage from './Pages/Games/Nuts/Page';
    import KenoGamesPage from './Pages/Games/Keno/Page';
    import CoinFlipGamesPage from './Pages/Games/CoinFlip/Page';
  //gaameee
    import HomePage from './Pages/Support/Home/page'
  //support
    import AccountPage from './Pages/Support/Account/Page';
    import BonusPage from './Pages/Support/Bonus/Page';
    import AffilPage from './Pages/Support/Affil/Page';
    import HelpPage from './Pages/Support/Help/Page';
  //Dev
    import UndefinedPage from './Pages/dev/UndefinedPage';
    import DevGetProfPage from './Pages/dev/testedPage'
    import IcoTestPage from './Pages/dev/IcoTestPage'
  import AboutPage from './Pages/about/AboutPage';
  import AuthCallback from './Pages/AuthCallback';
import IntercomButton from './components/IntercomButton/page';
import { AuthModalProvider, useAuthModal } from './context/AuthModalContext';
import { HTPProvider, useHTP } from './context/HTPContext';
import { BetMenuProvider, useBetMenu } from './context/BetMenuContext';
import { ShareModalProvider, useShareModal } from './context/ShareModalContext';
import { SearchProvider, useSearch } from './context/SearchContext';
import { SidebarProvider } from './context/SidebarContext';
import ShareModal from './Pages/Games/components/ShareModal/page';
import SearchPage from './components/Search/page';
import { AnimatePresence } from 'framer-motion'
import "./app.css"
import Mtabbar from './components/tabBar/page';

const AUTH_CALLBACK_PARAMS = ['code', 'error', 'error_description'];

function AuthModals() {
  const { authModal } = useAuthModal();
  if (!authModal.open) return null;
  return (
    <>
      <div className='blur'></div>
      <div className='modal modal-auth'>
        {authModal.type === 'auth' && <Auth key="auth" />}
        {authModal.type === 'reg' && <Reg key="reg" />}
      </div>
    </>
  );
}

function HTPModal() {
  const { isHTPOpen, closeHTP } = useHTP();
  if (!isHTPOpen) return null;
  return (
    <HowToPlay isOpen={isHTPOpen} onClose={closeHTP} />
  );
}

function BetMenuWrapper() {
  const { isOpen, closeBetMenu, openBetMenu } = useBetMenu();
  const [searchParams] = useSearchParams();
  const betFromUrl = searchParams.get('bet');
  const prevBetRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      prevBetRef.current = null;
    }
  }, [isOpen]);

  useEffect(() => {
    if (betFromUrl && betFromUrl !== prevBetRef.current) {
      openBetMenu(betFromUrl);
      prevBetRef.current = betFromUrl;
    }
  }, [betFromUrl, openBetMenu]);

  return (
    <>
      {isOpen && createPortal(
        <BetMenu key="betMenu" isOpen={isOpen} onClose={closeBetMenu} />,
        document.body
      )}
    </>
  );
}

function ShareModalWrapper() {
  const { isOpen, closeShareModal } = useShareModal();
  if (!isOpen) return null;
  return <ShareModal />;
}

function SearchWrapper() {
  const { isSearchOpen, closeSearch } = useSearch();
  if (!isSearchOpen) return null;
  return <SearchPage onClose={closeSearch} />;
}

function App() {
  useDataUpdate((data) => {
    if (data.settings.devMode && data.settings.devSet?.dps?.view) {
      console.log('Данные обновлены:', data);
    }
  });
  
  const location = useLocation();
  const searchParams = useMemo(() => new URLSearchParams(location.search), [location.search]);
  const isAuthCallbackView = AUTH_CALLBACK_PARAMS.some(p => searchParams.has(p))
    || (location.pathname === '/auth' || location.pathname === '/auth/callback');
  
  return (
    <>
      <SidebarProvider>
      <ShareModalProvider>
      <BetMenuProvider>
      <HTPProvider>
      <AuthModalProvider>
      <SearchProvider>
        <div id="disabledAuth"></div>
        <div id="disabledReg"></div>
        <Sidebarnav />
        <Mtabbar />
        <div id='BOD'>
          <NavMenu />
        </div>
        <div className="content">
          <div className='content-wrapper absol'>
            <BetMenuWrapper />
          </div>
          {/* Тут Search */}
          <AnimatePresence>
            <AuthModals />
          </AnimatePresence>
          <AnimatePresence>
            <ShareModalWrapper />
          </AnimatePresence>
          <AnimatePresence>
            <SearchWrapper />
          </AnimatePresence>
            {isAuthCallbackView ? <AuthCallback /> : (
            <Routes>
              {/* games pages */}
                {/* <Route path="/games/crash" element={<CrashGamesPage />} /> */}
                <Route path="/games/plinko" element={<PlinkoGamesPage />} />
                <Route path="/games/miner" element={<MinerGamesPage />} />
                <Route path="/games/cookies" element={<CookiesGamesPage />} />
                <Route path="/games/nuts" element={<NutsGamesPage />} />
                <Route path="/games/keno" element={<KenoGamesPage />} />
                <Route path="/games/coinflip" element={<CoinFlipGamesPage />} />
              {/* Sup pages */}
                <Route path="/" element={<HomePage />} />
                <Route path="/bonuses" element={<BonusPage />} />
                <Route path="/affiliate" element={<AffilPage />} />
                <Route path="/help/*" element={<HelpPage />} />
                <Route path="/help" element={<HelpPage />} />
                <Route path="/about" element={<AboutPage />} />
                <Route path="/account/*" element={<AccountPage />} />
              {/* system-dev pages */}
                <Route path="/dev/icon-test" element={<IcoTestPage />} />
                <Route path="/dev/tested-polygons" element={<DevGetProfPage />} />
                <Route path="/undefined" element={<UndefinedPage />} />
                <Route path="*" element={<UndefinedPage />} />
            </Routes>
            )}
        </div>
        <Footer />
        <IntercomButton />
        <AnimatePresence>
          <HTPModal />
        </AnimatePresence>
      </SearchProvider>
      </AuthModalProvider>
      </HTPProvider>
      </BetMenuProvider>
      </ShareModalProvider>
      </SidebarProvider>
    </>
  );
}

export default App;