import { useEffect, useRef } from 'react'
import { useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext'
import { useSettings } from './useSettings' 
import { useAppState } from './useState'
import { useInterval, useIntervalAdvanced } from './useInterval'
import { useSyncedState } from './useSyncedState'
import { useTableData } from '../context/DataRT'
import { supabase } from '../supabase'
import { K_WAM } from '../Pages/Games/Miner/components/DepAndMines'
import { INIT_DATA } from '../lib/DEF_DATA'

export function useDataUpdate(callback) {
  const { settings } = useSettings();
  const { loadingDB, loadingServer, user, profile } = useAuth();
  const { state, updateState, updateStateWithoutDB } = useAppState()
  const isInitialized = useRef(false);
  const previousProfileRef = useRef(profile);
  const location = useLocation()
  const currentPath = location.pathname

  useEffect(() => {
    if(state?.dev?.view?.K_WAM_LOGS){console.log(`K_WAM : ${K_WAM}`)}
  }, [K_WAM])

  useEffect(() => {
    if(INIT_DATA?.path !== currentPath){INIT_DATA.path = currentPath}
    if(state?.dev?.view?.PATH__LOGS){console.log(`PATH: ${INIT_DATA.path}`)}
  }, [INIT_DATA?.path, currentPath])

  useEffect(() => {
    if(state?.dev?.view?.INIT_DATA__LOGS){console.log(`INIT_DATA: ${JSON.stringify(INIT_DATA)}`)}
  }, [INIT_DATA])

  useEffect(() => {
    if (!profile) return;
    if (previousProfileRef.current === profile) return;
    previousProfileRef.current = profile;
  }, [profile, updateStateWithoutDB])

  useEffect(() => {
    const dps = settings.dps || 140;
    if (state.dev?.view?.clrLog) {
      console.clear();
    }
    if (settings.devMode) {
      if (state.dev?.view?.updMiner) {
        console.log(`state miner :\n
          ${(state.miner).slice(0, 5)}\n${(state.miner).slice(5, 10)}\n${(state.miner).slice(10, 15)}\n${(state.miner).slice(15, 20)}\n${(state.miner).slice(20, 25)}
          \nstate miner opened :\n
          ${(state.minerOpened)?.slice(0, 5)}\n${(state.minerOpened)?.slice(5, 10)}\n${(state.minerOpened)?.slice(10, 15)}\n${(state.minerOpened)?.slice(15, 20)}\n${(state.minerOpened)?.slice(20, 25)}`
        );
      }
    }
  }, [state, settings])

  useEffect(() => {
    const dps = settings.dps || 140;
    const interval = setInterval(() => {
      callback?.({ dps, settings, loadingDB, loadingServer, user, profile });
    }, 1000 / dps);

    return () => clearInterval(interval);
  }, [settings.dps, callback, settings, loadingDB, loadingServer, user, profile]);

  const { data } = useTableData(
    INIT_DATA.path === '/games/miner' ? 'miner_view' : undefined,
    INIT_DATA.path === '/games/miner' ? [{ column: 'uuid', value: profile?.uuid }] : undefined,
    INIT_DATA.path === '/games/miner' ? { limit: 1 } : undefined
  );

  const firstDPS = (typeof state.FIRST_DPS === 'number' && state.FIRST_DPS > 0 && isFinite(state.FIRST_DPS)) 
    ? state.FIRST_DPS 
    : 60; 

  const { start: start1, reset: reset1 } = useIntervalAdvanced(() => {
    if (!data) return;
    if (!profile) return;

    if (profile.Miner.play && INIT_DATA.path === '/games/miner') {
      if(!(K_WAM[2])){K_WAM[2] = true}
      if(profile?.Miner?.round){
        INIT_DATA.round = profile?.Miner?.round
      }
      reset1();
    } else {
      if(INIT_DATA?.round){
        INIT_DATA.round = 0
      }
      if(K_WAM[2]){
        K_WAM[2] = false
      }
      (async () => {
        try {
          const { data: updateData, error } = await supabase
            .from('miner_view')
            .update({ minerview: Array(25).fill(false) })
            .eq('uuid', user.id)
            .select();
          
          if (error) {
            console.error("Error updating miner_view:", error);
            return;
          }
          
          reset1();
        } catch (err) {
          console.error("Network error:", err);
        }
      })();
    }
  }, 1000 / firstDPS, { immediate: true, pauseOnHidden: false });

  const { start: start2, reset: reset2 } = useIntervalAdvanced(() => {
    if (profile?.Miner?.zone) {
      const PRF_ZONE = profile.Miner.zone.map((item) => item === "X" ? true : false);
      updateState('miner', profile.Miner?.play ? profile.Miner.zone : Array(25).fill(false));
      updateState('minerOpened', profile.Miner?.play ? PRF_ZONE : Array(25).fill(false));
      updateState('miner_view', data?.miner_view);
      reset2();
    }
  }, 1000 / firstDPS, { immediate: true, pauseOnHidden: false });

  useEffect(() => {
    start1();
    start2();
  }, [])
}