import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    // Автодетект включён: supabase-js автоматически обменивает ?code= на сессию
    // на любой странице (включая root). Это позволяет AuthCallback работать
    // без manual code exchange — он просто проверяет наличие готовой сессии.
    detectSessionInUrl: true,
    storage: window.localStorage,
    flowType: 'pkce' 
  },
  global: {
    headers: {
      'apikey': supabaseAnonKey,
      'X-Client-Info': 'my-app'
    }
  }
})