const TABS = [
  { to: '/account',              label: 'Аккаунт',   Icon: AccountIcon },
  { to: '/account/transactions', label: 'История',   Icon: TransactionsIcon },
  { to: '/account/settings',     label: 'Настройки', Icon: SettingsIcon },
]

const isActive = (tab, pathname) =>
  tab.to === '/account' ? pathname === '/account' : pathname.startsWith(tab.to)

function AccountInner() {
  const location = useLocation()
  const navigate = useNavigate()
  const { profile, user, signOut, isFullyLoaded } = useAuth()
  const { openAuth } = useAuthModal()
  const menuRef = useRef(null)
  const [tabStyle, setTabStyle] = useState({ '--width': '0px', '--x': '0px' })

  const activeIndex = TABS.findIndex((tab) => isActive(tab, location.pathname))

  useEffect(() => {
    if (!isFullyLoaded) return
    if (!user) {
      navigate('/', { replace: true })
      openAuth()
    }
  }, [isFullyLoaded, user, navigate, openAuth])

  useEffect(() => {
    const menu = menuRef.current
    if (!menu) return

    const update = () => {
      const item = menu.querySelectorAll('.tab-menu__item')[activeIndex]
      if (!item) return
      setTabStyle({ '--width': `${item.offsetWidth}px`, '--x': `${item.offsetLeft}px` })
    }

    update()
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [activeIndex, location])

  if (!user || !profile) return null

  return (
    <div className="container">
      <div className="account-menu-wrapper">
        <div
          ref={menuRef}
          className="tab-menu tab-menu_active"
          id="tab-menu_95782"
          style={{ '--width': tabStyle['--width'], '--x': tabStyle['--x'] }}
        >
          {TABS.map((tab, index) => {
            const { to, label, Icon } = tab
            const active = index === activeIndex
            return (
              <Link
                key={to}
                to={to}
                className={`tab-menu__item${active ? ' tab-menu__item_active' : ''}`}
                aria-current={active ? 'page' : undefined}
              >
                <Icon />
                <span>{label}</span>
              </Link>
            )
          })}
        </div>
        <div className="account-menu__logout">
          <div className="account-menu__logout-content" onClick={signOut}>
            <span>Выйти</span>
            <LogoutIcon />
          </div>
        </div>
      </div>
      <div className="account-content">
        <Routes>
          <Route
            index
            element={
              <div className="account-info">
                <UserData profile={profile} />
              </div>
            }
          />
          <Route
            path="transactions/*"
            element={
              <div className="account-transactions">
                <HistoryBets profile={profile} />
              </div>
            }
          />
          <Route
            path="settings"
            element={
              <SettingsPage profile={profile}/>
            }
          />
        </Routes>
      </div>
    </div>
  )
}

function AccountPage() {
  const location = useLocation()
  const uuidParam = new URLSearchParams(location.search).get('uuid')

  if (uuidParam) return <PublicProfilePage />

  return <AccountInner />
}

export default AccountPage