import { useDevice } from "../menu/device-page"
import { useAuthModal } from "../../context/AuthModalContext"
import { useSearch } from "../../context/SearchContext"
import { useSidebar } from "../../context/SidebarContext"
import { useLocation } from "react-router-dom"

import './css/TB.css'
import { useAuth } from "../../context/AuthContext"

export default function Mtabbar({}) {
  const device = useDevice()
  const { openAuth } = useAuthModal()
  const { openSearch } = useSearch()
  const { pathname } = useLocation()
  const { profile } = useAuth()
  const { opened, toggleSidebar } = useSidebar()

  if(device!='m'){return(<></>)}
  return(
    <nav class="tab-bar-v2">
      <ul class="tab-bar-v2__list">
        <li class="tab-bar-v2__item">
          <a href="/" aria-current="page" class={`tab-bar-v2__button 
            ${pathname==='/' && 'tab-bar-v2__button_active'}`}>
            <span class="tab-bar-v2__icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path fill-rule="evenodd" d="M256 1a88.829 88.829 0 0 0-50.388 15.69L39.862 130.884a89.653 89.653 0 0 0-28.546 32.23A90.341 90.341 0 0 0 1 205.028v216.116c0 23.831 9.403 46.687 26.14 63.538C43.879 501.533 66.58 511 90.25 511h331.5c23.671 0 46.372-9.467 63.109-26.318C501.597 467.831 511 444.975 511 421.144V205.028a90.33 90.33 0 0 0-10.316-41.914 89.656 89.656 0 0 0-28.546-32.23L306.388 16.69A88.829 88.829 0 0 0 256 1Zm-95.625 382.5c-17.604 0-31.875 14.271-31.875 31.875s14.271 31.875 31.875 31.875h191.25c17.604 0 31.875-14.271 31.875-31.875S369.229 383.5 351.625 383.5h-191.25Z"></path></svg>
            </span> 
            <span class="tab-bar-v2__label">Главная</span>
          </a>
        </li>
        <li class="tab-bar-v2__item">
          {profile ? 
            <a href="/account" aria-current="page" class={`tab-bar-v2__button 
              ${pathname==='/account' && 'tab-bar-v2__button_active'}`}>
              <span class="tab-bar-v2__icon">
                <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><g><path d="M256 256.66c-134.927 0-244.701 109.775-244.701 244.7 0 5.873 4.767 10.64 10.64 10.64h468.123c5.873 0 10.639-4.767 10.639-10.64 0-134.926-109.775-244.7-244.701-244.7zM256 234.061c64.634 0 117.03-52.396 117.03-117.03C373.03 52.396 320.634 0 256 0c-64.635 0-117.031 52.396-117.031 117.031 0 64.634 52.396 117.03 117.031 117.03z"></path></g></svg>
              </span> 
              <span class="tab-bar-v2__label">Аккаунт</span>
            </a>
          : <button onClick={() => openAuth()} type="button" class="tab-bar-v2__button">
            <span class="tab-bar-v2__icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><g><path d="M256 256.66c-134.927 0-244.701 109.775-244.701 244.7 0 5.873 4.767 10.64 10.64 10.64h468.123c5.873 0 10.639-4.767 10.639-10.64 0-134.926-109.775-244.7-244.701-244.7zM256 234.061c64.634 0 117.03-52.396 117.03-117.03C373.03 52.396 320.634 0 256 0c-64.635 0-117.031 52.396-117.031 117.031 0 64.634 52.396 117.03 117.031 117.03z"></path></g></svg>
            </span> 
            <span class="tab-bar-v2__label">Войти</span>
          </button>}
        </li>
        <li class="tab-bar-v2__item">
          <a href="/bonuses" class={`tab-bar-v2__button 
            ${pathname==='/bonuses' && 'tab-bar-v2__button_active'}`}>
            <span class="tab-bar-v2__icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path d="M406.854 256c0-83.182-67.673-150.854-150.854-150.854-199.853 7.583-199.799 294.154.002 301.708 83.179 0 150.852-67.673 150.852-150.854zm-135.768 75.427h-60.342v-30.171h60.342c19.99-.76 19.975-29.417 0-30.171h-60.342v-90.512h90.512v30.171h-60.341v30.171h30.171c59.971 2.282 59.925 88.251 0 90.512z"></path><path d="M240.915 75.609V0C183.092 3.33 128.891 25.783 85.647 64.313l53.527 53.527c27.949-23.671 63.143-39.032 101.741-42.231zM75.609 271.085H0c3.33 57.824 25.783 112.024 64.313 155.267l53.527-53.526c-23.671-27.95-39.032-63.143-42.231-101.741zM117.84 139.174L64.313 85.647C25.783 128.89 3.332 183.09 0 240.915h75.609c3.2-38.598 18.56-73.792 42.231-101.741zM426.352 64.313C383.109 25.783 328.909 3.332 271.085 0v75.609c38.598 3.2 73.791 18.56 101.741 42.23l53.526-53.526zM436.391 240.915H512c-3.333-57.824-25.783-112.025-64.313-155.268l-53.527 53.526c23.671 27.95 39.031 63.144 42.231 101.742zM271.085 436.391V512c57.823-3.333 112.025-25.783 155.267-64.314l-53.526-53.526c-27.95 23.671-63.143 39.031-101.741 42.231zM85.647 447.685c43.244 38.532 97.445 60.982 155.268 64.314V436.39c-38.598-3.2-73.792-18.56-101.741-42.231l-53.527 53.526zM394.16 372.826l53.526 53.526c38.532-43.243 60.982-97.443 64.314-155.267h-75.609c-3.2 38.598-18.56 73.791-42.231 101.741z"></path></svg>
            </span> 
            <span class="tab-bar-v2__label">Бонусы</span>
          </a>
        </li>
        <li class="tab-bar-v2__item">
          <button onClick={() => openSearch()} type="button" class="tab-bar-v2__button">
            <span class="tab-bar-v2__icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><path d="M224.044 1c123.184 0 223.044 99.895 223.044 223.124 0 50.072-16.489 96.29-44.329 133.521l98.815 98.851.185.185c12.392 12.499 12.31 32.681-.185 45.078a31.87 31.87 0 0 1-10.389 6.878 31.866 31.866 0 0 1-12.233 2.366 31.866 31.866 0 0 1-22.623-9.244l-99.576-98.287c-37.085 27.506-82.997 43.777-132.709 43.777C100.861 447.249 1 347.354 1 224.125S100.86 1 224.044 1Zm0 63.75c-87.988 0-159.317 71.354-159.317 159.375S136.055 383.5 224.044 383.5c42.505 0 81.121-16.653 109.687-43.791a32.891 32.891 0 0 1 5.207-5.181c27.51-28.642 44.422-67.546 44.422-110.403 0-88.021-71.327-159.375-159.316-159.375Z"></path></svg>
            </span> 
            <span class="tab-bar-v2__label">Поиск</span>
          </button>
        </li>
        <li class="tab-bar-v2__item">
          <button onClick={() => toggleSidebar()} type="button" class={`tab-bar-v2__button
            ${opened && 'tab-bar-v2__button_active'}`}>
            <span class="tab-bar-v2__icon">
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" class=""><g><path d="M31.125 126.493h449.757c17.162 0 31.118-13.956 31.118-31.118S498.044 64.25 480.882 64.25H31.125C13.963 64.25 0 78.213 0 95.375s13.963 31.118 31.125 31.118zM480.882 224.875H31.125C13.963 224.875 0 238.838 0 256s13.963 31.118 31.125 31.118h449.757C498.044 287.118 512 273.162 512 256s-13.956-31.125-31.118-31.125zM480.882 385.5H31.125C13.963 385.5 0 399.471 0 416.632c0 17.162 13.963 31.118 31.125 31.118h449.757c17.162 0 31.118-13.956 31.118-31.118 0-17.161-13.956-31.132-31.118-31.132z"></path></g></svg>
            </span> 
            <span class="tab-bar-v2__label">Меню</span>
          </button>
        </li>
      </ul>
    </nav>
  )
}