function animateScroll(el, to) {
  const from = el.scrollLeft;
  const max = el.scrollWidth - el.clientWidth;
  const target = Math.max(0, Math.min(max, to));
  const dist = target - from;
  if (dist === 0) return;
  if (el._scrollAnim) cancelAnimationFrame(el._scrollAnim);

  const duration = 250;
  const easeInOut = (t) => t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
  const start = performance.now();

  const tick = (now) => {
    const t = Math.min(1, (now - start) / duration);
    el.scrollLeft = from + dist * easeInOut(t);
    if (t < 1) el._scrollAnim = requestAnimationFrame(tick);
  };
  el._scrollAnim = requestAnimationFrame(tick);
}

export function CardSlider({ title, to, Icon, items }) {
  const trackRef = useRef(null);
  const [canLeft, setCanLeft] = useState(false);
  const [canRight, setCanRight] = useState(false);
  const [fades, setFades] = useState({ left: 1, right: 1 });
  const [clipMap, setClipMap] = useState({});

  const update = () => {
    const track = trackRef.current;
    if (!track) return;
    const { scrollLeft, scrollWidth, clientWidth } = track;
    const left = scrollLeft > 1;
    const right = scrollLeft < scrollWidth - clientWidth - 1;
    setCanLeft(left);
    setCanRight(right);
    setFades({ left: left ? 0 : 1, right: right ? 0 : 1 });

    if (!left || !right) {
      setClipMap({});
      return;
    }

    const MIN_OPACITY = 0.2;
    const FADE_ZONE = 60;
    const nextClip = {};
    Array.from(track.children).forEach((child, i) => {
      const cardLeft = child.offsetLeft;
      const cardRight = cardLeft + child.offsetWidth;
      const visStart = scrollLeft - FADE_ZONE;
      const visEnd = scrollLeft + clientWidth + FADE_ZONE;
      const visible = Math.min(cardRight, visEnd) - Math.max(cardLeft, visStart);
      const fraction = Math.max(0, Math.min(1, visible / child.offsetWidth));
      nextClip[i] = MIN_OPACITY + (1 - MIN_OPACITY) * fraction;
    });
    setClipMap(nextClip);
  };

  const scroll = (direction) => {
    const track = trackRef.current;
    if (!track) return;
    const item = track.children[0];
    if (!item) return;
    const step = item.offsetWidth + 25;
    const max = track.scrollWidth - track.clientWidth;
    const currentIndex = Math.round(track.scrollLeft / step);
    const targetIndex = Math.max(0, currentIndex + (direction === 'left' ? -1 : 1));
    animateScroll(track, Math.min(targetIndex * step, max));
  };

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    update();
    const cancel = () => { if (track._scrollAnim) cancelAnimationFrame(track._scrollAnim); };
    track.addEventListener('scroll', update, { passive: true });
    track.addEventListener('wheel', cancel, { passive: true });
    track.addEventListener('touchstart', cancel, { passive: true });
    window.addEventListener('resize', update);
    return () => {
      cancel();
      track.removeEventListener('scroll', update);
      track.removeEventListener('wheel', cancel);
      track.removeEventListener('touchstart', cancel);
      window.removeEventListener('resize', update);
    };
  }, []);

  return (
    <section className="card-slider card-slider_full-bleed">
      <div className="card-slider__head">
        <div className="section-heading">
          <Link to={to} className="section-heading__link">
            {Icon && <Icon cn="section-heading__icon" />}
            <h3 className="section-heading__title">{title}</h3>
          </Link>
          <span className="section-heading__count">{items.length}</span>
        </div>
        <div className="card-slider__actions">
          <Link to={to} className="card-slider__see-all">
            <span className="card-slider__see-all-text">Показать все</span>
            <span className="card-slider__see-all-text-short">Все</span>
          </Link>
          <div className="card-slider__nav">
            <button type="button" className="card-slider__arrow card-slider__arrow_prev" disabled={!canLeft} onClick={() => scroll('left')}>
              {CHEVRON}
            </button>
            <button type="button" className="card-slider__arrow card-slider__arrow_next" disabled={!canRight} onClick={() => scroll('right')}>
              {CHEVRON}
            </button>
          </div>
        </div>
      </div>
      <div
        ref={trackRef}
        className="card-slider__track"
        style={{ '--item-width': '165px', '--item-width-sm': '150px', '--card-gap': '25px', '--fade-left': fades.left, '--fade-right': fades.right }}
      >
        {items.map((game, index) => (
          <GameCard key={game.code} game={game} si={index} clip={clipMap[index] ?? 1} />
        ))}
      </div>
    </section>
  );
}

export default function HomePage({}) {
  const location = useLocation();
  const { user } = useAuth();
  const { favorites, favoritesLoaded } = useLikes();
  const menuRef = useRef(null);
  const [tabStyle, setTabStyle] = useState({ '--width': '0px', '--x': '0px' });

  const isAuthenticated = Boolean(user);
  const TABS = isAuthenticated
    ? TABS_BASE
    : TABS_BASE.filter((tab) => tab.to !== '/?tab=favorites');
  const activeIndex = TABS.findIndex((tab) => isActive(tab, location));
  const tabParam = new URLSearchParams(location.search).get('tab');
  const activeTab = TAB_CONTENT[tabParam] ?? null;
  const isFavorites = tabParam === 'favorites';
  const favoriteItems = favoritesLoaded
    ? IN_HOUSE.filter((game) => favorites.has(game.name.toLowerCase()))
    : [];


  useEffect(() => {
    const menu = menuRef.current;
    if (!menu) return;

    const update = () => {
      const idx = TABS.findIndex((tab) => isActive(tab, location));
      const item = menu.querySelectorAll('.tab-menu__item')[idx];
      if (!item) return;

      setTabStyle({ '--width': `${item.offsetWidth}px`, '--x': `${item.offsetLeft}px` });

      menu.scrollTo({ left: item.offsetLeft - (menu.clientWidth - item.offsetWidth) / 2, behavior: 'smooth' });
    };

    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, [location]);

  return (
    <div className="content-wrapper">
      <div className="catolog-page">
        <div className="lobby">
          <div className="container">
            <div className="lobby__menu">
              <div
                ref={menuRef}
                className="tab-menu tab-menu_active"
                style={{ '--width': tabStyle['--width'], '--x': tabStyle['--x'] }}
              >
                {TABS.map((tab, index) => {
                  const { label, Icon } = tab;
                  const active = index === activeIndex;
                  return (
                    <Link
                      key={tab.to}
                      to={tab.to}
                      className={`tab-menu__item${active ? ' tab-menu__item_active' : ''}`}
                      aria-current={active ? 'page' : undefined}
                    >
                      <Icon />
                      <span>{label}</span>
                    </Link>
                  );
                })}
              </div>
            </div>
            <div className="lobby-content">
              {isFavorites ? (
                favoriteItems.length === 0 ? (
                  EMPTY_STATE
                ) : (
                  <div className="lobby__content">
                    <div className="catalog-grid">
                      <div className="catalog-grid__body">
                        <div className="game-grid">
                          {favoriteItems.map((game, index) => (
                            <GameCard key={game.code} game={game} si={index} />
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                )
              ) : activeTab ? (
                activeTab.items.length === 0 ? (
                  EMPTY_STATE
                ) : (
                  <div className="lobby__content">
                    <div className="catalog-grid">
                      <div className="catalog-grid__body">
                        <div className="game-grid">
                          {activeTab.items.map((game, index) => (
                            <GameCard key={game.code} game={game} si={index} />
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                )
              ) : (
                <div className="lobby-tab">
                  <div className="lobby-tab__rows">
                    <CardSlider title="Оригинальные" to="/?tab=in-house" Icon={ROI} items={IN_HOUSE} />
                    <CardSlider title="Настольные" to="/?tab=in-table" Icon={TAI} items={IN_TABLE} />
                    <CardSlider title="Игровые Шоу" to="/?tab=in-table" Icon={GSI} items={IN_GAMESHOW} />
                    <CardSlider title="Слоты" to="/?tab=in-slots" Icon={SLI} items={IN_SLOTS} />
                    <CardSlider title="Лайв-игры" to="/?tab=in-live" Icon={LVI} items={IN_LIVE} />
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}