import { createContext, useContext, useState } from 'react'

const ShareModalContext = createContext()

export function ShareModalProvider({ children }) {
  const [isOpen, setIsOpen] = useState(false)
  const [game, setGame] = useState(null)

  const openShareModal = (gameName) => {
    setGame(gameName)
    setIsOpen(true)
    document.body.style.overflowY = 'hidden'
  }

  const closeShareModal = () => {
    setIsOpen(false)
    setGame(null)
    document.body.style.overflowY = 'auto'
  }

  return (
    <ShareModalContext.Provider value={{ isOpen, game, openShareModal, closeShareModal }}>
      {children}
    </ShareModalContext.Provider>
  )
}

export function useShareModal() {
  return useContext(ShareModalContext)
}
