const HOLES_ROWS = [
  { key: 'low', items: ['x16', 'x7', 'x2', 'x1.4', 'x1.3', 'x1.1', 'x1.1', 'x1', 'x0.5', 'x1', 'x1.1', 'x1.1', 'x1.3', 'x1.4', 'x2', 'x7', 'x16'] },
  { key: 'medium', items: ['x110', 'x40', 'x9', 'x5', 'x2.7', 'x1.5', 'x1', 'x0.5', 'x0.3', 'x0.5', 'x1', 'x1.5', 'x2.7', 'x5', 'x9', 'x40', 'x110'] },
  { key: 'high', items: ['1000', 'x130', 'x23', 'x9', 'x3.8', 'x2', 'x0.2', 'x0.2', 'x0.2', 'x0.2', 'x0.2', 'x2', 'x3.8', 'x9', 'x23', 'x130', '1000'] },
]

const FORM_COLORS = ['blue', 'green', 'red']
const PRESETS = [0.5, 5, 25, 100, 500]
const SLOT_COUNT = 17 // лунок (совпадает с длиной рядов в HOLES_ROWS)
const PEG_ROWS = 16 // 16 рядов: 3..18 колышков (Stake-подобная пирамида)
const PEG_COLOR = '#3b4759'
const FIELD_W = 0.96 // ширина поля слотов (0.98 = отступы по 1%)
const GAP_X = 1 // шаг колышков = sx * GAP_X (меньше 1 -> плотнее)
const GAP_Y = 0.95 // множитель вертикального шага (меньше 1 -> плотнее)
const PEG_R = 0.006 // радиус колышка = w * PEG_R

export function getBoardGeometry(w, h) {
  const sx = w * FIELD_W / SLOT_COUNT // шаг слота (для лунок)
  const pad = (w - sx * SLOT_COUNT) / 2 // боковые отступы слотов
  const gx = sx * GAP_X // фактический шаг между колышками
  const r = Math.max(1.5, w * PEG_R) // радиус колышка
  const y0 = h * 0.055 // верхний ряд
  const y1 = h - h * 0.14 - h * 0.02 // нижний ряд над лунками (лунки = низ 14%)
  const sy = ((y1 - y0) / (PEG_ROWS - 1)) * GAP_Y

  const rows = []
  for (let row = 0; row < PEG_ROWS; row++) {
    const count = row + 3
    const y = y0 + row * sy
    const startX = w / 2 - ((count - 1) / 2) * gx
    const items = []
    for (let i = 0; i < count; i++) {
      items.push({ x: startX + i * gx, y })
    }
    rows.push(items)
  }

  const slotCenters = []
  for (let i = 0; i < SLOT_COUNT; i++) {
    slotCenters.push(pad + (i + 0.5) * sx)
  }

  return { rows, slotCenters, sx, gx, sy, r, pad }
}

const MODE_ROW = { blue: 'low', green: 'medium', red: 'high' }

function slotIndexesForK(mode, k) {
  const row = HOLES_ROWS.find((x) => x.key === MODE_ROW[mode])
  if (!row) return []
  const idx = []
  row.items.forEach((item, i) => {
    if (Math.abs(parseFloat(String(item).replace('x', '')) - Number(k)) < 1e-9) idx.push(i)
  })
  return idx
}

const MODE_LAND_Y = { blue: 0.883, green: 0.929, red: 0.976 }

function planWaypoints(geom, slot, mode, H, landOffset = 0) {
  const gMin = Math.max(0, slot - PEG_ROWS)
  const gMax = Math.min(1, slot)
  const g0 = gMin + Math.floor(Math.random() * (gMax - gMin + 1))
  let g = g0
  const minDist = geom.r * 2.5 // радиус шара + радиус колышка
  const off = minDist * 0.45   // горизонтальное смещение точки касания плеча
  const wps = []
  for (let s = 0; s < PEG_ROWS; s++) {
    const rowsLeft = PEG_ROWS - s
    const rightsLeft = slot - g
    let side
    if (rightsLeft <= 0) side = -1
    else if (rightsLeft >= rowsLeft) side = 1
    else side = Math.random() < 0.5 ? 1 : -1
    const peg = geom.rows[s][g + 1]
    const dx = off * side + (Math.random() - 0.5) * off * 0.4 // лёгкий «живой» разброс
    wps.push({ x: peg.x + dx, y: peg.y - Math.sqrt(Math.max(0, minDist * minDist - dx * dx)), peg })
    if (side === 1) g += 1
  }
  wps.push({ x: geom.slotCenters[slot], y: H * MODE_LAND_Y[mode] - landOffset, peg: null })
  return { wps, g0 }
}

export const plinkoGameApi = { drop: () => {} }

let runningBalls = 0
const runningListeners = new Set()
const notifyRunning = () => runningListeners.forEach((fn) => fn())

export const plinkoRunning = {
  add: () => { runningBalls += 1; notifyRunning() },
  remove: () => { runningBalls = Math.max(0, runningBalls - 1); notifyRunning() },
  reset: () => { if (runningBalls) { runningBalls = 0; notifyRunning() } },
  subscribe(fn) { runningListeners.add(fn); return () => runningListeners.delete(fn) },
  snapshot: () => runningBalls > 0,
}

function usePlinkoRunning() {
  return useSyncExternalStore(plinkoRunning.subscribe, plinkoRunning.snapshot, plinkoRunning.snapshot)
}
const PHYS = {
  timeScale: 0.8,        // замедление времени — дуги читаются глазом
  gravity: 2100,         // px/с^2: мягкая гравитация = длинные плавные дуги
  eMin: 0.45, eMax: 0.85,   // реституция: ВСЕГДА < 1 -> энергия убывает
  deadChance: 0.12,      // шанс «мёртвого» удара (отскок почти гаснет)
  deadMul: [0.3, 0.6],   // его множитель (тоже < 1)
  gMood: [0.85, 1.12],   // случайный множитель гравитации сегмента
  maxUp: 430,            // потолок скорости отскока, px/с
  maxStep: 0.008,        // макс. шаг интегрирования, с (против «туннелирования»)
  maxIter: 12,           // макс. событий (касаний) на кадр с одного шара
  eSide: 0.5,            // реституция незапланированного (скользящего) касания
  slideVn: 35,           // ниже какой скорости сближения — скольжение, не удар
  vxMax: 300,
}

const BALL_COLORS = { blue: '#3d7cfd', green: '#00d169', red: '#ff4a66' }
const BALL_DARK = { blue: '#2a5cc8', green: '#00a04d', red: '#cc3a50' }
const PEG_FLASH_MS = 1000 // длительность мягкой вспышки колышка
const SQUASH_MS = 110     // длительность squash-деформации шара после касания

function lerpHex(a, b, t) {
  const pa = [parseInt(a.slice(1, 3), 16), parseInt(a.slice(3, 5), 16), parseInt(a.slice(5, 7), 16)]
  const pb = [parseInt(b.slice(1, 3), 16), parseInt(b.slice(3, 5), 16), parseInt(b.slice(5, 7), 16)]
  const c = pa.map((v, i) => Math.round(v + (pb[i] - v) * t))
  return `rgb(${c[0]},${c[1]},${c[2]})`
}

export function PlinkoCanvas({ onLand }) {
  const canvasRef = useRef(null)
  const onLandRef = useRef(onLand)
  const { state } = useAppState()
  const stateRef = useRef(state)
  onLandRef.current = onLand
  stateRef.current = state

  useEffect(() => {
    const canvas = canvasRef.current
    const wrap = canvas && canvas.parentElement
    if (!wrap) return undefined

    const ctx = canvas.getContext('2d')
    let W = 0
    let H = 0
    let geom = null
    let raf = 0
    let offsetY = 0

    const balls = [] // { x, y, vx, vy, seg, vUp, gMul, hitAt, sideHits, wps, wi, slotIdx, mode, bet_uuid, done }
    const pegHits = new Map() // key -> время касания (мс)
    const G = PHYS.gravity // гравитация базы, px/с^2

    const resize = () => {
      const { width, height } = wrap.getBoundingClientRect()
      if (!width || !height) return
      const dpr = window.devicePixelRatio || 1
      canvas.width = Math.round(width * dpr)
      canvas.height = Math.round(height * dpr)
      canvas.style.width = `${width}px`
      canvas.style.height = `${height}px`
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      W = width
      H = height
      // компенсация margin-top: 15px у canvas относительно контента —
      // иначе шарик приземляется ниже центра ряда коэффициентов
      const cr = canvas.getBoundingClientRect()
      const wr = wrap.getBoundingClientRect()
      offsetY = cr.top - wr.top
      geom = getBoardGeometry(W, H)
    }

    const pegKey = (p) => `${p.x.toFixed(1)}_${p.y.toFixed(1)}`

    let dropSeq = 0 // сквозной номер шарика для plinko_ballCount

    const drop = (mode, k, bet_uuid) => {
      if (!geom) return false // канвас не готов — шар не полетит (см. handlePlay)
      const idxs = slotIndexesForK(mode, k)
      const idx = idxs.length ? idxs[Math.floor(Math.random() * idxs.length)] : (SLOT_COUNT - 1) / 2
      const { wps, g0 } = planWaypoints(geom, idx, mode, H, offsetY)
      const top = geom.rows[0]
      const x = (top[g0].x + top[g0 + 1].x) / 2
      const y = top[0].y - geom.sy * 0.7
      dropSeq += 1
      balls.push({ x, y, vx: 0, vy: 0, seg: false, vUp: 0, gMul: 1, hitAt: -1e9, sideHits: 0, free: false, freeY: 0, freePeg: null, lastPeg: null, wps, wi: 0, slotIdx: idx, mode, bet_uuid, done: false, num: dropSeq, trail: [] })
      return true
    }
    plinkoGameApi.drop = drop

    const landBall = (ball) => {
      onLandRef.current && onLandRef.current(ball.slotIdx, ball.mode, ball.bet_uuid)
    }

    const startSegment = (b, v0) => {
      while (b.wi < b.wps.length - 1 && b.wps[b.wi].y <= b.y) b.wi += 1
      const wp = b.wps[b.wi]
      const Gs = G * b.gMul
      const s0 = v0 === undefined ? -b.vUp : Math.min(v0, 0)
      const T = (-s0 + Math.sqrt(Math.max(0, s0 * s0 + 2 * Gs * Math.max(wp.y - b.y, 6)))) / Gs
      b.vy = s0
      b.vx = Math.max(-PHYS.vxMax, Math.min(PHYS.vxMax, (wp.x - b.x) / Math.max(T, 0.05)))
      b.seg = true
    }

    // индекс ряда по высоте y (ряды 0..PEG_ROWS-1 идут сверху вниз)
    const rowAt = (y) => Math.round((y - geom.rows[0][0].y) / geom.sy)

    const probeSidePeg = (b, Gs, exA, exB) => {
      const md = geom.r * 2.5
      const yApex = b.vy < 0 ? b.y - (b.vy * b.vy) / (2 * Gs) : b.y
      const sFrom = Math.max(0, rowAt(Math.min(yApex, b.y)) - 1)
      const sTo = Math.min(PEG_ROWS - 1, rowAt(Math.max(b.y, b.wps[b.wi].y)) + 1)
      for (let s = sFrom; s <= sTo; s++) {
        const row = geom.rows[s]
        for (let i = 0; i < row.length; i++) {
          const p = row[i]
          if (p === exA || p === exB) continue
          const dx = b.x - p.x
          if (dx > md || dx < -md) continue // быстрый отсёк по горизонтали
          const dy = b.y - p.y
          const d2 = dx * dx + dy * dy
          if (d2 > md * md || d2 < 1e-9) continue
          const d = Math.sqrt(d2)
          const nx = dx / d
          const ny = dy / d
          if (b.vx * nx + b.vy * ny >= 0) continue // удаляется от колышка
          return { p, nx, ny }
        }
      }
      return null
    }

    const step = (dt) => {
      if (!geom) return
      const r = dt * PHYS.timeScale

      for (const b of balls) {
        if (b.done) continue
        if (!b.seg && !b.free) startSegment(b) // первый сегмент — свободное падение

        // запись траектории для отладочного отображения пути (plinko_path)
        if (stateRef.current?.plinko_path) {
          b.trail.push(b.x, b.y)
          if (b.trail.length > 1200) b.trail.splice(0, 2)
        }


        let rem = r
        let guard = 0
        while (rem > 1e-6 && !b.done && guard++ < PHYS.maxIter) {
          const wp = b.wps[b.wi]
          const Gs = G * b.gMul
          const h = Math.min(rem, PHYS.maxStep)
          let tc = h
          if (!b.free && b.vy > 0) {
            const disc = b.vy * b.vy + 2 * Gs * (wp.y - b.y)
            if (disc >= 0) {
              const root = (-b.vy + Math.sqrt(disc)) / Gs
              if (root > 1e-6 && root < tc) tc = root
            }
          }

          const py = b.y
          b.vy += Gs * tc
          b.x += b.vx * tc
          b.y = py + b.vy * tc - 0.5 * Gs * tc * tc
          rem -= tc
          const side = probeSidePeg(b, Gs, b.free ? null : wp.peg, (b.wps[b.wi - 1] || {}).peg)
          if (side) {
            const md = geom.r * 2.5
            const vn = b.vx * side.nx + b.vy * side.ny
            const sliding = b.free && side.p === b.freePeg && vn > -PHYS.slideVn
            // squash и вспышка — только на настоящий удар, не при скольжении
            if (!sliding) {
              b.hitAt = performance.now()
              pegHits.set(pegKey(side.p), b.hitAt)
            }
            b.lastPeg = side.p
            b.sideHits += 1

            if (sliding) {
              // ограничение угла обкатки: шар не должен перекатываться через
              // верхушку колышка и вылетать с его обратной стороны
              const ang = Math.atan2(b.y - side.p.y, b.x - side.p.x)
              let dAng = Math.abs(ang - (b.slideStartAngle ?? ang))
              if (dAng > Math.PI) dAng = Math.PI * 2 - dAng
              if (dAng > b.slideMaxAngle) {
                b.free = false
                b.freePeg = null
                b.hitAt = performance.now()
                pegHits.set(pegKey(side.p), b.hitAt)
                startSegment(b, b.vy)
                continue
              }
              const tx = -side.ny
              const ty = side.nx
              const sgn = tx < 0 ? -1 : 1
              const sp = Math.abs(b.vx * tx + b.vy * ty) * 0.7 + 20
              b.vx = tx * sp * sgn
              b.vy = ty * sp * sgn
              b.x = side.p.x + side.nx * md * 1.02
              b.y = side.p.y + side.ny * md * 1.02
              continue
            }

            b.x = side.p.x + side.nx * md
            b.y = side.p.y + side.ny * md
            b.vx -= (1 + PHYS.eSide) * vn * side.nx
            b.vy -= (1 + PHYS.eSide) * vn * side.ny
            const sep = b.vx * side.nx + b.vy * side.ny
            if (sep < PHYS.sideSep) {
              b.vx += (PHYS.sideSep - sep) * side.nx
              b.vy += (PHYS.sideSep - sep) * side.ny
            }
            b.free = true
            b.freePeg = side.p
            b.freeY = side.p.y + geom.sy * 0.6
            b.slideStartAngle = Math.atan2(b.y - side.p.y, b.x - side.p.x)
            b.slideMaxAngle = Math.PI * 0.55
            continue
          }

          if (b.free && b.y >= b.freeY) {
            b.free = false
            b.freePeg = null
            startSegment(b, b.vy)
            continue
          }

          if (b.free) continue

          if (b.vy > 0 && b.y >= wp.y - 1e-3) {
            b.y = wp.y
            if (!wp.peg) b.x = wp.x // финал — точно в центр нужной лунки
            b.sideHits = 0
            b.lastPeg = wp.peg
            if (wp.peg) {
              let v = (PHYS.eMin + Math.random() * (PHYS.eMax - PHYS.eMin)) * b.vy
              if (Math.random() < PHYS.deadChance) {
                v *= PHYS.deadMul[0] + Math.random() * (PHYS.deadMul[1] - PHYS.deadMul[0])
              }
              if (wp.y > b.wps[b.wps.length - 1].y - geom.sy * 0.5) v *= 0.6
              b.gMul = PHYS.gMood[0] + Math.random() * (PHYS.gMood[1] - PHYS.gMood[0])
              const headroom = Math.max(0, b.y - (geom.rows[0][0].y - geom.sy * 0.6))
              const vCeil = Math.sqrt(2 * G * b.gMul * headroom)
              b.vUp = Math.min(v, PHYS.maxUp, vCeil)
              b.hitAt = performance.now()
              pegHits.set(pegKey(wp.peg), b.hitAt)
              b.wi += 1
              startSegment(b)
            } else {
              b.vx = 0
              b.vy = 0
              b.done = true
              b.doneAt = performance.now()
              landBall(b)
            }
          }
        }
      }

      // шарики, завершившие полёт, держим в массиве ещё plinko_pathCoolDown мс,
      // чтобы след пути (plinko_path) был виден после приземления
      const coolMs = stateRef.current?.plinko_path ? (Number(stateRef.current?.plinko_pathCoolDown) || 0) : 0
      for (let i = balls.length - 1; i >= 0; i--) {
        const b = balls[i]
        if (!b.done) continue
        if (coolMs > 0 && performance.now() - b.doneAt <= coolMs) continue
        balls.splice(i, 1)
      }
    }

    const render = () => {
      if (!geom) return
      const now = performance.now()
      ctx.clearRect(0, 0, W, H)

      const ballR = geom.r * 1.5
      for (const row of geom.rows) {
        for (const p of row) {
          const key = pegKey(p)
          const hitAt = pegHits.get(key)
          let color = PEG_COLOR
          if (hitAt !== undefined) {
            const t = (now - hitAt) / PEG_FLASH_MS
            if (t >= 1) {
              pegHits.delete(key)
            } else {
              const e = 1 - (1 - t) * (1 - t)
              color = lerpHex('#ffffff', PEG_COLOR, e)
            }
          }
          ctx.fillStyle = color
          ctx.beginPath()
          ctx.arc(p.x, p.y, geom.r, 0, Math.PI * 2)
          ctx.fill()
        }
      }

      for (const b of balls) {
        if (b.done) continue
        ctx.fillStyle = BALL_COLORS[b.mode] || '#ffffff'
        // squash после касания — «резина»
        const ht = now - b.hitAt
        const k = ht >= 0 && ht < SQUASH_MS ? 0.32 * (1 - ht / SQUASH_MS) : 0
        if (k) {
          ctx.save()
          ctx.translate(b.x, b.y)
          ctx.scale(1 + k, 1 - k)
          ctx.beginPath()
          ctx.arc(0, 0, ballR, 0, Math.PI * 2)
          ctx.fill()
          ctx.restore()
        } else {
          ctx.beginPath()
          ctx.arc(b.x, b.y, ballR, 0, Math.PI * 2)
          ctx.fill()
        }

        // отображение номера шарика (plinko_ballCount)
        if (stateRef.current?.plinko_ballCount) {
          const fontSize = Math.max(7, Math.round(ballR * 1.3))
          ctx.fillStyle = 'rgba(255,255,255,0.85)'
          ctx.font = `bold ${fontSize}px monospace`
          ctx.textAlign = 'center'
          ctx.textBaseline = 'middle'
          ctx.fillText(String(b.num), b.x, b.y)
        }
      }

      // отображение пути шариков (plinko_path) — пунктирная линия по waypoint'ам
      if (stateRef.current?.plinko_path) {
        for (const b of balls) {
          const wps = b.wps
          ctx.lineCap = 'round'
          ctx.lineJoin = 'round'
          ctx.lineWidth = Math.max(1.2, geom.r * 0.6)
          ctx.setLineDash([4, 4])
          // предсказанный путь рисуем только для летящих шаров
          if (!b.done) {
            for (let i = 1; i < wps.length; i++) {
              ctx.strokeStyle = BALL_COLORS[b.mode] || '#fff'
              ctx.globalAlpha = 0.3
              ctx.beginPath()
              ctx.moveTo(wps[i - 1].x, wps[i - 1].y)
              ctx.lineTo(wps[i].x, wps[i].y)
              ctx.stroke()
            }
          }
          ctx.setLineDash([])
          ctx.globalAlpha = 1

          // также отрисовка фактического следа (trail) — сохраняется ещё
          // plinko_pathCoolDown мс после приземления (шаг не удаляет шар раньше)
          const trail = b.trail
          if (trail.length >= 4) {
            ctx.lineCap = 'round'
            ctx.lineWidth = Math.max(1.5, geom.r * 0.8)
            ctx.strokeStyle = BALL_DARK[b.mode] || '#888'
            ctx.globalAlpha = 0.6
            // trail — плоский массив [x0,y0, x1,y1, ...]: шаг по 2, пары не смещаем
            for (let i = 2; i < trail.length; i += 2) {
              ctx.beginPath()
              ctx.moveTo(trail[i - 2], trail[i - 1])
              ctx.lineTo(trail[i], trail[i + 1])
              ctx.stroke()
            }
            ctx.globalAlpha = 1
          }
        }
      }
    }

    let last = performance.now()
    const loop = (now) => {
      const dt = Math.min((now - last) / 1000, 0.032)
      last = now
      step(dt)
      render()
      if (balls.length === 0 && pegHits.size === 0) {
        raf = 0
        return
      }
      raf = requestAnimationFrame(loop)
    }
    const kick = () => {
      if (!raf) {
        last = performance.now()
        raf = requestAnimationFrame(loop)
      }
    }

    resize()
    render()
    const dropPrev = plinkoGameApi.drop
    plinkoGameApi.drop = (mode, k, bet_uuid) => {
      const flew = dropPrev(mode, k, bet_uuid)
      kick()
      return flew
    }
    const ro = new ResizeObserver(() => {
      resize()
      render()
    })
    ro.observe(wrap)
    return () => {
      cancelAnimationFrame(raf)
      ro.disconnect()
      plinkoGameApi.drop = () => {}
      plinkoRunning.reset()
    }
  }, [])

  return <canvas ref={canvasRef} id="plinkoCanvas"></canvas>
}

