function PlinkoForm({ color, presetsRight = false }) {
  const inputId = `bet_${color}`
  const { profile, holdLocalBet, restoreLocalBet } = useAuth()

  const [tempValue, setTempValue] = useState('10')
  const prevValueRef = useRef('10')
  const [bet, setBet] = useState(10)

  const BET_MIN = 0.01
  const BET_MAX = () => Number(profile?.balance ?? 0)
  const BET_DEFAULT = 10

  const clampValue = (num) => {
    return Math.max(BET_MIN, Math.min(BET_MAX(), num))
  }

  const validateAndNormalize = (raw) => {
    const normalized = raw.toString().replace(',', '.')
    const num = parseFloat(normalized)
    if (isNaN(num)) return BET_DEFAULT
    return clampValue(num)
  }

  const commitBet = (value) => {
    const finalStr = value.toString()
    prevValueRef.current = finalStr
    setTempValue(finalStr)
    setBet(value)
  }

  const handleChange = (e) => {
    const rawValue = e.target.value
    if (rawValue === '' || /^\d*\.?\d*$/.test(rawValue)) {
      if (rawValue === '' || (rawValue.length > 1 && rawValue.startsWith('0') && !rawValue.startsWith('0.') && !isNaN(rawValue[1]))) {
        setTempValue(prevValueRef.current)
        return
      }
      setTempValue(rawValue)
    }
  }

  const handleBlur = () => {
    commitBet(validateAndNormalize(tempValue))
  }

  const handlePresetChange = (preset) => {
    commitBet(preset)
  }

  const handleHalf = () => {
    commitBet(clampValue(Number(bet) / 2))
  }

  const handleDouble = () => {
    commitBet(clampValue(Number(bet) * 2))
  }

  const [pending, setPending] = useState(0)
  const loading = pending > 0

  const handlePlay = async () => {
    if (!profile) return
    if (Number(bet) <= 0 || Number(bet) > BET_MAX()) return
    setPending((p) => p + 1)
    holdBalance()
    holdLocalBet(Number(bet))
    try {
      markSupabaseCall('Plinko', 'pending')
      const { data, error } = await supabase.functions.invoke('Plinko-Release', {
        body: { action: 'plinko', data: { dep: Number(bet), plinkoMode: color } },
      })
      if (error) {
        releaseBalanceOrphan()
        restoreLocalBet(Number(bet))
        let serverMsg = error?.message || 'Ошибка игры'
        try {
          if (error.context) {
            const ctx = await error.context.clone().json()
            if (ctx?.error) serverMsg = ctx.error
          }
        } catch (e) { /* тело не JSON */ }
        markSupabaseCall('Plinko', 'error', serverMsg)
        // mess(500, serverMsg)
        return
      }
      if (data?.error) {
        releaseBalanceOrphan()
        restoreLocalBet(Number(bet))
        markSupabaseCall('Plinko', 'error', data.error)
        mess(400, data.error)
        return
      }
      if (!data || typeof data.k === 'undefined') {
        releaseBalanceOrphan()
        restoreLocalBet(Number(bet))
        markSupabaseCall('Plinko', 'error', 'bad response')
        mess(500, 'Неизвестный ответ от сервера')
        return
      }
      markSupabaseCall('Plinko', 'ok')
      const flew = plinkoGameApi.drop(color, data.k)
      if (!flew) {
        // канвас не готов — шар не полетит, возвращаем списание
        releaseBalanceOrphan()
        restoreLocalBet(Number(bet))
        markSupabaseCall('Plinko', 'error', 'canvas not ready')
        mess(500, 'Игра ещё не готова, попробуйте ещё раз')
      }
    } catch (err) {
      releaseBalanceOrphan()
      restoreLocalBet(Number(bet))
      console.error('Plinko play error:', err)
      markSupabaseCall('Plinko', 'error', String(err))
      mess(500, 'Ошибка игры')
    } finally {
      setPending((p) => p - 1)
    }
  }

  return (
    <div className="plinko-game-form">
      <div className="game-form">
        <div className="game-form-header">
          <div className="game-form__label-custom">
            <label className="tumbler" htmlFor={inputId}>
              <span className="tumbler-label">Ставка</span>
            </label>
          </div>
          <div className="game-form__label-extra">
            <div aria-label="Toggle fast mode" className="plinko-game-form__fast-bet plinko-game-form__fast-bet_disabled">
              <span>Fast</span>
              {FAST_ICON}
            </div>
          </div>
        </div>
        <div className="game-form-body">
          <div className="game-form__input-icon">{RUB_ICON}</div>
          <div className="game-form__input">
            <input
              type="text"
              id={inputId}
              name={inputId}
              inputMode="decimal"
              autoComplete="off"
              value={tempValue}
              onChange={handleChange}
              onBlur={handleBlur}
            />
          </div>
          <div className="game-form-tools">
            <button aria-label="Divide" className="game-form-tools__item game-form-tools__item_divider" onClick={handleHalf}>
              {DIVIDER_ICON}
            </button>
            <button aria-label="Multiply" className="game-form-tools__item game-form-tools__item_multiplier" onClick={handleDouble}>
              {MULTIPLIER_ICON}
            </button>
          </div>
        </div>
        <div className={`game-form-presets${presetsRight ? ' game-form-presets_right' : ''}`}>
          {PRESETS.map((preset) => (
            <button
              key={preset}
              aria-label={String(preset)}
              className="game-form-presets__item"
              onMouseDown={() => handlePresetChange(preset)}
            >
              {preset}
            </button>
          ))}
        </div>
      </div>
      <button aria-label="Ставка" className={`game-form-button game-form-buttonn game-form-button_${color}${loading ? ' game-form-button_loading' : ''}`} onClick={handlePlay}>
        <span className="game-form-button-content">
          <span className="game-form-button__text">
            Ставка
            <span className="game-form-button__loading">{LOADING_ICON}</span>
          </span>
          <span className="game-form-button__help"></span>
        </span>
        <span className="game-form-button__processing">{LOADING_ICON}</span>
      </button>
    </div>
  )
}

// ===========================================================================
// Body: углы, канвас, слоты
// ===========================================================================

export function PlinkoBody() {
  const [landed, setLanded] = useState(null) // { row, index } — подсветка выигравшей лунки
  const landTimer = useRef(0)

  const handleLand = (index, mode) => {
    setLanded({ row: MODE_ROW[mode], index })
    clearTimeout(landTimer.current)
    landTimer.current = setTimeout(() => setLanded(null), 1500)
    releaseBalance()
    plinkoRunning.remove()
    window.dispatchEvent(new CustomEvent('plinko:land', { detail: { index, mode } }))
  }

  useEffect(() => () => clearTimeout(landTimer.current), [])

  return (
    <div className="plinko-game-body">
      <div className="plinko-game-content">
        <div className="plinko-game-corners">
          <div className="plinko-game-corner plinko-game-corner_left"></div>
          <div className="plinko-game-corner plinko-game-corner_right">
            <div className="plinko-game-multipliers-wrapper">
              <div id="plinkoGameMultipliers" className="plinko-game-multipliers"></div>
            </div>
          </div>
        </div>
        <div className="plinko-game-canvas">
          <PlinkoCanvas onLand={handleLand} />
        </div>
        <div className="plinko-game-holes">
          {HOLES_ROWS.map((row) => (
            <div key={row.key} className={`plinko-game-holes-row plinko-game-holes-row_${row.key}`}>
              {row.items.map((item, index) => {
                const isLanded = landed && landed.row === row.key && landed.index === index
                return (
                  <div key={`${row.key}-${index}`} className={`plinko-game-holes-row__item${isLanded ? ' plinko-game-holes-row__item_landed' : ''}`}>
                    {item}
                  </div>
                )
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// ===========================================================================
// Footer: формы ставок + иконка скролла
// ===========================================================================

export function PlinkoFooter() {
  return (
    <div className="plinko-game-footer">
      <div className="plinko-game-form-wrapper">
        <div className="plinko-game-form-content">
          <div className="plinko-game-form plinko-game-form_empty"></div>
          {FORM_COLORS.map((color, index) => (
            <PlinkoForm key={color} color={color} presetsRight={index === FORM_COLORS.length - 1} />
          ))}
          <div className="plinko-game-form plinko-game-form_empty"></div>
        </div>
        <div className="plinko-game-form__scroll-icon">{SCROLL_ICON}</div>
      </div>
    </div>
  )
}

// ===========================================================================
// Игра целиком
// ===========================================================================

export default function PlinkoGame() {
  return (
    <div className="plinko-game game-inhouse-plinko__game">
      <PlinkoBody />
      <PlinkoFooter />
    </div>
  )
}