function TowerMultipliers({ stones, mode, profile, result }) {
  const currentMultipliers = MULTIPLIERS_TABLE[stones] || MULTIPLIERS_TABLE[1];
  const targetString = result?.[0] === true ? (result[1]?.findIndex(row => row?.[5] !== 1)-1 ?? 9) : profile?.Nuts?.stringNuts;

  return (
    <div className="tower-multipliers">
      {currentMultipliers.map((item, index) => {
        const dataCell = (targetString===(9-index)) ? 2 : (targetString>(9-index)) ? 1 : 0
        return (
        <div className={`tower-multipliers__item ${dataCell===2 ? 'tower-multipliers__item_winning' : 
          dataCell===1 ? 'tower-multipliers__item_opened' : ''}`} key={item.level}>
          <small>{item.level} уровень</small>
          <strong>{item.multiplier}</strong>
        </div>
      )})}
    </div>
  );
}

function TowerCells({ mode, profile, setSST, proccesing, setProcessing, result, setResult }) {
  const nutsArea = result?.[0] === true ? [...(result[1] || [])].reverse() : [...(profile?.Nuts?.nutsArea || [])].reverse();
  const targetString = result?.[0] === true ? (result[1]?.findIndex(row => row?.[5] !== 1) ?? 9) : profile?.Nuts?.stringNuts;

  return (
    <div className="tower-cells">
      {Array.from({ length: TOWER_ROWS }).map((_, rowIdx) => (
        <div key={rowIdx} className="tower-cells__row">
          {Array.from({ length: TOWER_COLS }).map((_, colIdx) => {
            const cellValue = nutsArea[rowIdx]?.[colIdx] ?? 4;
            const gamedRow = result[0] ? true : (nutsArea?.[rowIdx]?.[5] === 1);

            return (
              <div key={colIdx} onClick={() => mode!='start' && (8-rowIdx)===targetString 
                && NutsRun(profile, colIdx, setSST, setProcessing, setResult)}
                className="tower-cells__cell tower-cells__cell_disabled">
                <div className={`tower-cells__cell-wrapper ${(gamedRow && cellValue!==(2) && cellValue!==(3)) ? 'gamedRows' : ''}`}>
                  <div className={`tower-cells__cell-content ${mode!='start' ? 
                    (8-rowIdx)===targetString ?
                    proccesing ? proccesing===colIdx ? 'tower-cells__cell_proc' 
                    : 'tower-cells__cell_active-blocked' :
                    'tower-cells__cell_active' : '' : ''} 
                    ${cellValue===2 ? 'tower-cells__cell-win' : cellValue===3 ? 'tower-cells__cell_lose' : ''}`}>
                    <div className="tower-cells__cell-placeholder">{NUTS_SVG}</div>
                    <div className={`tower-cells__cell-symbol ${gamedRow ? cellValue===0 || cellValue===2 ? 'visible' : '' : ''}
                      ${cellValue===2 ? 'tower-cells__cell-symbol_animated' : ''}`}>
                      <div className={`tower-cells__cell-symbol-image df-nuts-cx ${cellValue===2 ? 'win-keno-cell-img' : ''}`}>
                        <img src={NUTS_PNG} alt="Nuts" />
                      </div>
                    </div>
                    <div className={`tower-cells__cell-symbol ${gamedRow ? (cellValue===3||cellValue===(1)) ? 'visible' : '' : ''}
                      ${cellValue===3 ? 'tower-cells__cell-symbol_animated' : ''}`}>
                      <div className={`tower-cells__cell-symbol-image ${cellValue===3 ? 'df-stones-cx' : 'df-nuts-cx'}`}>
                        <img src={STNE_PNG} alt="Stone" />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

function RightBody({ stones, mode, profile, setSST, proccesing, setProcessing, result, setResult }) {
  return (
    <div className="tower-game-body-right">
      <div className="tower-game-row">
        <div className="tower-game-field">
          <TowerCells mode={mode} profile={profile} setSST={setSST} proccesing={proccesing} setProcessing={setProcessing} result={result} setResult={setResult}/>
        </div>

        <TowerMultipliers result={result} setResult={setResult} stones={stones} mode={mode} profile={profile}/>
      </div>

      <div className="tower-status-bar">
        <div className="tower-status-bar-content">
          {/* Выбор ячейки / Автовыбор */}
          <div className="visible-bar tower-status-bar__choice tower-status-bar__choice_bet tower-status-bar__choice_visible">
            <div className="tower-status-bar__choice-text">
              <strong className='white-bar-nuts'>Выберите ячейку</strong>
            </div>
            <div className="tower-status-bar__choice-text">или</div>
            <button
              onClick={()=>(!proccesing || profile?.Nuts?.dep) && NutsRun(profile, random.int(0, 4), setSST, setProcessing, setResult)}
              aria-label="Random"
              className={`tower-status-bar__choice-button tower-status-bar__choice-button_yellow 
                ${(proccesing || !profile?.Nuts?.dep) ? 'tower-status-bar__choice-button_disabled' : ''}`}
            >
              <span>Автовыбор</span>
              {RANDOM_SVG}
            </button>
          </div>

          {/* Авто-ставка */}
          <div className="tower-status-bar__choice tower-status-bar__choice_auto-bet">
            <div className="tower-status-bar__choice-text tower-status-bar__choice-text_wide">
              <strong>Выберите</strong> ячейку на одном или нескольких уровнях и{' '}
              <strong>запустите</strong> игру
            </div>
            <button
              disabled
              aria-label="Reset"
              className="tower-status-bar__choice-button tower-status-bar__choice-button_default tower-status-bar__choice-button_disabled"
            >
              <span>Очистить</span>
            </button>
          </div>

          {/* Победа */}
          <div className="tower-status-bar__win">
            <div className="tower-status-bar__win-text">Победа</div>
            <div className="tower-status-bar__win-multiplier" />
            <div className="tower-status-bar__win-text" />
          </div>
        </div>
      </div>
    </div>
  );
}

export default function TowerLeft({ profile, onPlay }) {
  const [bet, setBet] = useState(10)
  const [stones, setStones] = useState(1)
  const [stateST, setSST] = useState('start')
  const [ proccesing, setProcessing ] = useState(false);
  const [result, setResult] = useState([false, false])

  return (
    <div className='tower-game page-game'>
      <div className='tower-game-body'>
        <div className='tower-game-body-left'>
          <TowerInformer />
        </div>
        <RightBody result={result} setResult={setResult} stones={stones} mode={stateST} profile={profile} setSST={setSST} proccesing={proccesing} setProcessing={setProcessing}/>
      </div>
      <div className='tower-game-footer'>
        <DepMenu setResult={setResult} proccesing={proccesing} setProcessing={setProcessing} stateST={stateST} setSST={setSST} profile={profile} onPlay={onPlay} bet={bet} setBet={setBet} stones={stones} setStones={setStones} />
      </div>
    </div>
  )
}
