import { Link, useLocation, Navigate } from "react-router-dom";
import BetsData from "./betsData";

import '../css/HB.css'

const TABS = [
  { key: 'bets',      label: 'Ставки' },
  { key: 'payments',  label: 'Платежи' },
  { key: 'withdraws', label: 'Выводы' },
  { key: 'bonuses',   label: 'Бонусы' },
  { key: 'other',     label: 'Прочие операции' },
]

const BASE = '/account/transactions'

export default function HistoryBets({profile}) {
  const { pathname } = useLocation()

  if (pathname === BASE) return <Navigate to={`${BASE}/${TABS[0].key}`} replace />

  const activeTab = TABS.find((tab) => pathname === `${BASE}/${tab.key}`) || TABS[0]

  return(
    <>
    <div className="account-transactions-menu">
      <div className="account-transactions-menu-items">
        {TABS.map((tab) => {
          const active = tab.key === activeTab.key
          return (
            <Link
              key={tab.key}
              to={`${BASE}/${tab.key}`}
              aria-current={active ? 'page' : undefined}
              className={`account-transactions-menu-item${active ? ' account-transactions-menu-item_active' : ''}`}
            >
              {tab.label}
            </Link>
          )
        })}
      </div>
    </div>
      <div className="account-transactions-content">
        <div className={`account-transactions-table account-transactions-table_${activeTab.key}`}>
          <BetsData mode={activeTab.key} profile={profile} />
        </div>
      </div>
    </>
  )
}