export function markSupabaseCall(name, status, error = null) {
  if (!INIT_DATA.supabase[name]) INIT_DATA.supabase[name] = {}
  INIT_DATA.supabase[name].status = status
  INIT_DATA.supabase[name].lastError = error
  INIT_DATA.supabase[name].lastAt = Date.now()
}
const AUTH_FLOW_KEY = 'unluckyduck_auth_flow';
const AUTH_FLOW_FALLBACK = '/';

function isInternalPath(path) {
  return typeof path === 'string'
    && path.startsWith('/')
    && !path.startsWith('//')
    && !path.startsWith('/auth');
}

export function beginAuthFlow(provider = 'google') {
  const returnTo = `${window.location.pathname}${window.location.search}${window.location.hash}`;
  INIT_DATA.auth = {
    provider,
    returnTo: isInternalPath(returnTo) ? returnTo : AUTH_FLOW_FALLBACK,
    startedAt: Date.now(),
  };
  try {
    sessionStorage.setItem(AUTH_FLOW_KEY, JSON.stringify(INIT_DATA.auth));
  } catch (err) {
    console.warn('[INIT_DATA] auth flow save failed:', err);
  }
  return INIT_DATA.auth;
}

export function readAuthFlow() {
  if (!INIT_DATA.auth.returnTo) {
    try {
      const raw = sessionStorage.getItem(AUTH_FLOW_KEY);
      if (raw) INIT_DATA.auth = { ...INIT_DATA.auth, ...JSON.parse(raw) };
    } catch (err) {
      console.warn('[INIT_DATA] auth flow read failed:', err);
    }
  }
  return INIT_DATA.auth;
}

export function getAuthReturnTo() {
  const { returnTo } = readAuthFlow();
  return isInternalPath(returnTo) ? returnTo : AUTH_FLOW_FALLBACK;
}

export function endAuthFlow() {
  INIT_DATA.auth = { provider: null, returnTo: null, startedAt: 0 };
  try {
    sessionStorage.removeItem(AUTH_FLOW_KEY);
  } catch (err) {
    console.warn('[INIT_DATA] auth flow clear failed:', err);
  }
}