import { createContext, useContext, useState } from 'react'

const HTPContext = createContext()

export function HTPProvider({ children }) {
  const [isHTPOpen, setIsHTPOpen] = useState(false)
  const openHTP = () => setIsHTPOpen(true)
  const closeHTP = () => setIsHTPOpen(false)
  return (
    <HTPContext.Provider value={{ isHTPOpen, openHTP, closeHTP }}>
      {children}
    </HTPContext.Provider>
  )
}

export function useHTP() {
  return useContext(HTPContext)
}
