import React, { useState } from 'react'
import { useOpenBetMenu } from '../../../../hooks/useOpenBetMenu.jsx'
import '../css/Miner-auto.css'
import { useAppState } from '../../../../hooks/useState.js'
import { useAuth } from '../../../../context/AuthContext'
import { minerRun, getRunStart } from '../Page'
import { K_WAM } from './DepAndMines'
import { exit_bet_uuid } from './DepAndMines.jsx'

export default function AutoCell({ minerview: propMinerview }) {
  const { profile } = useAuth()
  const { state } = useAppState()
  const openBetMenu = useOpenBetMenu()
  const [ isAutoRunning, setIsAutoRunning ] = useState(false)

  let sb_cls = "miner-status-bar__choice miner-status-bar__choice_bet"
  let ab_cls = "miner-status-bar__choice-button miner-status-bar__choice-button_yellow"
  let hc_cls = "miner-status-bar__win hidden"
  let UUID_bool = false

  const minerview = propMinerview

  if (!profile || !state || !minerview) {
    return (
      <div className="miner-status-bar">
        <div className="miner-status-bar-content">
          <div className="miner-status-bar__choice miner-status-bar__choice_bet miner-status-bar__choice_visible">
            <div className="miner-status-bar__choice-text">
              <strong>Выберите ячейку</strong>
            </div>
            <div className="miner-status-bar__choice-text"> или </div>
            <button className="miner-status-bar__choice-button miner-status-bar__choice-button_yellow miner-status-bar__choice-button_disabled">
              <span>Автовыбор</span>
              <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className=""><path d="M368.31 91.252 74 385.562l54.155 54.155 294.31-294.31-54.155-54.155Zm-46.169 82.657 46.169-46.17 17.668 17.668-46.17 46.17-17.667-17.668ZM425.214 68.537l32.267-32.267 18.243 18.243-32.266 32.267-18.244-18.243Zm-4.194 167.368 18.242-18.242 32.876 32.874-18.243 18.243-32.875-32.875ZM243.229 58.103l18.243-18.242 32.672 32.67L275.9 90.773l-32.671-32.67Zm221.025 83.31v25.801h46.742v-25.801h-46.742ZM344.782 1.015v46.519h25.801V1l-25.801.015Z"></path></svg>
            </button>
          </div>
        </div>
      </div>
    )
  }

  if (profile?.Miner?.play) {
    UUID_bool = false
    hc_cls = "miner-status-bar__win hidden"
    sb_cls = `miner-status-bar__choice miner-status-bar__choice_bet miner-status-bar__choice_visible`
    if (getRunStart() || isAutoRunning) {
      UUID_bool = false
      hc_cls = "miner-status-bar__win hidden"
      ab_cls = `miner-status-bar__choice-button miner-status-bar__choice-button_yellow miner-status-bar__choice-button_disabled`
    } else {
      UUID_bool = false
      hc_cls = "miner-status-bar__win hidden"
      ab_cls = "miner-status-bar__choice-button miner-status-bar__choice-button_yellow"
    }
  } else {
    if (!(minerview.includes(false)) && K_WAM[2]) {
      if (exit_bet_uuid != false) {UUID_bool = true}
      hc_cls = "miner-status-bar__win miner-status-bar__win_visible"
      sb_cls = `miner-status-bar__choice miner-status-bar__choice_bet hidden`
    } else {
      UUID_bool = false
      hc_cls = "miner-status-bar__win hidden"
      sb_cls = `miner-status-bar__choice miner-status-bar__choice_bet miner-status-bar__choice_visible`
      ab_cls = `miner-status-bar__choice-button miner-status-bar__choice-button_yellow miner-status-bar__choice-button_disabled`
    }
  }

  return (
    <div className="miner-status-bar">
      <div className="miner-status-bar-content" onClick={() => {UUID_bool && openBetMenu(exit_bet_uuid)}}>
        <div className={sb_cls}>
          <div className="miner-status-bar__choice-text">
            <strong>Выберите ячейку</strong>
          </div>
          <div className="miner-status-bar__choice-text"> или </div>
          <button 
            onClick={async () => {
              if (isAutoRunning || getRunStart()) return;
              setIsAutoRunning(true);
              if (minerview && minerview.includes(false)) {
                const list = []
                for (let i = 0; i < 24; i++) {
                  if (minerview[i] === false) {
                    list.push(i)
                  }
                }
                if (list.length > 0) {
                  const randomCell = list[Math.floor(Math.random() * list.length)]
                  await minerRun(randomCell, profile, state)
                }
              }
              setIsAutoRunning(false);
            }} 
            className={ab_cls}
            disabled={getRunStart() || isAutoRunning}
          >
            <span>Автовыбор</span>
            <svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" fill="currentColor" viewBox="0 0 512 512" className=""><path d="M368.31 91.252 74 385.562l54.155 54.155 294.31-294.31-54.155-54.155Zm-46.169 82.657 46.169-46.17 17.668 17.668-46.17 46.17-17.667-17.668ZM425.214 68.537l32.267-32.267 18.243 18.243-32.266 32.267-18.244-18.243Zm-4.194 167.368 18.242-18.242 32.876 32.874-18.243 18.243-32.875-32.875ZM243.229 58.103l18.243-18.242 32.672 32.67L275.9 90.773l-32.671-32.67Zm221.025 83.31v25.801h46.742v-25.801h-46.742ZM344.782 1.015v46.519h25.801V1l-25.801.015Z"></path></svg>
          </button>
        </div>
          <div className={hc_cls}>
          <div className="miner-status-bar__win-text">Победа</div> 
          <div className="miner-status-bar__win-multiplier">
            <span>{"x" + String(K_WAM[0].toFixed(2))}</span>
          </div> 
          <div className="miner-status-bar__win-text">
            <span className="amount">
              <span>{String(K_WAM[1].toFixed(2)) + " ₽"}</span>
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}