import { useState, useEffect } from 'react';
import { saveState, getAllState, saveStateBatch, clearAllState } from '../lib/indexedDB';
import { DEFAULT_STATE } from '../lib/DEF_DATA'

export function useAppState() {
  const [state, setState] = useState(DEFAULT_STATE);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadState();
  }, []);

  const loadState = async () => {
    try {
      const all = await getAllState();
      setState({ ...DEFAULT_STATE, ...all });
    } catch (err) {
      console.error('[useAppState] Load error:', err);
      setState(DEFAULT_STATE);
    } finally {
      setLoading(false);
    }
  };

  const updateState = async (key, value) => {
    try {
      await saveState(key, value);
      setState(prev => ({ ...prev, [key]: value }));
    } catch (err) {
      console.error('[useAppState] Save error:', err);
    }
  };

  const updateStateBatch = async (newState) => {
    try {
      const dbState = { ...state, ...newState };
      await saveStateBatch(newState);
      setState(dbState);
    } catch (err) {
      console.error('[useAppState] Batch save error:', err);
    }
  };

  const updateStateWithoutDB = (newState) => {
    setState(prev => ({ ...prev, ...newState }));
  };

  const resetState = async () => {
    try {
      await clearAllState();
      setState(DEFAULT_STATE);
    } catch (err) {
      console.error('[useAppState] Reset error:', err);
    }
  };

  return {
    state,
    loading,
    updateState,
    updateStateBatch,
    updateStateWithoutDB,
    resetState,
    loadState
  };
}